(function(){
  if(window.PAGES_BUNDLE) {
    window.PAGES_BUNDLE["panel-slideout"] = "<div class=\"page-header\"><h1 class=\"ds-hero-title\">Slideout</h1></div>\n\n<!-- Tab bar -->\n<div class=\"btn-tab-bar\">\n  <button class=\"btn-tab-btn slideout-tab-btn active\" data-tab=\"design\" onclick=\"switchSlideoutTab('design')\">Design</button>\n  <button class=\"btn-tab-btn slideout-tab-btn\" data-tab=\"code\" onclick=\"switchSlideoutTab('code')\">Code</button>\n  <button class=\"btn-tab-btn slideout-tab-btn\" data-tab=\"usage\" onclick=\"switchSlideoutTab('usage')\">Usage</button>\n</div>\n\n<!-- ========== DESIGN TAB ========== -->\n<div id=\"slideout-pane-design\" class=\"btn-tab-pane slideout-tab-pane active\">\n\n  <!-- ── OVERVIEW ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Overview</div>\n    <p class=\"btn-family-desc\">Slideout panels (drawers) are surface-level containers that slide in from the edge of the viewport — typically the right side — to present contextual detail, forms, or secondary workflows without navigating away from the current page. Unlike modals, slideouts do not block the entire UI; they allow users to maintain spatial awareness of the page behind them.</p>\n\n    <div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-top:4px;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n\n      <div style=\"padding:20px 20px;background:#fff;border-right:1px solid #e2e8f0;\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\">\n          <div style=\"width:32px;height:32px;border-radius:8px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M15 3v18\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:700;color:#0f172a;\">Non-blocking</div>\n        </div>\n        <p style=\"font-size:12px;color:#64748b;margin:0;line-height:1.6;\">Content behind the drawer remains visible. Users stay oriented within the current context.</p>\n      </div>\n\n      <div style=\"padding:20px 20px;background:#f7fafc;border-right:1px solid #e2e8f0;\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\">\n          <div style=\"width:32px;height:32px;border-radius:8px;background:#e2e8f0;display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M17 8l4 4-4 4\"/><path d=\"M3 12h18\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:700;color:#0f172a;\">Edge-anchored</div>\n        </div>\n        <p style=\"font-size:12px;color:#64748b;margin:0;line-height:1.6;\">Always attached to the viewport edge. Right-side is the standard; left-side for navigation contexts.</p>\n      </div>\n\n      <div style=\"padding:20px 20px;background:#fff;border-right:1px solid #e2e8f0;\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\">\n          <div style=\"width:32px;height:32px;border-radius:8px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:700;color:#0f172a;\">Scrollable content</div>\n        </div>\n        <p style=\"font-size:12px;color:#64748b;margin:0;line-height:1.6;\">The content zone scrolls independently. Header and footer are sticky and never scroll out of view.</p>\n      </div>\n\n      <div style=\"padding:20px 20px;background:#f7fafc;\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:10px;\">\n          <div style=\"width:32px;height:32px;border-radius:8px;background:#e2e8f0;display:flex;align-items:center;justify-content:center;flex-shrink:0;\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:700;color:#0f172a;\">Task-focused</div>\n        </div>\n        <p style=\"font-size:12px;color:#64748b;margin:0;line-height:1.6;\">Best for detail views, edit forms, filters, and settings that relate directly to a selected item on the page.</p>\n      </div>\n\n    </div>\n  </div>\n\n  <!-- ── VARIANTS ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Variants</div>\n    <p class=\"btn-family-desc\">Two drawer variants cover the full range of use cases. Choose based on whether the background task needs to stay interactive while the drawer is open.</p>\n\n    <!-- ── VARIANT 1: PUSH ── -->\n    <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:0;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;margin-bottom:20px;\">\n\n      <!-- Live demo — Push -->\n      <div style=\"background:#f1f5f9;position:relative;min-height:220px;display:flex;overflow:hidden;\">\n        <!-- Page content compressed -->\n        <div style=\"flex:1;padding:20px 16px;display:flex;flex-direction:column;gap:8px;min-width:0;\">\n          <div style=\"height:9px;background:#94a3b8;border-radius:3px;width:40%;margin-bottom:4px;\"></div>\n          <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;flex-shrink:0;\">\n            <div style=\"height:28px;background:#f8fafc;border-bottom:1px solid #e2e8f0;\"></div>\n            <div style=\"height:28px;border-bottom:1px solid #f1f5f9;display:flex;align-items:center;padding:0 10px;gap:6px;\">\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:55%;\"></div>\n            </div>\n            <div style=\"height:28px;border-bottom:1px solid #f1f5f9;display:flex;align-items:center;padding:0 10px;gap:6px;\">\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:38%;\"></div>\n            </div>\n            <div style=\"height:28px;display:flex;align-items:center;padding:0 10px;gap:6px;\">\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:62%;\"></div>\n            </div>\n          </div>\n          <!-- arrow indicator -->\n          <div style=\"position:absolute;top:50%;right:-1px;transform:translateY(-50%);width:0;height:0;border-top:10px solid transparent;border-bottom:10px solid transparent;border-left:10px solid #e2e8f0;z-index:2;\"></div>\n          <div style=\"position:absolute;top:50%;right:0;transform:translateY(-50%);width:0;height:0;border-top:9px solid transparent;border-bottom:9px solid transparent;border-left:9px solid #f1f5f9;z-index:3;\"></div>\n        </div>\n        <!-- Drawer — no overlay, flush right -->\n        <div style=\"width:160px;flex-shrink:0;background:#fff;border-left:2px solid #e2e8f0;display:flex;flex-direction:column;\">\n          <div style=\"padding:12px 14px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n            <span style=\"font-size:12px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Filters</span>\n            <div style=\"width:20px;height:20px;background:#f1f5f9;border-radius:5px;display:flex;align-items:center;justify-content:center;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n            </div>\n          </div>\n          <div style=\"flex:1;padding:12px 14px;display:flex;flex-direction:column;gap:12px;\">\n            <div>\n              <div style=\"font-size:9px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:5px;\">Date Range</div>\n              <div style=\"height:26px;background:#f1f5f9;border:1px solid #e2e8f0;border-radius:5px;\"></div>\n            </div>\n            <div>\n              <div style=\"font-size:9px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:5px;\">Status</div>\n              <div style=\"display:flex;flex-direction:column;gap:5px;\">\n                <div style=\"display:flex;align-items:center;gap:6px;\">\n                  <div style=\"width:12px;height:12px;border-radius:3px;background:#1852fe;border:1.5px solid #1852fe;flex-shrink:0;display:flex;align-items:center;justify-content:center;\">\n                    <svg width=\"7\" height=\"7\" viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"2 6 5 9 10 3\"/></svg>\n                  </div>\n                  <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:70%;\"></div>\n                </div>\n                <div style=\"display:flex;align-items:center;gap:6px;\">\n                  <div style=\"width:12px;height:12px;border-radius:3px;border:1.5px solid #cbd5e1;flex-shrink:0;\"></div>\n                  <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:55%;\"></div>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div style=\"padding:10px 14px;border-top:1px solid #e2e8f0;flex-shrink:0;\">\n            <div style=\"height:26px;background:#1852fe;border-radius:5px;\"></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Description — Push -->\n      <div style=\"padding:28px 28px;background:#fff;border-left:1px solid #e2e8f0;display:flex;flex-direction:column;justify-content:center;\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:14px;\">\n          <div style=\"font-size:15px;font-weight:700;color:#0f172a;\">Inline Push</div>\n          <span style=\"font-size:11px;font-weight:600;color:#475569;background:#f1f5f9;border:1px solid #e2e8f0;padding:2px 8px;border-radius:4px;\">No overlay</span>\n        </div>\n        <ul style=\"margin:0 0 0 0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px;\">\n          <li style=\"display:flex;align-items:flex-start;gap:10px;\">\n            <div style=\"width:20px;height:20px;border-radius:5px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n            </div>\n            <span style=\"font-size:13px;color:#475569;line-height:1.55;\">Pushes and shrinks existing UI to make room — page content stays fully visible and interactive.</span>\n          </li>\n          <li style=\"display:flex;align-items:flex-start;gap:10px;\">\n            <div style=\"width:20px;height:20px;border-radius:5px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2.2\" stroke-linecap=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M15 3v18\"/></svg>\n            </div>\n            <span style=\"font-size:13px;color:#475569;line-height:1.55;\">No backdrop overlay — background remains fully lit and scrollable.</span>\n          </li>\n          <li style=\"display:flex;align-items:flex-start;gap:10px;\">\n            <div style=\"width:20px;height:20px;border-radius:5px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M9 3H5a2 2 0 0 0-2 2v4m6-6h10a2 2 0 0 1 2 2v4M9 3v18m0 0h10a2 2 0 0 0 2-2v-4M9 21H5a2 2 0 0 1-2-2v-4m0 0h18\"/></svg>\n            </div>\n            <span style=\"font-size:13px;color:#475569;line-height:1.55;\">Best for contextual workflows — filters, settings, or side panels where the user needs to reference the main content while working.</span>\n          </li>\n        </ul>\n      </div>\n    </div>\n\n    <!-- ── VARIANT 2: OVERLAY ── -->\n    <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:0;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;\">\n\n      <!-- Live demo — Overlay -->\n      <div style=\"background:#f1f5f9;position:relative;min-height:220px;overflow:hidden;\">\n        <!-- Page content behind overlay -->\n        <div style=\"position:absolute;inset:0;padding:20px 16px;\">\n          <div style=\"height:9px;background:#94a3b8;border-radius:3px;width:40%;margin-bottom:12px;opacity:0.4;\"></div>\n          <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;opacity:0.35;\">\n            <div style=\"height:28px;background:#f8fafc;border-bottom:1px solid #e2e8f0;\"></div>\n            <div style=\"height:28px;border-bottom:1px solid #f1f5f9;\"></div>\n            <div style=\"height:28px;border-bottom:1px solid #f1f5f9;\"></div>\n            <div style=\"height:28px;\"></div>\n          </div>\n        </div>\n        <!-- Dim overlay -->\n        <div style=\"position:absolute;inset:0;background:rgba(31,41,55,0.70);\"></div>\n        <!-- Drawer on top -->\n        <div style=\"position:absolute;top:12px;right:12px;bottom:12px;width:180px;background:#fff;border-radius:12px;display:flex;flex-direction:column;overflow:hidden;\">\n          <div style=\"padding:12px 14px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n            <span style=\"font-size:12px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Vessel Detail</span>\n            <div style=\"width:20px;height:20px;background:#f1f5f9;border-radius:5px;display:flex;align-items:center;justify-content:center;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n            </div>\n          </div>\n          <div style=\"flex:1;padding:12px 14px;background:#f8fafc;display:flex;flex-direction:column;gap:10px;\">\n            <div>\n              <div style=\"font-size:9px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:4px;\">Vessel</div>\n              <div style=\"font-size:11px;font-weight:600;color:#0f172a;\">MV Pacific Star</div>\n            </div>\n            <div>\n              <div style=\"font-size:9px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:4px;\">Port</div>\n              <div style=\"font-size:11px;color:#0f172a;\">Singapore</div>\n            </div>\n            <div>\n              <div style=\"font-size:9px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:4px;\">Status</div>\n              <div style=\"display:inline-flex;align-items:center;gap:4px;background:#dcfce7;border-radius:4px;padding:2px 7px;\">\n                <div style=\"width:5px;height:5px;border-radius:50%;background:#16a34a;\"></div>\n                <span style=\"font-size:10px;font-weight:600;color:#15803d;\">Active</span>\n              </div>\n            </div>\n          </div>\n          <div style=\"padding:10px 14px;border-top:1px solid #e2e8f0;display:flex;gap:6px;flex-shrink:0;\">\n            <div style=\"flex:1;height:26px;background:#f1f5f9;border-radius:5px;border:1.5px solid #e2e8f0;\"></div>\n            <div style=\"flex:1;height:26px;background:#1852fe;border-radius:5px;\"></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Description — Overlay -->\n      <div style=\"padding:28px 28px;background:#fff;border-left:1px solid #e2e8f0;display:flex;flex-direction:column;justify-content:center;\">\n        <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:14px;\">\n          <div style=\"font-size:15px;font-weight:700;color:#0f172a;\">Overlay Drawer</div>\n          <span style=\"font-size:11px;font-weight:600;color:#fff;background:#1852fe;padding:2px 8px;border-radius:4px;\">Default</span>\n        </div>\n        <ul style=\"margin:0 0 0 0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px;\">\n          <li style=\"display:flex;align-items:flex-start;gap:10px;\">\n            <div style=\"width:20px;height:20px;border-radius:5px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2.2\" stroke-linecap=\"round\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"2\"/><path d=\"M2 12h20\"/></svg>\n            </div>\n            <span style=\"font-size:13px;color:#475569;line-height:1.55;\">Appears above the UI — slides in from the right edge of the viewport over the existing content.</span>\n          </li>\n          <li style=\"display:flex;align-items:flex-start;gap:10px;\">\n            <div style=\"width:20px;height:20px;border-radius:5px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2.2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 8v4l3 3\"/></svg>\n            </div>\n            <span style=\"font-size:13px;color:#475569;line-height:1.55;\">Semi-transparent dark backdrop dims the page — focuses attention on the drawer without fully blocking context.</span>\n          </li>\n          <li style=\"display:flex;align-items:flex-start;gap:10px;\">\n            <div style=\"width:20px;height:20px;border-radius:5px;background:#f1f5f9;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;\">\n              <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M9 3H5a2 2 0 0 0-2 2v4m6-6h10a2 2 0 0 1 2 2v4M9 3v18m0 0h10a2 2 0 0 0 2-2v-4M9 21H5a2 2 0 0 1-2-2v-4m0 0h18\"/></svg>\n            </div>\n            <span style=\"font-size:13px;color:#475569;line-height:1.55;\">Used for focused tasks — editing a record, reviewing details, or completing a workflow that requires full attention.</span>\n          </li>\n        </ul>\n      </div>\n    </div>\n\n  </div>\n\n  <!-- ── ANATOMY ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Anatomy</div>\n    <p class=\"btn-family-desc\" style=\"margin-bottom:28px;\">Every slideout is built from three zones: <strong>Header</strong>, <strong>Content</strong>, and <strong>Footer</strong> (optional). The Header and Footer are position-sticky — they remain visible while the Content zone scrolls independently.</p>\n\n    <!-- Anatomy diagram -->\n    <div style=\"background:#525252;border-radius:12px;padding:32px 0;margin-bottom:32px;overflow:hidden;position:relative;\">\n\n      <!-- Overlay label badge — bottom left -->\n      <div style=\"position:absolute;bottom:20px;left:20px;z-index:4;display:flex;align-items:center;gap:8px;\">\n        <div style=\"width:28px;height:28px;border-radius:50%;background:#da1e28;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0;\">5</div>\n        <div style=\"width:32px;height:1.5px;background:rgba(218,30,40,0.65);\"></div>\n      </div>\n\n      <div style=\"overflow-x:auto;\">\n        <div style=\"min-width:580px;display:flex;align-items:flex-start;padding:0 16px;gap:0;\">\n\n          <!-- LEFT annotation column\n               Zone heights: Header=56px · Content=240px · Footer=56px\n               Badge centers: 1→28  2→176  3→380 -->\n          <div style=\"width:100px;flex-shrink:0;display:flex;flex-direction:column;\">\n\n            <!-- 1 · Header — center at 28px -->\n            <div style=\"margin-top:14px;display:flex;align-items:center;\">\n              <div style=\"width:28px;height:28px;border-radius:50%;background:#da1e28;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0;\">1</div>\n              <div style=\"flex:1;height:1.5px;background:rgba(218,30,40,0.65);\"></div>\n            </div>\n\n            <!-- spacer to content center: 56 + 120 - 14 - 28 = 134px -->\n            <div style=\"height:134px;\"></div>\n\n            <!-- 2 · Content — center at 176px -->\n            <div style=\"display:flex;align-items:center;\">\n              <div style=\"width:28px;height:28px;border-radius:50%;background:#da1e28;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0;\">2</div>\n              <div style=\"flex:1;height:1.5px;background:rgba(218,30,40,0.65);\"></div>\n            </div>\n\n            <!-- spacer to footer center: 240 - 120 - 28 = 92px -->\n            <div style=\"height:92px;\"></div>\n\n            <!-- 3 · Footer — center at 380px -->\n            <div style=\"display:flex;align-items:center;\">\n              <div style=\"width:28px;height:28px;border-radius:50%;background:#da1e28;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0;\">3</div>\n              <div style=\"flex:1;height:1.5px;background:rgba(218,30,40,0.65);\"></div>\n            </div>\n\n          </div>\n\n          <!-- Page context (blurred) + drawer -->\n          <div style=\"flex:1;min-width:0;display:flex;gap:0;position:relative;\">\n\n            <!-- Backdrop page -->\n            <div style=\"flex:1;background:rgba(255,255,255,0.08);border-radius:10px 0 0 10px;padding:20px;display:flex;flex-direction:column;gap:10px;opacity:0.4;\">\n              <div style=\"height:10px;background:#fff;border-radius:3px;width:35%;\"></div>\n              <div style=\"height:200px;background:rgba(255,255,255,0.15);border-radius:6px;\"></div>\n            </div>\n\n            <!-- Drawer panel -->\n            <div style=\"width:260px;flex-shrink:0;background:#fff;border-radius:12px;overflow:hidden;display:flex;flex-direction:column;\">\n\n              <!-- ① Header (56px) -->\n              <div style=\"padding:16px 18px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #e2e8f0;min-height:56px;box-sizing:border-box;flex-shrink:0;\">\n                <div style=\"font-size:15px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;line-height:1.2;\">Vessel Detail</div>\n                <button style=\"width:28px;height:28px;background:#f1f5f9;border:none;cursor:default;display:flex;align-items:center;justify-content:center;color:#64748b;border-radius:6px;flex-shrink:0;\" aria-hidden=\"true\">\n                  <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n                </button>\n              </div>\n\n              <!-- ② Content (240px) — scrollable -->\n              <div style=\"flex:1;padding:18px;background:#f8fafc;overflow:hidden;min-height:240px;max-height:240px;\">\n                <div style=\"display:flex;flex-direction:column;gap:14px;\">\n                  <div>\n                    <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.07em;margin-bottom:5px;\">Vessel Name</div>\n                    <div style=\"font-size:13px;font-weight:600;color:#0f172a;\">MV Pacific Star</div>\n                  </div>\n                  <div>\n                    <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.07em;margin-bottom:5px;\">IMO Number</div>\n                    <div style=\"font-size:13px;color:#0f172a;\">9 234 567</div>\n                  </div>\n                  <div>\n                    <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.07em;margin-bottom:5px;\">Port of Registry</div>\n                    <div style=\"font-size:13px;color:#0f172a;\">Singapore</div>\n                  </div>\n                  <div>\n                    <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.07em;margin-bottom:5px;\">Status</div>\n                    <div style=\"display:inline-flex;align-items:center;gap:5px;background:#dcfce7;border-radius:5px;padding:3px 9px;\">\n                      <div style=\"width:6px;height:6px;border-radius:50%;background:#16a34a;\"></div>\n                      <span style=\"font-size:11px;font-weight:600;color:#15803d;\">Active</span>\n                    </div>\n                  </div>\n                  <div>\n                    <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.07em;margin-bottom:5px;\">Last Updated</div>\n                    <div style=\"font-size:13px;color:#0f172a;\">04 May 2026 · 09:14</div>\n                  </div>\n                </div>\n              </div>\n\n              <!-- ③ Footer (56px) — optional -->\n              <div style=\"padding:12px 18px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end;gap:8px;background:#fff;flex-shrink:0;min-height:56px;box-sizing:border-box;align-items:center;\">\n                <button style=\"display:inline-flex;align-items:center;padding:8px 14px;border:1.5px solid #1852fe;background:#fff;color:#1852fe;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:'Gilroy',sans-serif;\">Edit</button>\n                <button style=\"display:inline-flex;align-items:center;padding:8px 14px;border:none;background:#1852fe;color:#fff;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:'Gilroy',sans-serif;\">Save</button>\n              </div>\n\n            </div>\n          </div>\n\n          <!-- RIGHT annotation column -->\n          <div style=\"width:100px;flex-shrink:0;display:flex;flex-direction:column;\">\n\n            <!-- 4 · Close button — align with header center -->\n            <div style=\"margin-top:14px;display:flex;align-items:center;flex-direction:row-reverse;\">\n              <div style=\"width:28px;height:28px;border-radius:50%;background:#da1e28;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;flex-shrink:0;\">4</div>\n              <div style=\"flex:1;height:1.5px;background:rgba(218,30,40,0.65);\"></div>\n            </div>\n\n          </div>\n\n        </div>\n      </div>\n    </div>\n\n    <!-- Legend -->\n    <p style=\"font-size:14px;color:#475569;line-height:1.7;margin:0 0 16px;\">The drawer always renders Header → Content → Footer in that order. Header and Footer are <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:4px;font-size:12px;\">position:sticky</code> so they remain fixed while Content scrolls.</p>\n    <ol style=\"margin:0 0 0 20px;padding:0;font-size:14px;color:#475569;line-height:2.2;\">\n      <li><strong style=\"color:#0f172a;\">Header</strong>: Drawer title + close ×. Fixed height (56px), never scrolls. Separated from Content by a 1px divider.</li>\n      <li><strong style=\"color:#0f172a;\">Content</strong>: The scrollable work area — detail views, forms, filter panels. Gets <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:4px;font-size:11px;\">overflow-y: auto</code> automatically.</li>\n      <li><strong style=\"color:#0f172a;\">Footer <span style=\"font-size:11px;font-weight:600;color:#1852fe;background:#eff6ff;padding:1px 6px;border-radius:4px;vertical-align:middle;\">optional</span></strong>: Right-aligned action buttons. Omit the prop for read-only drawers. When present, primary action is always rightmost.</li>\n      <li><strong style=\"color:#0f172a;\">Close ×</strong>: Dismisses the drawer. Always present in the header's trailing slot. Also closeable via Escape key or overlay click.</li>\n      <li><strong style=\"color:#0f172a;\">Overlay</strong>: Semi-transparent backdrop (Overlay variant only). Clicking it closes the drawer.</li>\n    </ol>\n  </div>\n\n  <!-- ── SIZES ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Sizes</div>\n    <p class=\"btn-family-desc\">Drawer width is fixed and set at the time of invocation. Choose the smallest width that comfortably accommodates your content. Never use Large on viewports narrower than 768px.</p>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:24px;\">\n\n      <!-- Narrow -->\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#0f172a;\">Narrow</span>\n          <span style=\"font-family:'SF Mono',monospace;font-size:12px;color:#64748b;\">320px</span>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <div style=\"height:4px;background:#e2e8f0;border-radius:2px;width:40%;margin-bottom:12px;position:relative;overflow:hidden;\">\n            <div style=\"position:absolute;inset:0;background:linear-gradient(90deg,#1852fe,#5b8fff);border-radius:2px;\"></div>\n          </div>\n          <p style=\"font-size:12px;color:#475569;margin:0;line-height:1.6;\">Status panels, simple detail views, short filter sets.</p>\n        </div>\n      </div>\n\n      <!-- Default -->\n      <div style=\"background:#fff;border:2px solid #1852fe;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#1852fe;\">Default <span style=\"font-size:10px;font-weight:600;color:#fff;background:#1852fe;padding:1px 5px;border-radius:3px;margin-left:4px;\">std</span></span>\n          <span style=\"font-family:'SF Mono',monospace;font-size:12px;color:#64748b;\">400px</span>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <div style=\"height:4px;background:#e2e8f0;border-radius:2px;width:55%;margin-bottom:12px;position:relative;overflow:hidden;\">\n            <div style=\"position:absolute;inset:0;background:linear-gradient(90deg,#1852fe,#5b8fff);border-radius:2px;\"></div>\n          </div>\n          <p style=\"font-size:12px;color:#475569;margin:0;line-height:1.6;\">Edit forms, vessel/voyage detail, user profile, settings panels.</p>\n        </div>\n      </div>\n\n      <!-- Wide -->\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#0f172a;\">Wide</span>\n          <span style=\"font-family:'SF Mono',monospace;font-size:12px;color:#64748b;\">560px</span>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <div style=\"height:4px;background:#e2e8f0;border-radius:2px;width:70%;margin-bottom:12px;position:relative;overflow:hidden;\">\n            <div style=\"position:absolute;inset:0;background:linear-gradient(90deg,#1852fe,#5b8fff);border-radius:2px;\"></div>\n          </div>\n          <p style=\"font-size:12px;color:#475569;margin:0;line-height:1.6;\">Multi-section edit forms, document previews, complex filter panels.</p>\n        </div>\n      </div>\n\n      <!-- Large -->\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#0f172a;\">Large</span>\n          <span style=\"font-family:'SF Mono',monospace;font-size:12px;color:#64748b;\">800px</span>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <div style=\"height:4px;background:#e2e8f0;border-radius:2px;width:100%;margin-bottom:12px;position:relative;overflow:hidden;\">\n            <div style=\"position:absolute;inset:0;background:linear-gradient(90deg,#1852fe,#5b8fff);border-radius:2px;\"></div>\n          </div>\n          <p style=\"font-size:12px;color:#475569;margin:0;line-height:1.6;\">Data review side-by-side, report generation, step-heavy flows. Use sparingly.</p>\n        </div>\n      </div>\n\n    </div>\n\n    <div style=\"padding:12px 16px;background:#fffbeb;border-left:3px solid #f59e0b;border-radius:0 8px 8px 0;font-size:13px;color:#92400e;\">\n      <strong>Rule:</strong> Drawer width must never exceed viewport width minus 48px. On mobile, the drawer always spans 100% of the viewport width regardless of the configured size prop.\n    </div>\n  </div>\n\n  <!-- ── STATES ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">States</div>\n    <p class=\"btn-family-desc\">The drawer content zone has five distinct states. The Header and Footer zones are always rendered regardless of the content state — they provide consistent affordances for dismissal and action.</p>\n\n    <!-- Default State -->\n    <div class=\"btn-sub-label\" style=\"margin-bottom:16px;\">Default</div>\n    <div style=\"display:flex;gap:16px;align-items:flex-start;margin-bottom:28px;flex-wrap:wrap;\">\n      <div style=\"width:240px;flex-shrink:0;background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:14px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Vessel Detail</span>\n          <div style=\"width:24px;height:24px;background:#f1f5f9;border-radius:6px;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n          </div>\n        </div>\n        <div style=\"padding:16px;background:#f8fafc;display:flex;flex-direction:column;gap:12px;\">\n          <div>\n            <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:4px;\">Vessel Name</div>\n            <div style=\"font-size:13px;font-weight:600;color:#0f172a;\">MV Pacific Star</div>\n          </div>\n          <div>\n            <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:4px;\">Status</div>\n            <div style=\"display:inline-flex;align-items:center;gap:5px;background:#dcfce7;border-radius:5px;padding:3px 9px;\">\n              <div style=\"width:6px;height:6px;border-radius:50%;background:#16a34a;\"></div>\n              <span style=\"font-size:11px;font-weight:600;color:#15803d;\">Active</span>\n            </div>\n          </div>\n          <div>\n            <div style=\"font-size:10px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:4px;\">Port</div>\n            <div style=\"font-size:13px;color:#0f172a;\">Singapore</div>\n          </div>\n        </div>\n        <div style=\"padding:10px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end;gap:8px;\">\n          <button style=\"padding:7px 13px;border:1.5px solid #1852fe;background:#fff;color:#1852fe;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\">Edit</button>\n          <button style=\"padding:7px 13px;border:none;background:#1852fe;color:#fff;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\">Save</button>\n        </div>\n      </div>\n      <div style=\"flex:1;min-width:200px;padding-top:4px;\">\n        <p style=\"font-size:13px;color:#475569;line-height:1.7;margin:0 0 8px;\">The default state renders content normally. Header shows title and close button; Content zone shows the data; Footer (if present) shows action buttons.</p>\n        <ul style=\"margin:0 0 0 16px;padding:0;font-size:13px;color:#475569;line-height:2;\">\n          <li>Header border-bottom: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#e2e8f0 1px solid</code></li>\n          <li>Content background: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#f8fafc</code></li>\n          <li>Footer border-top: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#e2e8f0 1px solid</code></li>\n        </ul>\n      </div>\n    </div>\n\n    <hr class=\"btn-family-divider\">\n\n    <!-- Loading State -->\n    <div class=\"btn-sub-label\" style=\"margin-bottom:16px;\">Loading</div>\n    <div style=\"display:flex;gap:16px;align-items:flex-start;margin-bottom:28px;flex-wrap:wrap;\">\n      <div style=\"width:240px;flex-shrink:0;background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:14px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Vessel Detail</span>\n          <div style=\"width:24px;height:24px;background:#f1f5f9;border-radius:6px;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n          </div>\n        </div>\n        <div style=\"padding:16px;background:#f8fafc;display:flex;flex-direction:column;gap:14px;\">\n          <!-- Skeleton rows -->\n          <div>\n            <div style=\"height:8px;background:#e2e8f0;border-radius:3px;width:40%;margin-bottom:7px;background:linear-gradient(90deg,#e2e8f0 25%,#f1f5f9 50%,#e2e8f0 75%);background-size:200% 100%;animation:shimmer 1.4s infinite;\"></div>\n            <div style=\"height:11px;background:#e2e8f0;border-radius:3px;width:70%;background:linear-gradient(90deg,#e2e8f0 25%,#f1f5f9 50%,#e2e8f0 75%);background-size:200% 100%;animation:shimmer 1.4s infinite;\"></div>\n          </div>\n          <div>\n            <div style=\"height:8px;background:#e2e8f0;border-radius:3px;width:30%;margin-bottom:7px;background:linear-gradient(90deg,#e2e8f0 25%,#f1f5f9 50%,#e2e8f0 75%);background-size:200% 100%;animation:shimmer 1.4s 0.1s infinite;\"></div>\n            <div style=\"height:11px;background:#e2e8f0;border-radius:3px;width:50%;background:linear-gradient(90deg,#e2e8f0 25%,#f1f5f9 50%,#e2e8f0 75%);background-size:200% 100%;animation:shimmer 1.4s 0.1s infinite;\"></div>\n          </div>\n          <div>\n            <div style=\"height:8px;background:#e2e8f0;border-radius:3px;width:35%;margin-bottom:7px;background:linear-gradient(90deg,#e2e8f0 25%,#f1f5f9 50%,#e2e8f0 75%);background-size:200% 100%;animation:shimmer 1.4s 0.2s infinite;\"></div>\n            <div style=\"height:11px;background:#e2e8f0;border-radius:3px;width:60%;background:linear-gradient(90deg,#e2e8f0 25%,#f1f5f9 50%,#e2e8f0 75%);background-size:200% 100%;animation:shimmer 1.4s 0.2s infinite;\"></div>\n          </div>\n        </div>\n        <div style=\"padding:10px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end;gap:8px;\">\n          <button style=\"padding:7px 13px;border:1.5px solid #e2e8f0;background:#fff;color:#94a3b8;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\" disabled>Edit</button>\n          <button style=\"padding:7px 13px;border:none;background:#94a3b8;color:#fff;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\" disabled>Save</button>\n        </div>\n      </div>\n      <div style=\"flex:1;min-width:200px;padding-top:4px;\">\n        <p style=\"font-size:13px;color:#475569;line-height:1.7;margin:0 0 8px;\">Shown when content is being fetched. The Header renders with the title (if known) or a skeleton placeholder. Footer buttons are present but disabled. Content zone renders skeleton rows matching the expected data shape.</p>\n        <ul style=\"margin:0 0 0 16px;padding:0;font-size:13px;color:#475569;line-height:2;\">\n          <li>Skeleton uses shimmer animation: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#e2e8f0 → #f1f5f9 → #e2e8f0</code></li>\n          <li>Footer action buttons: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">disabled + opacity 0.5</code></li>\n          <li>No spinner inside content — use skeleton rows instead</li>\n        </ul>\n      </div>\n    </div>\n\n    <hr class=\"btn-family-divider\">\n\n    <!-- Empty State -->\n    <div class=\"btn-sub-label\" style=\"margin-bottom:16px;\">Empty</div>\n    <div style=\"display:flex;gap:16px;align-items:flex-start;margin-bottom:28px;flex-wrap:wrap;\">\n      <div style=\"width:240px;flex-shrink:0;background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:14px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Activity Log</span>\n          <div style=\"width:24px;height:24px;background:#f1f5f9;border-radius:6px;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n          </div>\n        </div>\n        <div style=\"padding:32px 16px;background:#f8fafc;display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;\">\n          <div style=\"width:48px;height:48px;border-radius:50%;background:#e2e8f0;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#94a3b8\" stroke-width=\"1.5\" stroke-linecap=\"round\"><path d=\"M9 11l3 3L22 4\"/><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:600;color:#0f172a;\">No activity yet</div>\n          <div style=\"font-size:12px;color:#64748b;line-height:1.5;\">Actions on this vessel will appear here once recorded.</div>\n        </div>\n        <div style=\"padding:10px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:center;\">\n          <button style=\"padding:7px 16px;border:none;background:#1852fe;color:#fff;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\">Add entry</button>\n        </div>\n      </div>\n      <div style=\"flex:1;min-width:200px;padding-top:4px;\">\n        <p style=\"font-size:13px;color:#475569;line-height:1.7;margin:0 0 8px;\">Content loaded successfully but there is nothing to show. Use an icon, a short message, and — when possible — a single primary action that helps the user get started.</p>\n        <ul style=\"margin:0 0 0 16px;padding:0;font-size:13px;color:#475569;line-height:2;\">\n          <li>Icon should be relevant to the content type</li>\n          <li>Message: one heading + one short explanatory line</li>\n          <li>CTA is optional — omit when user cannot create content from this surface</li>\n        </ul>\n      </div>\n    </div>\n\n    <hr class=\"btn-family-divider\">\n\n    <!-- Error State -->\n    <div class=\"btn-sub-label\" style=\"margin-bottom:16px;\">Error</div>\n    <div style=\"display:flex;gap:16px;align-items:flex-start;margin-bottom:28px;flex-wrap:wrap;\">\n      <div style=\"width:240px;flex-shrink:0;background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:14px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Vessel Detail</span>\n          <div style=\"width:24px;height:24px;background:#f1f5f9;border-radius:6px;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n          </div>\n        </div>\n        <div style=\"padding:32px 16px;background:#fff5f5;display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;border-bottom:1px solid #fee2e2;\">\n          <div style=\"width:48px;height:48px;border-radius:50%;background:#fee2e2;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"1.5\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:600;color:#991b1b;\">Failed to load</div>\n          <div style=\"font-size:12px;color:#b45309;line-height:1.5;\">Could not retrieve vessel data. Check your connection and try again.</div>\n        </div>\n        <div style=\"padding:10px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:center;\">\n          <button style=\"padding:7px 16px;border:1.5px solid #dc2626;background:#fff;color:#dc2626;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\">Retry</button>\n        </div>\n      </div>\n      <div style=\"flex:1;min-width:200px;padding-top:4px;\">\n        <p style=\"font-size:13px;color:#475569;line-height:1.7;margin:0 0 8px;\">Shown when the content fetch fails. Use a red-tinted icon, a clear failure heading, and a specific message. Always provide a Retry action in the footer.</p>\n        <ul style=\"margin:0 0 0 16px;padding:0;font-size:13px;color:#475569;line-height:2;\">\n          <li>Content background: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#fff5f5</code></li>\n          <li>Icon circle: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#fee2e2</code></li>\n          <li>Footer: single \"Retry\" secondary-danger button, centred</li>\n          <li>Message must name the failure — avoid generic \"Something went wrong\"</li>\n        </ul>\n      </div>\n    </div>\n\n    <hr class=\"btn-family-divider\">\n\n    <!-- Success State -->\n    <div class=\"btn-sub-label\" style=\"margin-bottom:16px;\">Success</div>\n    <div style=\"display:flex;gap:16px;align-items:flex-start;margin-bottom:4px;flex-wrap:wrap;\">\n      <div style=\"width:240px;flex-shrink:0;background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,0.08);\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:14px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Vessel Detail</span>\n          <div style=\"width:24px;height:24px;background:#f1f5f9;border-radius:6px;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n          </div>\n        </div>\n        <div style=\"padding:32px 16px;background:#f0fdf4;display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;border-bottom:1px solid #bbf7d0;\">\n          <div style=\"width:48px;height:48px;border-radius:50%;background:#dcfce7;display:flex;align-items:center;justify-content:center;\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"1.8\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n          </div>\n          <div style=\"font-size:13px;font-weight:600;color:#15803d;\">Changes saved</div>\n          <div style=\"font-size:12px;color:#166534;line-height:1.5;\">Vessel record updated successfully.</div>\n        </div>\n        <div style=\"padding:10px 16px;border-top:1px solid #e2e8f0;display:flex;justify-content:center;\">\n          <button style=\"padding:7px 16px;border:none;background:#1852fe;color:#fff;font-size:12px;font-weight:600;border-radius:6px;cursor:default;font-family:inherit;\">Close</button>\n        </div>\n      </div>\n      <div style=\"flex:1;min-width:200px;padding-top:4px;\">\n        <p style=\"font-size:13px;color:#475569;line-height:1.7;margin:0 0 8px;\">Shown briefly after a successful action. The drawer auto-dismisses after 1.5 s unless the user interacts. A toast notification also fires simultaneously so the confirmation persists after the drawer closes.</p>\n        <ul style=\"margin:0 0 0 16px;padding:0;font-size:13px;color:#475569;line-height:2;\">\n          <li>Content background: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#f0fdf4</code></li>\n          <li>Icon circle: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">#dcfce7</code></li>\n          <li>Auto-dismiss delay: <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:3px;font-size:11px;\">1500ms</code></li>\n          <li>Always pair with a toast — the drawer close discards the confirmation</li>\n        </ul>\n      </div>\n    </div>\n\n  </div>\n\n  <!-- ── INTERACTION BEHAVIOUR ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Interaction Behaviour</div>\n    <p class=\"btn-family-desc\">Slideouts follow a consistent set of interaction rules regardless of variant or content type. These rules ensure predictable behaviour across all surfaces where drawers appear.</p>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px;\">\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;display:flex;align-items:center;gap:8px;\">\n          <kbd style=\"font-family:var(--font-sans);font-size:11px;background:#f1f5f9;border:1px solid #e2e8f0;border-radius:4px;padding:1px 6px;color:#334154;\">Esc</kbd> Close\n        </div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">Pressing Escape always closes the drawer. If the user has unsaved changes, show a confirmation prompt before discarding.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">Overlay click — close</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">Clicking the overlay backdrop closes the drawer (Overlay variant). Disable with <code style=\"font-size:11px;background:#f1f5f9;padding:1px 4px;border-radius:3px;\">maskClosable={false}</code> when unsaved changes exist.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">Close × button</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">Always present in the header trailing slot. Clicking it closes the drawer unconditionally. Label with <code style=\"font-size:11px;background:#f1f5f9;padding:1px 4px;border-radius:3px;\">aria-label=\"Close panel\"</code>.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">Focus trap</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">Keyboard focus is trapped inside the drawer while open. Tab and Shift+Tab cycle through interactive elements within the panel only. Focus moves to the first focusable element on open.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">Scroll isolation</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">The page body scroll is locked while an Overlay drawer is open. Push and Inline drawers do not lock body scroll — the page content alongside remains scrollable.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">One drawer at a time</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">Never stack drawers. If a secondary action needs confirmation, use a modal on top of the open drawer. Nesting drawers creates confusing layering and breaks the focus trap.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">Unsaved changes guard</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">When the drawer contains an edit form with unsaved changes, intercept close attempts (Esc, overlay, × button) and show a confirmation modal: \"Discard changes?\" with Discard + Keep editing actions.</p>\n      </div>\n\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px 20px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:6px;\">Focus return</div>\n        <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.65;\">On close, keyboard focus must return to the element that triggered the drawer open. Maintain a ref to the trigger and call <code style=\"font-size:11px;background:#f1f5f9;padding:1px 4px;border-radius:3px;\">.focus()</code> after the exit animation completes.</p>\n      </div>\n\n    </div>\n  </div>\n\n  <!-- ── MOTION / ANIMATION ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Motion &amp; Animation</div>\n    <p class=\"btn-family-desc\">Drawers use a horizontal slide from the edge combined with an opacity fade. The enter curve is a deceleration easing (fast start, soft land) and the exit is an acceleration easing (gentle start, fast exit). Both curves come from the Carbon Design System expressive motion vocabulary.</p>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:14px;margin-bottom:24px;\">\n\n      <div style=\"padding:18px 20px;background:#fff;border:1px solid #e2e8f0;border-radius:10px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:10px;\">Enter <span style=\"font-weight:400;color:#64748b;\">· 300ms</span></div>\n        <div style=\"font-size:12px;color:#475569;line-height:2;margin-bottom:8px;\">\n          <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">opacity</span> 0 → 1<br>\n          <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">translateX</span> 100% → 0\n        </div>\n        <code style=\"font-size:11px;font-family:'SF Mono',monospace;background:#f1f5f9;padding:5px 8px;border-radius:4px;display:block;color:#334154;\">cubic-bezier(0, 0, 0.3, 1)</code>\n      </div>\n\n      <div style=\"padding:18px 20px;background:#fff;border:1px solid #e2e8f0;border-radius:10px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:10px;\">Exit <span style=\"font-weight:400;color:#64748b;\">· 250ms</span></div>\n        <div style=\"font-size:12px;color:#475569;line-height:2;margin-bottom:8px;\">\n          <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">opacity</span> 1 → 0<br>\n          <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">translateX</span> 0 → 100%\n        </div>\n        <code style=\"font-size:11px;font-family:'SF Mono',monospace;background:#f1f5f9;padding:5px 8px;border-radius:4px;display:block;color:#334154;\">cubic-bezier(0.4, 0, 1, 1)</code>\n      </div>\n\n      <div style=\"padding:18px 20px;background:#fff;border:1px solid #e2e8f0;border-radius:10px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:10px;\">Overlay enter</div>\n        <div style=\"font-size:12px;color:#475569;line-height:2;margin-bottom:8px;\">\n          Enter: <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">300ms</span> same easing<br>\n          Exit: <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">250ms</span> ease-in\n        </div>\n        <div style=\"font-size:11px;color:#94a3b8;\">Always synchronised with the drawer panel animation.</div>\n      </div>\n\n      <div style=\"padding:18px 20px;background:#fff;border:1px solid #e2e8f0;border-radius:10px;\">\n        <div style=\"font-size:12px;font-weight:700;color:#0f172a;margin-bottom:10px;\">Push shift <span style=\"font-weight:400;color:#64748b;\">· 300ms</span></div>\n        <div style=\"font-size:12px;color:#475569;line-height:2;margin-bottom:8px;\">\n          <span style=\"font-family:'SF Mono',monospace;font-size:11px;background:#f1f5f9;padding:1px 5px;border-radius:3px;\">translateX</span> 0 → −width<br>\n          Page content and drawer move in sync\n        </div>\n        <code style=\"font-size:11px;font-family:'SF Mono',monospace;background:#f1f5f9;padding:5px 8px;border-radius:4px;display:block;color:#334154;\">cubic-bezier(0, 0, 0.3, 1)</code>\n      </div>\n\n    </div>\n\n    <!-- Animation preview -->\n    <div style=\"background:#111827;border-radius:12px;overflow:hidden;\">\n      <div style=\"padding:14px 20px;border-bottom:1px solid rgba(255,255,255,0.07);display:flex;align-items:center;justify-content:space-between;\">\n        <div style=\"display:flex;align-items:center;gap:10px;\">\n          <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\" stroke-linecap=\"round\"><polygon points=\"5 3 19 12 5 21 5 3\"/></svg>\n          <span style=\"font-size:12px;font-weight:600;color:#94a3b8;text-transform:uppercase;letter-spacing:0.07em;\">Animation Preview · loops automatically</span>\n        </div>\n        <button onclick=\"replaySlideoutAnimPreview()\" style=\"font-size:11px;font-weight:600;color:#60a5fa;background:rgba(96,165,250,0.1);border:1px solid rgba(96,165,250,0.25);border-radius:6px;padding:5px 12px;cursor:pointer;font-family:inherit;letter-spacing:0.02em;\">↺ Replay</button>\n      </div>\n      <div style=\"position:relative;height:240px;overflow:hidden;background:linear-gradient(135deg,#0f172a 0%,#1e293b 100%);\">\n        <!-- Overlay fade -->\n        <div id=\"sd-anim-overlay\" style=\"position:absolute;inset:0;background:rgba(31,41,55,0.55);animation:gs-sd-overlay-loop 3.6s linear infinite;\"></div>\n        <!-- Sliding drawer -->\n        <div style=\"position:absolute;inset:0;display:flex;align-items:stretch;overflow:hidden;\">\n          <div style=\"flex:1;\"></div>\n          <div id=\"sd-anim-drawer\" style=\"width:160px;background:#fff;box-shadow:-8px 0 32px rgba(0,0,0,0.4);display:flex;flex-direction:column;animation:gs-sd-drawer-loop 3.6s linear infinite;\">\n            <div style=\"padding:12px 14px;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n              <div style=\"font-size:12px;font-weight:700;color:#001e4c;font-family:'Gilroy',sans-serif;\">Detail</div>\n              <div style=\"width:18px;height:18px;background:#f1f5f9;border-radius:4px;display:flex;align-items:center;justify-content:center;\">\n                <svg width=\"9\" height=\"9\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n              </div>\n            </div>\n            <div style=\"flex:1;padding:12px 14px;display:flex;flex-direction:column;gap:8px;background:#f8fafc;\">\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:60%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:80%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:45%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:70%;\"></div>\n            </div>\n            <div style=\"padding:8px 14px;border-top:1px solid #e2e8f0;display:flex;justify-content:flex-end;gap:6px;flex-shrink:0;\">\n              <div style=\"height:24px;width:48px;background:#f1f5f9;border-radius:5px;border:1.5px solid #e2e8f0;\"></div>\n              <div style=\"height:24px;width:48px;background:#1852fe;border-radius:5px;\"></div>\n            </div>\n          </div>\n        </div>\n        <!-- Timing labels -->\n        <div style=\"position:absolute;bottom:0;left:0;right:0;padding:0 20px 14px;display:flex;justify-content:center;gap:20px;align-items:center;\">\n          <div style=\"display:flex;align-items:center;gap:6px;\">\n            <div style=\"width:8px;height:8px;border-radius:50%;background:#34d399;\"></div>\n            <span style=\"font-size:11px;color:rgba(255,255,255,0.45);\">Enter · 300ms · cubic-bezier(0, 0, 0.3, 1)</span>\n          </div>\n          <div style=\"width:1px;height:12px;background:rgba(255,255,255,0.12);\"></div>\n          <div style=\"display:flex;align-items:center;gap:6px;\">\n            <div style=\"width:8px;height:8px;border-radius:50%;background:#f87171;\"></div>\n            <span style=\"font-size:11px;color:rgba(255,255,255,0.45);\">Exit · 250ms · cubic-bezier(0.4, 0, 1, 1)</span>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Keyframes -->\n    <div style=\"margin-top:16px;background:#1e293b;border-radius:10px;padding:16px 20px;\">\n      <div style=\"font-size:11px;font-weight:600;color:#94a3b8;margin-bottom:10px;text-transform:uppercase;letter-spacing:0.07em;\">CSS Keyframes</div>\n      <pre style=\"margin:0;font-size:12px;font-family:'SF Mono',monospace;color:#e2e8f0;line-height:1.8;white-space:pre-wrap;\">@keyframes gs-drawer-in {\n  from { opacity: 0; transform: translateX(100%); }\n  to   { opacity: 1; transform: translateX(0);    }\n}\n@keyframes gs-drawer-out {\n  from { opacity: 1; transform: translateX(0);    }\n  to   { opacity: 0; transform: translateX(100%); }\n}\n@keyframes gs-sd-overlay-in  { from { opacity: 0; } to { opacity: 1; } }\n@keyframes gs-sd-overlay-out { from { opacity: 1; } to { opacity: 0; } }</pre>\n    </div>\n\n    <div style=\"margin-top:14px;padding:12px 16px;background:#fffbeb;border-left:3px solid #f59e0b;border-radius:0 8px 8px 0;font-size:13px;color:#92400e;\">\n      <strong>Reduced motion:</strong> Honour <code style=\"font-size:11px;background:rgba(0,0,0,0.06);padding:1px 5px;border-radius:3px;\">prefers-reduced-motion: reduce</code>. Skip the translate animation and use opacity-only transition at 150ms.\n    </div>\n  </div>\n\n  <!-- ── RESPONSIVE BEHAVIOUR ── -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Responsive Behaviour</div>\n    <p class=\"btn-family-desc\">Drawer sizing and positioning adapt based on the available viewport width. The same drawer component renders differently across breakpoints with no configuration needed beyond the base <code style=\"background:#f1f5f9;padding:1px 5px;border-radius:4px;font-size:12px;\">width</code> prop.</p>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px;margin-bottom:20px;\">\n\n      <!-- Desktop -->\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#0f172a;\">Desktop</span>\n          <span style=\"font-size:11px;color:#64748b;font-family:'SF Mono',monospace;\">≥ 1024px</span>\n        </div>\n        <!-- Preview -->\n        <div style=\"padding:14px;background:#e8edf5;border-bottom:1px solid #e2e8f0;\">\n          <div style=\"background:#fff;border-radius:6px;overflow:hidden;display:flex;height:80px;border:1px solid #e2e8f0;\">\n            <div style=\"flex:1;padding:8px;opacity:0.4;\">\n              <div style=\"height:6px;background:#94a3b8;border-radius:2px;width:40%;margin-bottom:6px;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:70%;margin-bottom:6px;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:55%;\"></div>\n            </div>\n            <div style=\"width:90px;background:#f8fafc;border-left:1px solid #e2e8f0;padding:8px;display:flex;flex-direction:column;gap:5px;\">\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:75%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:55%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:65%;\"></div>\n            </div>\n          </div>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <ul style=\"margin:0 0 0 14px;padding:0;font-size:12px;color:#475569;line-height:1.9;\">\n            <li>Configured width renders as-is (320–800px)</li>\n            <li>Page content remains visible alongside</li>\n            <li>Push variant shifts content left by drawer width</li>\n          </ul>\n        </div>\n      </div>\n\n      <!-- Tablet -->\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#0f172a;\">Tablet</span>\n          <span style=\"font-size:11px;color:#64748b;font-family:'SF Mono',monospace;\">768px – 1023px</span>\n        </div>\n        <div style=\"padding:14px;background:#e8edf5;border-bottom:1px solid #e2e8f0;\">\n          <div style=\"background:rgba(31,41,55,0.3);border-radius:6px;overflow:hidden;display:flex;height:80px;position:relative;\">\n            <div style=\"flex:1;padding:8px;opacity:0.3;\">\n              <div style=\"height:6px;background:#fff;border-radius:2px;width:50%;margin-bottom:6px;\"></div>\n              <div style=\"height:6px;background:rgba(255,255,255,0.5);border-radius:2px;width:70%;\"></div>\n            </div>\n            <div style=\"width:120px;background:#fff;border-left:1px solid #e2e8f0;padding:8px;display:flex;flex-direction:column;gap:5px;\">\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:75%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:55%;\"></div>\n              <div style=\"height:6px;background:#e2e8f0;border-radius:2px;width:65%;\"></div>\n            </div>\n          </div>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <ul style=\"margin:0 0 0 14px;padding:0;font-size:12px;color:#475569;line-height:1.9;\">\n            <li>Drawer width capped at 75vw if prop width exceeds it</li>\n            <li>Overlay variant always used — Push switches to Overlay</li>\n            <li>Touch swipe-right on drawer dismisses it</li>\n          </ul>\n        </div>\n      </div>\n\n      <!-- Mobile -->\n      <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;\">\n        <div style=\"padding:14px 16px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;\">\n          <span style=\"font-size:13px;font-weight:700;color:#0f172a;\">Mobile</span>\n          <span style=\"font-size:11px;color:#64748b;font-family:'SF Mono',monospace;\">&lt; 768px</span>\n        </div>\n        <div style=\"padding:14px;background:#e8edf5;border-bottom:1px solid #e2e8f0;\">\n          <div style=\"background:rgba(31,41,55,0.35);border-radius:6px;overflow:hidden;height:80px;position:relative;display:flex;align-items:stretch;\">\n            <div style=\"flex:1;opacity:0.2;\"></div>\n            <div style=\"width:100%;position:absolute;inset:0;background:#fff;padding:8px 10px;display:flex;flex-direction:column;justify-content:space-between;\">\n              <div style=\"display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e2e8f0;padding-bottom:6px;\">\n                <div style=\"height:8px;background:#001e4c;border-radius:2px;width:35%;\"></div>\n                <div style=\"width:14px;height:14px;background:#f1f5f9;border-radius:3px;\"></div>\n              </div>\n              <div style=\"display:flex;flex-direction:column;gap:4px;flex:1;padding:6px 0;\">\n                <div style=\"height:5px;background:#e2e8f0;border-radius:2px;width:70%;\"></div>\n                <div style=\"height:5px;background:#e2e8f0;border-radius:2px;width:50%;\"></div>\n              </div>\n              <div style=\"display:flex;gap:5px;border-top:1px solid #e2e8f0;padding-top:5px;justify-content:flex-end;\">\n                <div style=\"height:18px;width:36px;background:#f1f5f9;border-radius:3px;border:1px solid #e2e8f0;\"></div>\n                <div style=\"height:18px;width:36px;background:#1852fe;border-radius:3px;\"></div>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div style=\"padding:14px 16px;\">\n          <ul style=\"margin:0 0 0 14px;padding:0;font-size:12px;color:#475569;line-height:1.9;\">\n            <li>Always full-width (100vw) regardless of configured width</li>\n            <li>Always Overlay variant — no Push or Inline</li>\n            <li>Body scroll always locked while open</li>\n            <li>Swipe-right to dismiss (touch gesture)</li>\n          </ul>\n        </div>\n      </div>\n\n    </div>\n\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%;border-collapse:collapse;font-size:13px;background:#fff;border-radius:10px;overflow:hidden;border:1px solid #e2e8f0;\">\n        <thead>\n          <tr style=\"background:#f8fafc;border-bottom:1px solid #e2e8f0;\">\n            <th style=\"text-align:left;padding:10px 16px;font-size:11px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;\">Breakpoint</th>\n            <th style=\"text-align:left;padding:10px 16px;font-size:11px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;\">Width</th>\n            <th style=\"text-align:left;padding:10px 16px;font-size:11px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;\">Variant override</th>\n            <th style=\"text-align:left;padding:10px 16px;font-size:11px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;\">Scroll lock</th>\n            <th style=\"text-align:left;padding:10px 16px;font-size:11px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.06em;\">Swipe dismiss</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:11px 16px;font-weight:600;color:#0f172a;\">Desktop ≥ 1024px</td><td style=\"padding:11px 16px;color:#475569;\">Configured prop</td><td style=\"padding:11px 16px;color:#475569;\">None</td><td style=\"padding:11px 16px;color:#475569;\">Overlay only</td><td style=\"padding:11px 16px;color:#475569;\">—</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:11px 16px;font-weight:600;color:#0f172a;\">Tablet 768–1023px</td><td style=\"padding:11px 16px;color:#475569;\">Min(prop, 75vw)</td><td style=\"padding:11px 16px;color:#475569;\">Push → Overlay</td><td style=\"padding:11px 16px;color:#475569;\">Yes</td><td style=\"padding:11px 16px;color:#475569;\">Yes</td></tr>\n          <tr><td style=\"padding:11px 16px;font-weight:600;color:#0f172a;\">Mobile &lt; 768px</td><td style=\"padding:11px 16px;color:#475569;\">100vw always</td><td style=\"padding:11px 16px;color:#475569;\">Always Overlay</td><td style=\"padding:11px 16px;color:#475569;\">Always</td><td style=\"padding:11px 16px;color:#475569;\">Yes</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- ── ACCESSIBILITY ── -->\n  <h2 class=\"ds-section-heading\">Accessibility</h2>\n  <div class=\"btn-a11y-card\">\n    <h3>WCAG 2.1 AA Checklist</h3>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\">Use <code>role=\"dialog\"</code> and <code>aria-modal=\"true\"</code> on the drawer panel element. Link the title via <code>aria-labelledby</code> pointing to the header title element.</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Focus trap</strong> — keyboard focus must stay inside the drawer while it is open. On open, move focus to the first interactive element (usually the first form field or the close button if content-only).</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Escape key</strong> closes the drawer. The × button must have <code>aria-label=\"Close panel\"</code>. Both must work even when focus is inside a form field.</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Focus return</strong> — on close, focus must return to the trigger element that opened the drawer. Store a ref to the trigger before opening and call <code>.focus()</code> after the exit animation finishes.</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Background inert</strong> — mark the rest of the page with <code>inert</code> or <code>aria-hidden=\"true\"</code> while the drawer is open so screen readers do not read the dimmed background content.</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Contrast</strong> — all text inside the drawer must meet 4.5:1 contrast ratio (WCAG AA). Placeholder text is exempt but must meet 3:1 minimum.</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Reduced motion</strong> — honour <code>prefers-reduced-motion: reduce</code>. Skip the translateX animation entirely; use a 150ms opacity-only fade as the fallback.</div>\n    </div>\n    <div class=\"btn-a11y-row\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Screen reader announcement</strong> — use <code>aria-live=\"polite\"</code> on a visually hidden element to announce \"<em>Panel opened: [title]</em>\" when the drawer enters. Some screen readers do not automatically announce <code>role=\"dialog\"</code> on slide-in panels.</div>\n    </div>\n    <div class=\"btn-a11y-row\" style=\"border:none;padding-bottom:0;\">\n      <div class=\"btn-a11y-icon\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <div class=\"btn-a11y-text\"><strong>Scroll lock (Overlay only)</strong> — prevent <code>body</code> scroll via <code>overflow: hidden</code> while the overlay drawer is open. Restore on close and also on browser back-navigation.</div>\n    </div>\n  </div>\n\n</div>\n\n<!-- ========== CODE TAB ========== -->\n<div id=\"slideout-pane-code\" class=\"btn-tab-pane slideout-tab-pane\">\n\n  <!-- ═══════════════════════════════════════════════════════════════\n       LIVE DEMO CARD\n  ═══════════════════════════════════════════════════════════════ -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Live Demo</div>\n    <p class=\"btn-family-desc\">Interactive examples of both drawer variants — no framework required.</p>\n\n    <!-- Demo container -->\n    <div id=\"sd-demo\" style=\"position:relative;overflow:hidden;height:360px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;margin-top:20px;display:flex;\">\n\n      <!-- Backdrop for overlay drawer -->\n      <div id=\"cd-overlay-backdrop\" onclick=\"cdCloseOverlay()\" style=\"display:none;position:absolute;inset:0;z-index:9;background:rgba(31,41,55,0.70);transition:opacity 0.28s;\"></div>\n\n      <!-- ── Left: fake page content ── -->\n      <div id=\"sd-main-content\" style=\"flex:1;min-width:0;display:flex;flex-direction:column;padding:24px;gap:16px;transition:all 0.28s cubic-bezier(0.4,0,0.2,1);\">\n\n        <!-- Fake title bar -->\n        <div style=\"display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n          <div style=\"display:flex;flex-direction:column;gap:6px;\">\n            <div style=\"height:10px;width:140px;background:#cbd5e1;border-radius:3px;\"></div>\n            <div style=\"height:7px;width:100px;background:#e2e8f0;border-radius:3px;\"></div>\n          </div>\n          <div style=\"height:32px;width:32px;background:#e2e8f0;border-radius:8px;\"></div>\n        </div>\n\n        <!-- Skeleton rows -->\n        <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;flex-shrink:0;\">\n          <div style=\"height:34px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;padding:0 14px;gap:8px;\">\n            <div style=\"height:7px;width:60px;background:#e2e8f0;border-radius:2px;\"></div>\n            <div style=\"height:7px;width:80px;background:#e2e8f0;border-radius:2px;\"></div>\n            <div style=\"height:7px;width:50px;background:#e2e8f0;border-radius:2px;\"></div>\n          </div>\n          <div style=\"height:34px;border-bottom:1px solid #f1f5f9;display:flex;align-items:center;padding:0 14px;gap:8px;\">\n            <div style=\"height:7px;width:120px;background:#e2e8f0;border-radius:2px;\"></div>\n            <div style=\"height:7px;width:80px;background:#e2e8f0;border-radius:2px;margin-left:auto;\"></div>\n          </div>\n          <div style=\"height:34px;border-bottom:1px solid #f1f5f9;display:flex;align-items:center;padding:0 14px;gap:8px;\">\n            <div style=\"height:7px;width:90px;background:#e2e8f0;border-radius:2px;\"></div>\n            <div style=\"height:7px;width:110px;background:#e2e8f0;border-radius:2px;margin-left:auto;\"></div>\n          </div>\n          <div style=\"height:34px;border-bottom:1px solid #f1f5f9;display:flex;align-items:center;padding:0 14px;gap:8px;\">\n            <div style=\"height:7px;width:140px;background:#e2e8f0;border-radius:2px;\"></div>\n            <div style=\"height:7px;width:60px;background:#e2e8f0;border-radius:2px;margin-left:auto;\"></div>\n          </div>\n          <div style=\"height:34px;display:flex;align-items:center;padding:0 14px;gap:8px;\">\n            <div style=\"height:7px;width:100px;background:#e2e8f0;border-radius:2px;\"></div>\n            <div style=\"height:7px;width:90px;background:#e2e8f0;border-radius:2px;margin-left:auto;\"></div>\n          </div>\n        </div>\n\n        <!-- Action buttons at bottom -->\n        <div style=\"margin-top:auto;display:flex;gap:8px;flex-shrink:0;\">\n          <button onclick=\"cdOpenOverlay()\" style=\"height:36px;padding:0 16px;background:#1852fe;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;transition:background 0.15s;\" onmouseover=\"this.style.background='#1242d4'\" onmouseout=\"this.style.background='#1852fe'\">Open Overlay Drawer</button>\n          <button onclick=\"cdOpenInline()\" style=\"height:36px;padding:0 16px;background:#fff;color:#475569;border:1px solid #e2e8f0;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;transition:background 0.15s;\" onmouseover=\"this.style.background='#f8fafc'\" onmouseout=\"this.style.background='#fff'\">Open Inline Drawer</button>\n        </div>\n      </div>\n\n      <!-- ── Overlay Drawer ── -->\n      <div id=\"cd-overlay\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cd-overlay-title\" style=\"position:absolute;top:12px;right:12px;bottom:12px;width:300px;background:#fff;border-radius:12px;overflow:hidden;transform:translateX(calc(100% + 12px));transition:transform 0.28s cubic-bezier(0.4,0,0.2,1);z-index:10;display:flex;flex-direction:column;\">\n        <!-- Sticky header -->\n        <div style=\"height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid #e2e8f0;flex-shrink:0;\">\n          <span id=\"cd-overlay-title\" style=\"font-size:13px;font-weight:700;color:#0f172a;font-family:'Gilroy',sans-serif;\">Edit Record</span>\n          <button onclick=\"cdCloseOverlay()\" aria-label=\"Close drawer\" style=\"width:26px;height:26px;background:#f1f5f9;border:none;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0;\">\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <!-- Scrollable body -->\n        <div style=\"flex:1;overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:16px;\">\n          <div>\n            <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;\">Record Name</div>\n            <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n          </div>\n          <div>\n            <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;\">Status</div>\n            <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n          </div>\n          <div>\n            <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;\">Assigned To</div>\n            <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n          </div>\n          <div>\n            <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;\">Notes</div>\n            <div style=\"height:72px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n          </div>\n          <div>\n            <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;\">Due Date</div>\n            <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n          </div>\n        </div>\n        <!-- Sticky footer -->\n        <div style=\"height:60px;display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:0 20px;border-top:1px solid #e2e8f0;flex-shrink:0;background:#fff;\">\n          <button onclick=\"cdCloseOverlay()\" style=\"height:34px;padding:0 14px;background:#fff;color:#475569;border:1px solid #e2e8f0;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;\">Cancel</button>\n          <button onclick=\"cdCloseOverlay()\" style=\"height:34px;padding:0 14px;background:#1852fe;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;\">Apply</button>\n        </div>\n      </div>\n\n      <!-- ── Inline Push Drawer ── -->\n      <div id=\"cd-inline\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"cd-inline-title\" style=\"width:0;overflow:hidden;background:#fff;border-left:1px solid #e2e8f0;display:flex;flex-direction:column;flex-shrink:0;transition:width 0.28s cubic-bezier(0.4,0,0.2,1);\">\n        <div style=\"width:280px;display:flex;flex-direction:column;height:100%;\">\n          <!-- Sticky header -->\n          <div style=\"height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid #e2e8f0;flex-shrink:0;\">\n            <span id=\"cd-inline-title\" style=\"font-size:13px;font-weight:700;color:#0f172a;font-family:'Gilroy',sans-serif;white-space:nowrap;\">Filters</span>\n            <button onclick=\"cdCloseInline()\" aria-label=\"Close drawer\" style=\"width:26px;height:26px;background:#f1f5f9;border:none;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0;\">\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></svg>\n            </button>\n          </div>\n          <!-- Scrollable body -->\n          <div style=\"flex:1;overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:16px;\">\n            <div>\n              <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;white-space:nowrap;\">Date Range</div>\n              <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n            </div>\n            <div>\n              <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;white-space:nowrap;\">Category</div>\n              <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n            </div>\n            <div>\n              <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;white-space:nowrap;\">Region</div>\n              <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n            </div>\n            <div>\n              <div style=\"font-size:11px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.04em;white-space:nowrap;\">Status</div>\n              <div style=\"height:36px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;\"></div>\n            </div>\n          </div>\n          <!-- Sticky footer -->\n          <div style=\"height:60px;display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:0 20px;border-top:1px solid #e2e8f0;flex-shrink:0;background:#fff;\">\n            <button onclick=\"cdCloseInline()\" style=\"height:34px;padding:0 14px;background:#fff;color:#475569;border:1px solid #e2e8f0;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;white-space:nowrap;\">Cancel</button>\n            <button onclick=\"cdCloseInline()\" style=\"height:34px;padding:0 14px;background:#1852fe;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;white-space:nowrap;\">Apply</button>\n          </div>\n        </div>\n      </div>\n\n    </div><!-- /sd-demo -->\n\n    <!-- Demo labels -->\n    <div style=\"display:flex;gap:20px;margin-top:12px;\">\n      <div style=\"display:flex;align-items:center;gap:6px;\">\n        <div style=\"width:8px;height:8px;background:#1852fe;border-radius:2px;\"></div>\n        <span style=\"font-size:11px;color:#64748b;\">Overlay — backdrop dims page, drawer floats above</span>\n      </div>\n      <div style=\"display:flex;align-items:center;gap:6px;\">\n        <div style=\"width:8px;height:8px;background:#64748b;border-radius:2px;\"></div>\n        <span style=\"font-size:11px;color:#64748b;\">Inline push — drawer shifts page content, no backdrop</span>\n      </div>\n    </div>\n\n  </div><!-- /Live Demo card -->\n\n\n  <!-- ═══════════════════════════════════════════════════════════════\n       CODE SECTIONS CARD\n  ═══════════════════════════════════════════════════════════════ -->\n  <div class=\"btn-family-card\">\n    <div class=\"btn-family-title\">Implementation</div>\n    <p class=\"btn-family-desc\">\n      The GS Drawer wraps Ant Design's <code class=\"ds-code-tag\">Drawer</code> component, wiring design-system CSS tokens through a SCSS bridge. Two variants are supported: <code class=\"ds-code-tag\">overlay</code> (floats above content with a dark backdrop) and <code class=\"ds-code-tag\">push</code> (shifts layout with no mask). All token values resolve at runtime from <code class=\"ds-code-tag\">:root</code> CSS custom properties — no hard-coded hex values live in component files.\n    </p>\n\n    <!-- ① Installation -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">1</span>\n        <h3 class=\"ds-prop-title\">Installation</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">bash</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-install',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-install\"><span class=\"c-cmt\"># Install dependencies</span>\nnpm install antd\nnpm install --save-dev sass</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ② File Structure -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">2</span>\n        <h3 class=\"ds-prop-title\">File Structure</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">directory</span>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-structure\"><span class=\"c-cmt\">src/\n├── tokens/\n│   └── tokens.css             </span><span class=\"c-cmt\">← DS CSS custom properties (:root primitives → semantic → component)</span>\n<span class=\"c-cmt\">├── theme/\n│   └── gs-theme.js            </span><span class=\"c-cmt\">← Reads CSS vars at runtime → passes to ConfigProvider</span>\n<span class=\"c-cmt\">├── styles/\n│   └── _variables.scss        </span><span class=\"c-cmt\">← SCSS bridge: $var: var(--drawer-*)</span>\n<span class=\"c-cmt\">└── components/\n    └── Drawer/\n        ├── Drawer.jsx          </span><span class=\"c-cmt\">← GS Drawer wrapper (overlay + push variants)</span>\n<span class=\"c-cmt\">        ├── DrawerHeader.jsx    </span><span class=\"c-cmt\">← Sticky header with title + close</span>\n<span class=\"c-cmt\">        ├── DrawerFooter.jsx    </span><span class=\"c-cmt\">← Sticky footer with primary/secondary actions</span>\n<span class=\"c-cmt\">        ├── DrawerSkeleton.jsx  </span><span class=\"c-cmt\">← Loading skeleton state</span>\n<span class=\"c-cmt\">        ├── Drawer.scss         </span><span class=\"c-cmt\">← Component SCSS using token bridge</span>\n<span class=\"c-cmt\">        └── index.js            </span><span class=\"c-cmt\">← Barrel export</span></pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ③ gs-theme.js -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">3</span>\n        <h3 class=\"ds-prop-title\">theme/gs-theme.js</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">JavaScript · Geoserve Theme</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-theme',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-theme\"><span class=\"c-cmt\">/**\n * Geoserve UI theme config – injected via ConfigProvider.\n *\n * Token values are read from the design-system CSS custom properties\n * at runtime via getComputedStyle so any update to :root cascades\n * here automatically – no hard-coded hex values in this file.\n *\n * Token chain example:\n *   colorPrimary  ←  --prim-marine  ←  :root { --prim-marine: #1852FE }\n *\n * Wrap your app root (or the Drawer's nearest ancestor) with:\n *   &lt;ConfigProvider theme={gsTheme}&gt;...&lt;/ConfigProvider&gt;\n */</span>\n<span class=\"c-kw\">const</span> cssVar = (name) =&gt;\n  getComputedStyle(document.documentElement).getPropertyValue(name).trim();\n\n<span class=\"c-kw\">const</span> gsTheme = {\n  token: {\n    colorPrimary:  cssVar(<span class=\"c-val\">'--prim-marine'</span>),       <span class=\"c-cmt\">// → #1852FE</span>\n    colorError:    cssVar(<span class=\"c-val\">'--prim-red-500'</span>),      <span class=\"c-cmt\">// → #DC2625</span>\n    borderRadius:  <span class=\"c-val\">4</span>,                             <span class=\"c-cmt\">// --prim-radius-sm</span>\n    fontFamily:    cssVar(<span class=\"c-val\">'--prim-font-primary'</span>),  <span class=\"c-cmt\">// Gilroy stack</span>\n    fontSize:      <span class=\"c-val\">14</span>,                            <span class=\"c-cmt\">// --prim-font-size-md</span>\n  },\n  components: {\n    Drawer: {\n      zIndexPopup:         <span class=\"c-val\">1000</span>,\n      footerPaddingBlock:  <span class=\"c-val\">16</span>,\n      footerPaddingInline: <span class=\"c-val\">24</span>,\n      headerPadding:       <span class=\"c-val\">'16px 24px'</span>,\n      bodyPadding:         <span class=\"c-val\">'0'</span>,\n      paddingLG:           <span class=\"c-val\">24</span>,\n    },\n  },\n};\n\n<span class=\"c-kw\">export default</span> gsTheme;</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ④ _variables.scss -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">4</span>\n        <h3 class=\"ds-prop-title\">styles/_variables.scss</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">SCSS · Design Tokens</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-vars',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-vars\"><span class=\"c-cmt\">// ─── Drawer token bridge: SCSS variables → CSS custom properties ──────────\n// Each $variable wraps a var(--comp-drawer-*) so SCSS can reference them in\n// rules while the CSS engine resolves the actual value from :root at runtime.\n//\n// Tier chain:  $drawer-bg\n//               → var(--comp-drawer-bg)       [component token]\n//               → var(--color-surface-default) [semantic token]\n//               → var(--prim-white)            [primitive token]\n//               → #ffffff                      [raw value]\n// ─────────────────────────────────────────────────────────────────────────</span>\n\n<span class=\"c-cmt\">// ─── Drawer tokens ────────────────────────────────────────</span>\n<span class=\"c-kw\">$drawer-bg</span>:            var(<span class=\"c-val\">--comp-drawer-bg</span>);         <span class=\"c-cmt\">// #ffffff</span>\n<span class=\"c-kw\">$drawer-shadow</span>:        var(<span class=\"c-val\">--comp-drawer-shadow</span>);     <span class=\"c-cmt\">// -6px 0 32px rgba(0,0,0,0.18)</span>\n<span class=\"c-kw\">$drawer-header-height</span>: var(<span class=\"c-val\">--comp-drawer-header-h</span>);  <span class=\"c-cmt\">// 56px</span>\n<span class=\"c-kw\">$drawer-footer-height</span>: var(<span class=\"c-val\">--comp-drawer-footer-h</span>);  <span class=\"c-cmt\">// 72px</span>\n<span class=\"c-kw\">$drawer-width-sm</span>:      var(<span class=\"c-val\">--comp-drawer-w-sm</span>);      <span class=\"c-cmt\">// 320px</span>\n<span class=\"c-kw\">$drawer-width-md</span>:      var(<span class=\"c-val\">--comp-drawer-w-md</span>);      <span class=\"c-cmt\">// 480px</span>\n<span class=\"c-kw\">$drawer-width-lg</span>:      var(<span class=\"c-val\">--comp-drawer-w-lg</span>);      <span class=\"c-cmt\">// 720px</span>\n<span class=\"c-kw\">$drawer-overlay-bg</span>:    var(<span class=\"c-val\">--comp-drawer-overlay</span>);   <span class=\"c-cmt\">// rgba(15,23,42,0.40)</span>\n<span class=\"c-kw\">$drawer-border</span>:        var(<span class=\"c-val\">--color-border</span>);           <span class=\"c-cmt\">// #e2e8f0</span>\n<span class=\"c-kw\">$drawer-title-size</span>:    var(<span class=\"c-val\">--prim-font-size-md</span>);     <span class=\"c-cmt\">// 14px</span>\n<span class=\"c-kw\">$drawer-title-weight</span>:  var(<span class=\"c-val\">--prim-font-weight-bold</span>); <span class=\"c-cmt\">// 700</span></pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ⑤ Drawer.jsx -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">5</span>\n        <h3 class=\"ds-prop-title\">Drawer/Drawer.jsx</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">TypeScript · React</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-jsx',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-jsx\"><span class=\"c-kw\">import</span> React, { useRef, useEffect, useCallback } <span class=\"c-kw\">from</span> <span class=\"c-val\">'react'</span>;\n<span class=\"c-kw\">import</span> { Drawer <span class=\"c-kw\">as</span> AntDrawer, ConfigProvider } <span class=\"c-kw\">from</span> <span class=\"c-val\">'antd'</span>;\n<span class=\"c-kw\">import</span> gsTheme <span class=\"c-kw\">from</span> <span class=\"c-val\">'../../theme/gs-theme'</span>;\n<span class=\"c-kw\">import</span> <span class=\"c-val\">'./Drawer.scss'</span>;\n\n<span class=\"c-cmt\">/** Props accepted by the GS Drawer wrapper. */</span>\n<span class=\"c-kw\">interface</span> <span class=\"c-type\">DrawerProps</span> {\n  open:       <span class=\"c-type\">boolean</span>;\n  onClose:    () =&gt; <span class=\"c-type\">void</span>;\n  title:      <span class=\"c-type\">string</span>;\n  width?:     <span class=\"c-type\">number</span> | <span class=\"c-type\">string</span>;\n  variant?:   <span class=\"c-val\">'overlay'</span> | <span class=\"c-val\">'push'</span>;\n  footer?:    <span class=\"c-type\">React.ReactNode</span>;\n  loading?:   <span class=\"c-type\">boolean</span>;\n  children:   <span class=\"c-type\">React.ReactNode</span>;\n}\n\n<span class=\"c-cmt\">/** FOCUSABLE_SELECTORS – elements that should receive keyboard focus. */</span>\n<span class=\"c-kw\">const</span> FOCUSABLE = <span class=\"c-val\">'a[href],button:not([disabled]),input,select,textarea,[tabindex]:not([tabindex=\"-1\"])'</span>;\n\n<span class=\"c-kw\">const</span> Drawer: <span class=\"c-type\">React.FC</span>&lt;<span class=\"c-type\">DrawerProps</span>&gt; = ({\n  open,\n  onClose,\n  title,\n  width    = <span class=\"c-val\">480</span>,\n  variant  = <span class=\"c-val\">'overlay'</span>,\n  footer,\n  loading  = <span class=\"c-val\">false</span>,\n  children,\n}) =&gt; {\n  <span class=\"c-kw\">const</span> drawerRef  = useRef&lt;<span class=\"c-type\">HTMLDivElement</span>&gt;(<span class=\"c-val\">null</span>);\n  <span class=\"c-kw\">const</span> triggerRef = useRef&lt;<span class=\"c-type\">HTMLElement</span>&gt;(<span class=\"c-val\">null</span>);\n  <span class=\"c-kw\">const</span> titleId    = <span class=\"c-val\">`gs-drawer-title-${title.replace(/\\s+/g, '-').toLowerCase()}`</span>;\n\n  <span class=\"c-cmt\">// Capture the element that opened the drawer so focus returns on close.</span>\n  useEffect(() =&gt; {\n    <span class=\"c-kw\">if</span> (open) {\n      triggerRef.current = document.activeElement <span class=\"c-kw\">as</span> <span class=\"c-type\">HTMLElement</span>;\n    } <span class=\"c-kw\">else</span> {\n      triggerRef.current?.focus();\n    }\n  }, [open]);\n\n  <span class=\"c-cmt\">// Move focus into the drawer when it opens.</span>\n  useEffect(() =&gt; {\n    <span class=\"c-kw\">if</span> (!open || !drawerRef.current) <span class=\"c-kw\">return</span>;\n    <span class=\"c-kw\">const</span> first = drawerRef.current.querySelector&lt;<span class=\"c-type\">HTMLElement</span>&gt;(FOCUSABLE);\n    first?.focus();\n  }, [open]);\n\n  <span class=\"c-cmt\">// Trap tab/shift-tab focus within the drawer.</span>\n  <span class=\"c-kw\">const</span> handleKeyDown = useCallback(\n    (e: <span class=\"c-type\">React.KeyboardEvent</span>) =&gt; {\n      <span class=\"c-kw\">if</span> (!open || !drawerRef.current) <span class=\"c-kw\">return</span>;\n      <span class=\"c-kw\">if</span> (e.key === <span class=\"c-val\">'Escape'</span>) { onClose(); <span class=\"c-kw\">return</span>; }\n      <span class=\"c-kw\">if</span> (e.key !== <span class=\"c-val\">'Tab'</span>) <span class=\"c-kw\">return</span>;\n\n      <span class=\"c-kw\">const</span> focusable = Array.from(\n        drawerRef.current.querySelectorAll&lt;<span class=\"c-type\">HTMLElement</span>&gt;(FOCUSABLE)\n      );\n      <span class=\"c-kw\">if</span> (!focusable.length) <span class=\"c-kw\">return</span>;\n\n      <span class=\"c-kw\">const</span> first = focusable[<span class=\"c-val\">0</span>];\n      <span class=\"c-kw\">const</span> last  = focusable[focusable.length - <span class=\"c-val\">1</span>];\n\n      <span class=\"c-kw\">if</span> (e.shiftKey &amp;&amp; document.activeElement === first) {\n        e.preventDefault();\n        last.focus();\n      } <span class=\"c-kw\">else if</span> (!e.shiftKey &amp;&amp; document.activeElement === last) {\n        e.preventDefault();\n        first.focus();\n      }\n    },\n    [open, onClose]\n  );\n\n  <span class=\"c-kw\">return</span> (\n    &lt;<span class=\"c-tag\">ConfigProvider</span> <span class=\"c-attr\">theme</span>={gsTheme}&gt;\n      &lt;<span class=\"c-tag\">AntDrawer</span>\n        <span class=\"c-attr\">open</span>={open}\n        <span class=\"c-attr\">onClose</span>={onClose}\n        <span class=\"c-attr\">title</span>={title}\n        <span class=\"c-attr\">width</span>={width}\n        <span class=\"c-attr\">placement</span>=<span class=\"c-val\">\"right\"</span>\n        <span class=\"c-attr\">mask</span>={variant === <span class=\"c-val\">'overlay'</span>}\n        <span class=\"c-attr\">footer</span>={footer}\n        <span class=\"c-attr\">className</span>={<span class=\"c-val\">`gs-drawer gs-drawer--${variant}`</span>}\n        <span class=\"c-attr\">rootProps</span>={{\n          role:            <span class=\"c-val\">'dialog'</span>,\n          <span class=\"c-val\">'aria-modal'</span>:    variant === <span class=\"c-val\">'overlay'</span> ? <span class=\"c-val\">'true'</span> : <span class=\"c-val\">'false'</span>,\n          <span class=\"c-val\">'aria-labelledby'</span>: titleId,\n          onKeyDown:       handleKeyDown,\n          ref:             drawerRef,\n        }}\n      &gt;\n        {<span class=\"c-cmt\">/* ARIA live region for loading state */</span>}\n        &lt;<span class=\"c-tag\">div</span> <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-live</span>=<span class=\"c-val\">\"polite\"</span> <span class=\"c-attr\">style</span>={{ position: <span class=\"c-val\">'absolute'</span>, width: <span class=\"c-val\">1</span>, height: <span class=\"c-val\">1</span>, overflow: <span class=\"c-val\">'hidden'</span>, clip: <span class=\"c-val\">'rect(0,0,0,0)'</span> }}&gt;\n          {loading ? <span class=\"c-val\">'Loading content'</span> : <span class=\"c-val\">''</span>}\n        &lt;/<span class=\"c-tag\">div</span>&gt;\n        {children}\n      &lt;/<span class=\"c-tag\">AntDrawer</span>&gt;\n    &lt;/<span class=\"c-tag\">ConfigProvider</span>&gt;\n  );\n};\n\n<span class=\"c-kw\">export default</span> Drawer;</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ⑥ Drawer.scss -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">6</span>\n        <h3 class=\"ds-prop-title\">Drawer/Drawer.scss</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">SCSS · Geoserve Drawer Overrides</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-scss',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-scss\"><span class=\"c-kw\">@import</span> <span class=\"c-val\">'../styles/variables'</span>;\n\n<span class=\"c-cmt\">// Each $variable resolves via var(--comp-drawer-*) → var(--color-*) → var(--prim-*) → raw value.\n// To retheme the drawer, override the relevant --comp-drawer-* token in :root.</span>\n\n<span class=\"c-tag\">.gs-drawer</span> {\n  <span class=\"c-cmt\">// ─── Right-placement host ────────────────────────────────</span>\n  &amp;<span class=\"c-tag\">.ant-drawer-right</span> {\n    <span class=\"c-tag\">.ant-drawer-content-wrapper</span> {\n      box-shadow: <span class=\"c-kw\">$drawer-shadow</span>;  <span class=\"c-cmt\">// var(--comp-drawer-shadow)</span>\n    }\n\n    <span class=\"c-tag\">.ant-drawer-header</span> {\n      height:        <span class=\"c-kw\">$drawer-header-height</span>;  <span class=\"c-cmt\">// var(--comp-drawer-header-h)</span>\n      padding:       <span class=\"c-val\">0 24px</span>;\n      border-bottom: <span class=\"c-val\">1px solid</span> <span class=\"c-kw\">$drawer-border</span>;\n      display:       flex;\n      align-items:   center;\n      flex-shrink:   <span class=\"c-val\">0</span>;\n    }\n\n    <span class=\"c-tag\">.ant-drawer-title</span> {\n      font-size:   <span class=\"c-kw\">$drawer-title-size</span>;    <span class=\"c-cmt\">// var(--prim-font-size-md)</span>\n      font-weight: <span class=\"c-kw\">$drawer-title-weight</span>;  <span class=\"c-cmt\">// var(--prim-font-weight-bold)</span>\n      color:       <span class=\"c-val\">#0f172a</span>;\n      font-family: <span class=\"c-val\">'Gilroy'</span>, sans-serif;\n    }\n\n    <span class=\"c-tag\">.ant-drawer-body</span> {\n      padding:    <span class=\"c-val\">0</span>;\n      overflow-y: auto;\n    }\n\n    <span class=\"c-tag\">.ant-drawer-footer</span> {\n      height:          <span class=\"c-kw\">$drawer-footer-height</span>;  <span class=\"c-cmt\">// var(--comp-drawer-footer-h)</span>\n      padding:         <span class=\"c-val\">0 24px</span>;\n      border-top:      <span class=\"c-val\">1px solid</span> <span class=\"c-kw\">$drawer-border</span>;\n      display:         flex;\n      align-items:     center;\n      justify-content: flex-end;\n      gap:             <span class=\"c-val\">8px</span>;\n      flex-shrink:     <span class=\"c-val\">0</span>;\n    }\n  }\n\n  <span class=\"c-cmt\">// ─── Push variant: no mask, softer shadow ─────────────────</span>\n  &amp;<span class=\"c-tag\">--push</span> {\n    <span class=\"c-tag\">.ant-drawer-mask</span> { display: none !important; }\n\n    <span class=\"c-tag\">.ant-drawer-content-wrapper</span> {\n      box-shadow: <span class=\"c-val\">-3px 0 12px rgba(0,0,0,0.06)</span> !important;\n    }\n  }\n\n  <span class=\"c-cmt\">// ─── Overlay variant: dark backdrop ───────────────────────</span>\n  &amp;<span class=\"c-tag\">--overlay</span> {\n    <span class=\"c-tag\">.ant-drawer-mask</span> {\n      background: <span class=\"c-kw\">$drawer-overlay-bg</span>;  <span class=\"c-cmt\">// var(--comp-drawer-overlay)</span>\n    }\n  }\n}</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ⑦ DrawerSkeleton.jsx -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">7</span>\n        <h3 class=\"ds-prop-title\">DrawerSkeleton.jsx</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">JSX · Loading State</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-skeleton',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-skeleton\"><span class=\"c-kw\">import</span> React <span class=\"c-kw\">from</span> <span class=\"c-val\">'react'</span>;\n<span class=\"c-kw\">import</span> { Skeleton, Space, ConfigProvider } <span class=\"c-kw\">from</span> <span class=\"c-val\">'antd'</span>;\n<span class=\"c-kw\">import</span> gsTheme <span class=\"c-kw\">from</span> <span class=\"c-val\">'../../theme/gs-theme'</span>;\n\n<span class=\"c-cmt\">/**\n * DrawerSkeleton – drop into the Drawer body while data is loading.\n * Mimics a typical label + input layout with animated placeholders.\n */</span>\n<span class=\"c-kw\">const</span> DrawerSkeleton = () =&gt; (\n  &lt;<span class=\"c-tag\">ConfigProvider</span> <span class=\"c-attr\">theme</span>={gsTheme}&gt;\n    &lt;<span class=\"c-tag\">div</span> <span class=\"c-attr\">style</span>={{ padding: <span class=\"c-val\">'24px'</span> }}&gt;\n      &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">160</span>, height: <span class=\"c-val\">14</span>, marginBottom: <span class=\"c-val\">24</span> }} /&gt;\n\n      &lt;<span class=\"c-tag\">Space</span> <span class=\"c-attr\">direction</span>=<span class=\"c-val\">\"vertical\"</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">'100%'</span> }} <span class=\"c-attr\">size</span>={<span class=\"c-val\">20</span>}&gt;\n        &lt;<span class=\"c-tag\">div</span>&gt;\n          &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"small\"</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">80</span>, marginBottom: <span class=\"c-val\">8</span> }} /&gt;\n          &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">'100%'</span>, height: <span class=\"c-val\">40</span> }} /&gt;\n        &lt;/<span class=\"c-tag\">div</span>&gt;\n        &lt;<span class=\"c-tag\">div</span>&gt;\n          &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"small\"</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">64</span>, marginBottom: <span class=\"c-val\">8</span> }} /&gt;\n          &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">'100%'</span>, height: <span class=\"c-val\">40</span> }} /&gt;\n        &lt;/<span class=\"c-tag\">div</span>&gt;\n        &lt;<span class=\"c-tag\">div</span>&gt;\n          &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"small\"</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">100</span>, marginBottom: <span class=\"c-val\">8</span> }} /&gt;\n          &lt;<span class=\"c-tag\">Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">style</span>={{ width: <span class=\"c-val\">'100%'</span>, height: <span class=\"c-val\">80</span> }} /&gt;\n        &lt;/<span class=\"c-tag\">div</span>&gt;\n      &lt;/<span class=\"c-tag\">Space</span>&gt;\n    &lt;/<span class=\"c-tag\">div</span>&gt;\n  &lt;/<span class=\"c-tag\">ConfigProvider</span>&gt;\n);\n\n<span class=\"c-kw\">export default</span> DrawerSkeleton;</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ⑧ Multi-Panel Drawer -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">8</span>\n        <h3 class=\"ds-prop-title\">Multi-Panel (Stacked) Drawers</h3>\n      </div>\n      <p class=\"ds-label-upper\" style=\"margin-bottom:12px;\">Pattern — primary drawer opens a child drawer</p>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">JSX · Stacked Drawer Pattern</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-multi',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-multi\"><span class=\"c-kw\">import</span> React, { useState } <span class=\"c-kw\">from</span> <span class=\"c-val\">'react'</span>;\n<span class=\"c-kw\">import</span> { ConfigProvider } <span class=\"c-kw\">from</span> <span class=\"c-val\">'antd'</span>;\n<span class=\"c-kw\">import</span> gsTheme <span class=\"c-kw\">from</span> <span class=\"c-val\">'../../theme/gs-theme'</span>;\n<span class=\"c-kw\">import</span> Drawer <span class=\"c-kw\">from</span> <span class=\"c-val\">'./Drawer'</span>;\n<span class=\"c-kw\">import</span> DrawerFooter <span class=\"c-kw\">from</span> <span class=\"c-val\">'./DrawerFooter'</span>;\n\n<span class=\"c-cmt\">/**\n * MultiPanelExample – demonstrates stacked drawers.\n * The primary drawer (z-index 1000) renders a second child drawer\n * (z-index 1010) inside its body. Both share the same token system.\n *\n * Rules:\n *  – Only one level of nesting is recommended for usability.\n *  – The child drawer closes before the parent whenever possible.\n *  – Use unique aria-labelledby ids for each drawer level.\n */</span>\n<span class=\"c-kw\">const</span> MultiPanelExample = () =&gt; {\n  <span class=\"c-kw\">const</span> [primaryOpen, setPrimaryOpen] = useState(<span class=\"c-val\">false</span>);\n  <span class=\"c-kw\">const</span> [detailOpen,  setDetailOpen]  = useState(<span class=\"c-val\">false</span>);\n\n  <span class=\"c-kw\">return</span> (\n    &lt;<span class=\"c-tag\">ConfigProvider</span> <span class=\"c-attr\">theme</span>={gsTheme}&gt;\n      {<span class=\"c-cmt\">/* Trigger */</span>}\n      &lt;<span class=\"c-tag\">button</span> <span class=\"c-attr\">onClick</span>={() =&gt; setPrimaryOpen(<span class=\"c-val\">true</span>)}&gt;Open Primary Drawer&lt;/<span class=\"c-tag\">button</span>&gt;\n\n      {<span class=\"c-cmt\">/* Primary Drawer — z-index 1000 (from gsTheme) */</span>}\n      &lt;<span class=\"c-tag\">Drawer</span>\n        <span class=\"c-attr\">open</span>={primaryOpen}\n        <span class=\"c-attr\">onClose</span>={() =&gt; { setDetailOpen(<span class=\"c-val\">false</span>); setPrimaryOpen(<span class=\"c-val\">false</span>); }}\n        <span class=\"c-attr\">title</span>=<span class=\"c-val\">\"Record Detail\"</span>\n        <span class=\"c-attr\">width</span>={<span class=\"c-val\">480</span>}\n        <span class=\"c-attr\">variant</span>=<span class=\"c-val\">\"overlay\"</span>\n        <span class=\"c-attr\">footer</span>={\n          &lt;<span class=\"c-tag\">DrawerFooter</span>\n            <span class=\"c-attr\">onCancel</span>={() =&gt; setPrimaryOpen(<span class=\"c-val\">false</span>)}\n            <span class=\"c-attr\">onConfirm</span>={() =&gt; setPrimaryOpen(<span class=\"c-val\">false</span>)}\n          /&gt;\n        }\n      &gt;\n        &lt;<span class=\"c-tag\">div</span> <span class=\"c-attr\">style</span>={{ padding: <span class=\"c-val\">'24px'</span> }}&gt;\n          &lt;<span class=\"c-tag\">p</span>&gt;Primary drawer content here.&lt;/<span class=\"c-tag\">p</span>&gt;\n          &lt;<span class=\"c-tag\">button</span> <span class=\"c-attr\">onClick</span>={() =&gt; setDetailOpen(<span class=\"c-val\">true</span>)}&gt;Open Detail Panel&lt;/<span class=\"c-tag\">button</span>&gt;\n        &lt;/<span class=\"c-tag\">div</span>&gt;\n\n        {<span class=\"c-cmt\">/* Child Drawer — z-index 1010, narrower, no extra mask */</span>}\n        &lt;<span class=\"c-tag\">ConfigProvider</span> <span class=\"c-attr\">theme</span>={{ ...gsTheme, components: { Drawer: { ...gsTheme.components?.Drawer, zIndexPopup: <span class=\"c-val\">1010</span> } } }}&gt;\n          &lt;<span class=\"c-tag\">Drawer</span>\n            <span class=\"c-attr\">open</span>={detailOpen}\n            <span class=\"c-attr\">onClose</span>={() =&gt; setDetailOpen(<span class=\"c-val\">false</span>)}\n            <span class=\"c-attr\">title</span>=<span class=\"c-val\">\"Edit Detail\"</span>\n            <span class=\"c-attr\">width</span>={<span class=\"c-val\">320</span>}\n            <span class=\"c-attr\">variant</span>=<span class=\"c-val\">\"overlay\"</span>\n            <span class=\"c-attr\">footer</span>={\n              &lt;<span class=\"c-tag\">DrawerFooter</span>\n                <span class=\"c-attr\">onCancel</span>={() =&gt; setDetailOpen(<span class=\"c-val\">false</span>)}\n                <span class=\"c-attr\">onConfirm</span>={() =&gt; setDetailOpen(<span class=\"c-val\">false</span>)}\n                <span class=\"c-attr\">confirmLabel</span>=<span class=\"c-val\">\"Save\"</span>\n              /&gt;\n            }\n          &gt;\n            &lt;<span class=\"c-tag\">div</span> <span class=\"c-attr\">style</span>={{ padding: <span class=\"c-val\">'24px'</span> }}&gt;Child drawer content.&lt;/<span class=\"c-tag\">div</span>&gt;\n          &lt;/<span class=\"c-tag\">Drawer</span>&gt;\n        &lt;/<span class=\"c-tag\">ConfigProvider</span>&gt;\n      &lt;/<span class=\"c-tag\">Drawer</span>&gt;\n    &lt;/<span class=\"c-tag\">ConfigProvider</span>&gt;\n  );\n};\n\n<span class=\"c-kw\">export default</span> MultiPanelExample;</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ⑨ DrawerFooter.jsx -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">9</span>\n        <h3 class=\"ds-prop-title\">DrawerFooter.jsx</h3>\n      </div>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">TypeScript · React</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-footer',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-footer\"><span class=\"c-kw\">import</span> React <span class=\"c-kw\">from</span> <span class=\"c-val\">'react'</span>;\n<span class=\"c-kw\">import</span> { Button, Space, ConfigProvider } <span class=\"c-kw\">from</span> <span class=\"c-val\">'antd'</span>;\n<span class=\"c-kw\">import</span> gsTheme <span class=\"c-kw\">from</span> <span class=\"c-val\">'../../theme/gs-theme'</span>;\n\n<span class=\"c-kw\">interface</span> <span class=\"c-type\">DrawerFooterProps</span> {\n  onCancel:       () =&gt; <span class=\"c-type\">void</span>;\n  onConfirm:      () =&gt; <span class=\"c-type\">void</span>;\n  confirmLabel?:  <span class=\"c-type\">string</span>;\n  cancelLabel?:   <span class=\"c-type\">string</span>;\n  loading?:       <span class=\"c-type\">boolean</span>;\n  confirmDanger?: <span class=\"c-type\">boolean</span>;\n}\n\n<span class=\"c-kw\">const</span> DrawerFooter: <span class=\"c-type\">React.FC</span>&lt;<span class=\"c-type\">DrawerFooterProps</span>&gt; = ({\n  onCancel,\n  onConfirm,\n  confirmLabel  = <span class=\"c-val\">'Apply'</span>,\n  cancelLabel   = <span class=\"c-val\">'Cancel'</span>,\n  loading       = <span class=\"c-val\">false</span>,\n  confirmDanger = <span class=\"c-val\">false</span>,\n}) =&gt; (\n  &lt;<span class=\"c-tag\">ConfigProvider</span> <span class=\"c-attr\">theme</span>={gsTheme}&gt;\n    &lt;<span class=\"c-tag\">Space</span>&gt;\n      &lt;<span class=\"c-tag\">Button</span> <span class=\"c-attr\">onClick</span>={onCancel}&gt;{cancelLabel}&lt;/<span class=\"c-tag\">Button</span>&gt;\n      &lt;<span class=\"c-tag\">Button</span>\n        <span class=\"c-attr\">type</span>=<span class=\"c-val\">\"primary\"</span>\n        <span class=\"c-attr\">danger</span>={confirmDanger}\n        <span class=\"c-attr\">loading</span>={loading}\n        <span class=\"c-attr\">onClick</span>={onConfirm}\n      &gt;\n        {confirmLabel}\n      &lt;/<span class=\"c-tag\">Button</span>&gt;\n    &lt;/<span class=\"c-tag\">Space</span>&gt;\n  &lt;/<span class=\"c-tag\">ConfigProvider</span>&gt;\n);\n\n<span class=\"c-kw\">export default</span> DrawerFooter;</pre>\n        </div>\n      </div>\n    </div>\n\n    <!-- ⑩ Accessibility -->\n    <div class=\"btn-code-section\">\n      <div class=\"ds-step-row\">\n        <span class=\"ds-step-num\">10</span>\n        <h3 class=\"ds-prop-title\">Accessibility</h3>\n      </div>\n\n      <p class=\"ds-label-upper\" style=\"margin-bottom:12px;\">ARIA roles &amp; attributes</p>\n      <div class=\"btn-code-block\" style=\"margin-bottom:20px;\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">JSX · ARIA markup</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-aria',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-aria\"><span class=\"c-cmt\">{/* Required ARIA attributes on the drawer root element */}</span>\n&lt;<span class=\"c-tag\">div</span>\n  <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"dialog\"</span>\n  <span class=\"c-attr\">aria-modal</span>=<span class=\"c-val\">\"true\"</span>              <span class=\"c-cmt\">// overlay only — tells AT content behind is inert</span>\n  <span class=\"c-attr\">aria-labelledby</span>=<span class=\"c-val\">\"drawer-title\"</span>  <span class=\"c-cmt\">// points to the visible title element</span>\n  <span class=\"c-attr\">aria-describedby</span>=<span class=\"c-val\">\"drawer-desc\"</span>  <span class=\"c-cmt\">// optional: points to a description paragraph</span>\n&gt;\n  &lt;<span class=\"c-tag\">h2</span> <span class=\"c-attr\">id</span>=<span class=\"c-val\">\"drawer-title\"</span>&gt;Edit Record&lt;/<span class=\"c-tag\">h2</span>&gt;\n  &lt;<span class=\"c-tag\">p</span>  <span class=\"c-attr\">id</span>=<span class=\"c-val\">\"drawer-desc\"</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"sr-only\"</span>&gt;\n    Use this panel to edit the selected record. Press Escape to close.\n  &lt;/<span class=\"c-tag\">p</span>&gt;\n\n  {<span class=\"c-cmt\">/* Loading state announced to screen readers */</span>}\n  &lt;<span class=\"c-tag\">div</span> <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-live</span>=<span class=\"c-val\">\"polite\"</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"sr-only\"</span>&gt;\n    {loading ? <span class=\"c-val\">'Loading content'</span> : <span class=\"c-val\">''</span>}\n  &lt;/<span class=\"c-tag\">div</span>&gt;\n\n  <span class=\"c-cmt\">{/* drawer content ... */}</span>\n&lt;/<span class=\"c-tag\">div</span>&gt;</pre>\n        </div>\n      </div>\n\n      <p class=\"ds-label-upper\" style=\"margin-bottom:12px;\">useFocusTrap hook</p>\n      <div class=\"btn-code-block\">\n        <div class=\"btn-code-head\">\n          <span class=\"btn-code-lang\">TypeScript · Custom Hook</span>\n          <button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sd-code-a11y',this)\">Copy</button>\n        </div>\n        <div class=\"btn-code-body\">\n          <pre id=\"sd-code-a11y\"><span class=\"c-kw\">import</span> { useRef, useEffect, <span class=\"c-type\">RefObject</span> } <span class=\"c-kw\">from</span> <span class=\"c-val\">'react'</span>;\n\n<span class=\"c-kw\">const</span> FOCUSABLE_SELECTORS = <span class=\"c-val\">[</span>\n  <span class=\"c-val\">'a[href]'</span>,\n  <span class=\"c-val\">'button:not([disabled])'</span>,\n  <span class=\"c-val\">'input:not([disabled])'</span>,\n  <span class=\"c-val\">'select:not([disabled])'</span>,\n  <span class=\"c-val\">'textarea:not([disabled])'</span>,\n  <span class=\"c-val\">'[tabindex]:not([tabindex=\"-1\"])'</span>,\n<span class=\"c-val\">].join(</span><span class=\"c-val\">','</span><span class=\"c-val\">)</span>;\n\n<span class=\"c-cmt\">/**\n * useFocusTrap\n *\n * Traps keyboard focus within `ref` while `isOpen` is true.\n * On open  → moves focus to the first focusable element.\n * Tab      → cycles forward through focusable elements, wraps at end.\n * Shift+Tab→ cycles backward, wraps at start.\n * Escape   → calls `onClose`.\n * On close → restores focus to the element that triggered the drawer.\n */</span>\n<span class=\"c-kw\">export function</span> useFocusTrap(\n  ref: <span class=\"c-type\">RefObject</span>&lt;<span class=\"c-type\">HTMLElement</span>&gt;,\n  isOpen: <span class=\"c-type\">boolean</span>,\n  onClose?: () =&gt; <span class=\"c-type\">void</span>\n): <span class=\"c-type\">void</span> {\n  <span class=\"c-kw\">const</span> triggerRef = useRef&lt;<span class=\"c-type\">HTMLElement</span> | <span class=\"c-type\">null</span>&gt;(<span class=\"c-val\">null</span>);\n\n  <span class=\"c-cmt\">// Capture trigger element &amp; restore focus on close</span>\n  useEffect(() =&gt; {\n    <span class=\"c-kw\">if</span> (isOpen) {\n      triggerRef.current = document.activeElement <span class=\"c-kw\">as</span> <span class=\"c-type\">HTMLElement</span>;\n    } <span class=\"c-kw\">else</span> {\n      triggerRef.current?.focus();\n    }\n  }, [isOpen]);\n\n  <span class=\"c-cmt\">// Move focus to first element on open</span>\n  useEffect(() =&gt; {\n    <span class=\"c-kw\">if</span> (!isOpen || !ref.current) <span class=\"c-kw\">return</span>;\n    <span class=\"c-kw\">const</span> first = ref.current.querySelector&lt;<span class=\"c-type\">HTMLElement</span>&gt;(FOCUSABLE_SELECTORS);\n    first?.focus();\n  }, [isOpen, ref]);\n\n  <span class=\"c-cmt\">// Trap tab + handle Escape</span>\n  useEffect(() =&gt; {\n    <span class=\"c-kw\">if</span> (!isOpen || !ref.current) <span class=\"c-kw\">return</span>;\n\n    <span class=\"c-kw\">const</span> el = ref.current;\n\n    <span class=\"c-kw\">const</span> handleKeyDown = (e: <span class=\"c-type\">KeyboardEvent</span>) =&gt; {\n      <span class=\"c-kw\">if</span> (e.key === <span class=\"c-val\">'Escape'</span>) {\n        e.preventDefault();\n        onClose?.();\n        <span class=\"c-kw\">return</span>;\n      }\n\n      <span class=\"c-kw\">if</span> (e.key !== <span class=\"c-val\">'Tab'</span>) <span class=\"c-kw\">return</span>;\n\n      <span class=\"c-kw\">const</span> focusable = Array.from(\n        el.querySelectorAll&lt;<span class=\"c-type\">HTMLElement</span>&gt;(FOCUSABLE_SELECTORS)\n      ).filter(n =&gt; !n.closest(<span class=\"c-val\">'[aria-hidden=\"true\"]'</span>));\n\n      <span class=\"c-kw\">if</span> (!focusable.length) { e.preventDefault(); <span class=\"c-kw\">return</span>; }\n\n      <span class=\"c-kw\">const</span> first = focusable[<span class=\"c-val\">0</span>];\n      <span class=\"c-kw\">const</span> last  = focusable[focusable.length - <span class=\"c-val\">1</span>];\n\n      <span class=\"c-kw\">if</span> (e.shiftKey &amp;&amp; document.activeElement === first) {\n        e.preventDefault();\n        last.focus();\n      } <span class=\"c-kw\">else if</span> (!e.shiftKey &amp;&amp; document.activeElement === last) {\n        e.preventDefault();\n        first.focus();\n      }\n    };\n\n    el.addEventListener(<span class=\"c-val\">'keydown'</span>, handleKeyDown);\n    <span class=\"c-kw\">return</span> () =&gt; el.removeEventListener(<span class=\"c-val\">'keydown'</span>, handleKeyDown);\n  }, [isOpen, ref, onClose]);\n}\n\n<span class=\"c-cmt\">// ─── Usage ────────────────────────────────────────────────</span>\n<span class=\"c-cmt\">// const drawerRef = useRef&lt;HTMLDivElement&gt;(null);</span>\n<span class=\"c-cmt\">// useFocusTrap(drawerRef, isOpen, onClose);</span>\n<span class=\"c-cmt\">// &lt;div ref={drawerRef} role=\"dialog\" aria-modal=\"true\"&gt;...&lt;/div&gt;</span></pre>\n        </div>\n      </div>\n    </div>\n\n  </div><!-- /Implementation card -->\n\n</div><!-- /slideout-pane-code -->\n\n<!-- ========== USAGE TAB ========== -->\n<div id=\"slideout-pane-usage\" class=\"btn-tab-pane slideout-tab-pane\">\n  <div class=\"ds-card ds-coming-soon\">Slideout usage documentation coming soon</div>\n</div>\n";
  }

  window.PAGES_BUNDLE["loading-skeleton"] = "<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n     SKELETON \u2014 Pelagos Design System\n     Ref: Ant Design Skeleton \u00b7 https://ant.design/components/skeleton\n     Prefix: skel\n     \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<style>\n/* \u2500\u2500 Skeleton component tokens \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n   Ant Design Token         \u2192 GeoServe mapping\n   blockRadius:4            \u2192 4px  (text/block shapes)\n   gradientFromColor        \u2192 var(--prim-grey-50,  #F1F5F9)\n   gradientToColor          \u2192 var(--prim-grey-100, #E2E8F0)\n   paragraphLiHeight:16     \u2192 16px line height\n   paragraphMarginTop:28    \u2192 28px gap between title and paragraph\n   titleHeight:16           \u2192 16px\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n:root {\n  --skel-from:    var(--prim-grey-50,  #F1F5F9);\n  --skel-to:      var(--prim-grey-100, #E2E8F0);\n  --skel-radius:  4px;       /* blockRadius token  */\n  --skel-circle:  50%;\n  --skel-title-h: 16px;      /* titleHeight token  */\n  --skel-para-lh: 16px;      /* paragraphLiHeight  */\n  --skel-para-mt: 28px;      /* paragraphMarginTop */\n}\n\n/* \u2500\u2500 Base shimmer block \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-block {\n  display: block;\n  background: linear-gradient(\n    90deg,\n    var(--skel-from) 25%,\n    var(--skel-to)   50%,\n    var(--skel-from) 75%\n  );\n  background-size: 600px 100%;\n  border-radius: var(--skel-radius);\n  animation: none; /* static by default; active adds shimmer */\n}\n\n/* \u2500\u2500 Active (animated) state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-active .skel-block {\n  animation: skel-shimmer 1.5s ease-in-out infinite;\n}\n@keyframes skel-shimmer {\n  0%   { background-position:  600px 0; }\n  100% { background-position: -600px 0; }\n}\n\n/* \u2500\u2500 Shape modifiers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-block--circle  { border-radius: var(--skel-circle); }\n.skel-block--round   { border-radius: 100px; }\n.skel-block--square  { border-radius: 0; }\n\n/* \u2500\u2500 Composite: paragraph preset \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-paragraph { display: flex; flex-direction: column; gap: 8px; }\n.skel-paragraph .skel-block { height: var(--skel-para-lh); }\n.skel-paragraph .skel-block:last-child { width: 61%; } /* Ant Design default last-row width */\n\n/* \u2500\u2500 Composite: title preset \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-title { margin-bottom: var(--skel-para-mt); }\n.skel-title .skel-block { height: var(--skel-title-h); width: 38%; }\n\n/* \u2500\u2500 Composite: avatar preset \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-avatar-wrap { display: flex; gap: 16px; align-items: flex-start; }\n.skel-avatar      { flex-shrink: 0; }\n\n/* \u2500\u2500 Size helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-block--sm  { height: 24px; }\n.skel-block--md  { height: 32px; }\n.skel-block--lg  { height: 40px; }\n\n/* \u2500\u2500 Demo helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.skel-demo-surface {\n  background: #f8fafc;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  padding: 28px 24px;\n}\n.skel-demo-label {\n  font-size: 11px;\n  font-weight: 600;\n  color: #94a3b8;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  margin-bottom: 12px;\n}\n\n/* Reduced-motion: pause */\n@media (prefers-reduced-motion: reduce) {\n  .skel-active .skel-block { animation: none; }\n}\n</style>\n\n<!-- BANNER -->\n<div class=\"page-header\">\n  <h1 class=\"ds-hero-title\">Skeleton</h1>\n</div>\n\n<!-- TAB BAR -->\n<div class=\"btn-tab-bar\">\n  <button class=\"btn-tab-btn skel-tab-btn active\" data-tab=\"design\" onclick=\"switchSkeletonTab('design')\">Design</button>\n  <button class=\"btn-tab-btn skel-tab-btn\"        data-tab=\"code\"   onclick=\"switchSkeletonTab('code')\">Code</button>\n  <button class=\"btn-tab-btn skel-tab-btn\"        data-tab=\"usage\"  onclick=\"switchSkeletonTab('usage')\">Usage</button>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n     DESIGN TAB\n     \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div id=\"skel-tab-design\" class=\"btn-tab-pane skel-tab-pane active\">\n  <div class=\"code-tab-layout\">\n    <div class=\"code-tab-main\">\n\n      <!-- 1 \u00b7 OVERVIEW \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-overview\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Overview</div>\n        <p class=\"btn-family-desc\">Skeleton provides animated placeholder shapes that mirror the structure of incoming content \u2014 reducing perceived load time and preventing layout shift. It is built over the Ant Design Skeleton spec with GeoServe tokens applied to colour, radius, and timing. Use it for first-load states where the layout is known but the data is not yet available.</p>\n\n        <div class=\"btn-preview-strip\" style=\"display:flex;gap:40px;align-items:flex-start;flex-wrap:wrap;padding:28px 24px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;margin-top:16px;\" >\n          <div style=\"pointer-events:none;flex:1;min-width:220px;max-width:320px;\">\n            <!-- Skeleton with avatar \u2014 static default -->\n            <div class=\"skel-avatar-wrap\">\n              <div class=\"skel-avatar\">\n                <div class=\"skel-block skel-block--circle\" style=\"width:40px;height:40px;\"></div>\n              </div>\n              <div style=\"flex:1;\">\n                <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:38%;\"></div></div>\n                <div class=\"skel-paragraph\">\n                  <div class=\"skel-block\" style=\"width:100%;\"></div>\n                  <div class=\"skel-block\" style=\"width:94%;\"></div>\n                  <div class=\"skel-block\" style=\"width:61%;\"></div>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div style=\"pointer-events:none;flex:1;min-width:220px;max-width:320px;\">\n            <!-- Skeleton active (animated) -->\n            <div class=\"skel-active\">\n              <div class=\"skel-avatar-wrap\">\n                <div class=\"skel-avatar\">\n                  <div class=\"skel-block skel-block--circle\" style=\"width:40px;height:40px;\"></div>\n                </div>\n                <div style=\"flex:1;\">\n                  <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:38%;\"></div></div>\n                  <div class=\"skel-paragraph\">\n                    <div class=\"skel-block\" style=\"width:100%;\"></div>\n                    <div class=\"skel-block\" style=\"width:94%;\"></div>\n                    <div class=\"skel-block\" style=\"width:61%;\"></div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div style=\"display:flex;gap:8px;margin-top:12px;flex-wrap:wrap;\">\n          <span style=\"font-size:11px;color:#64748b;background:#f1f5f9;border-radius:4px;padding:2px 8px;\">\u2190 Static (default)</span>\n          <span style=\"font-size:11px;color:#1852FE;background:#dbeafe;border-radius:4px;padding:2px 8px;\">\u2190 Active / animated</span>\n        </div>\n\n        <div class=\"btn-when-examples\" style=\"margin-top:16px;\">\n          <span class=\"btn-when-example-tag\">5 element types</span>\n          <span class=\"btn-when-example-tag\">Static + Active states</span>\n          <span class=\"btn-when-example-tag\">3 sub-components</span>\n          <span class=\"btn-when-example-tag\">GeoServe tokens</span>\n          <span class=\"btn-when-example-tag\">WCAG AA</span>\n        </div>\n      </div>\n\n      <!-- 2 \u00b7 ANATOMY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-anatomy\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Anatomy</div>\n        <p class=\"btn-family-desc\">A full Skeleton is composed of up to four parts: avatar circle, title bar, paragraph rows, and the optional active shimmer overlay. Each part maps directly to an Ant Design sub-prop.</p>\n\n        <div style=\"background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:32px;display:flex;justify-content:center;margin-top:8px;overflow:auto;\">\n          <svg width=\"560\" height=\"180\" viewBox=\"0 0 560 180\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"min-width:400px;\">\n            <!-- Avatar circle -->\n            <rect x=\"40\" y=\"56\" width=\"48\" height=\"48\" rx=\"24\" fill=\"#E2E8F0\"/>\n            <!-- Title bar -->\n            <rect x=\"108\" y=\"56\" width=\"130\" height=\"16\" rx=\"4\" fill=\"#E2E8F0\"/>\n            <!-- Paragraph rows -->\n            <rect x=\"108\" y=\"100\" width=\"380\" height=\"16\" rx=\"4\" fill=\"#E2E8F0\"/>\n            <rect x=\"108\" y=\"124\" width=\"350\" height=\"16\" rx=\"4\" fill=\"#E2E8F0\"/>\n            <rect x=\"108\" y=\"148\" width=\"240\" height=\"16\" rx=\"4\" fill=\"#E2E8F0\"/>\n\n            <!-- \u2460 Avatar label -->\n            <circle cx=\"22\" cy=\"80\" r=\"10\" fill=\"#1852FE\"/>\n            <text x=\"22\" y=\"84\" text-anchor=\"middle\" fill=\"white\" font-size=\"11\" font-weight=\"700\" font-family=\"Helvetica,Arial,sans-serif\">1</text>\n            <line x1=\"32\" y1=\"80\" x2=\"40\" y2=\"80\" stroke=\"#CBD5E1\" stroke-width=\"1\"/>\n\n            <!-- \u2461 Title label -->\n            <circle cx=\"173\" cy=\"36\" r=\"10\" fill=\"#1852FE\"/>\n            <text x=\"173\" y=\"40\" text-anchor=\"middle\" fill=\"white\" font-size=\"11\" font-weight=\"700\" font-family=\"Helvetica,Arial,sans-serif\">2</text>\n            <line x1=\"173\" y1=\"46\" x2=\"173\" y2=\"56\" stroke=\"#CBD5E1\" stroke-width=\"1\"/>\n            <text x=\"156\" y=\"28\" text-anchor=\"middle\" fill=\"#475569\" font-size=\"11\" font-family=\"Helvetica,Arial,sans-serif\">Title</text>\n\n            <!-- \u2462 Paragraph rows label -->\n            <circle cx=\"510\" cy=\"124\" r=\"10\" fill=\"#1852FE\"/>\n            <text x=\"510\" y=\"128\" text-anchor=\"middle\" fill=\"white\" font-size=\"11\" font-weight=\"700\" font-family=\"Helvetica,Arial,sans-serif\">3</text>\n            <line x1=\"500\" y1=\"124\" x2=\"488\" y2=\"124\" stroke=\"#CBD5E1\" stroke-width=\"1\"/>\n            <text x=\"530\" y=\"128\" text-anchor=\"middle\" fill=\"#475569\" font-size=\"11\" font-family=\"Helvetica,Arial,sans-serif\"></text>\n\n            <!-- \u2463 Last row (61% width) label -->\n            <circle cx=\"360\" cy=\"170\" r=\"10\" fill=\"#1852FE\"/>\n            <text x=\"360\" y=\"174\" text-anchor=\"middle\" fill=\"white\" font-size=\"11\" font-weight=\"700\" font-family=\"Helvetica,Arial,sans-serif\">4</text>\n            <line x1=\"350\" y1=\"162\" x2=\"350\" y2=\"156\" stroke=\"#CBD5E1\" stroke-width=\"1\"/>\n\n            <!-- dimension: title height -->\n            <line x1=\"510\" y1=\"56\" x2=\"510\" y2=\"72\" stroke=\"#94A3B8\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n            <text x=\"520\" y=\"66\" fill=\"#94A3B8\" font-size=\"10\" font-family=\"Helvetica,Arial,sans-serif\">16px</text>\n\n            <!-- Labels beside diagram -->\n            <text x=\"22\" y=\"95\" text-anchor=\"middle\" fill=\"#475569\" font-size=\"10\" font-family=\"Helvetica,Arial,sans-serif\">Avatar</text>\n            <text x=\"510\" y=\"118\" text-anchor=\"start\" fill=\"#475569\" font-size=\"10\" font-family=\"Helvetica,Arial,sans-serif\">Rows</text>\n            <text x=\"340\" y=\"168\" text-anchor=\"start\" fill=\"#475569\" font-size=\"10\" font-family=\"Helvetica,Arial,sans-serif\">Last</text>\n          </svg>\n        </div>\n\n        <ol style=\"margin-top:20px;display:flex;flex-direction:column;gap:8px;padding-left:20px;\">\n          <li><strong>Avatar</strong> \u2014 Optional circle (or square) placeholder. Enabled via <code>avatar</code> prop. Sizes: <code>small</code> (24px), <code>default</code> (32px), <code>large</code> (40px).</li>\n          <li><strong>Title</strong> \u2014 Single bar representing a heading. Height: <code>16px</code> (<code>titleHeight</code> token). Width defaults to <code>38%</code>; overridable.</li>\n          <li><strong>Paragraph rows</strong> \u2014 Stack of bars representing body text. Row height: <code>16px</code> (<code>paragraphLiHeight</code>). Default: 3 rows. Gap above paragraph: <code>28px</code> (<code>paragraphMarginTop</code>).</li>\n          <li><strong>Last paragraph row</strong> \u2014 Always rendered at <code>61%</code> width by default to mimic natural text wrap. Override with <code>paragraph.width</code> array.</li>\n        </ol>\n      </div>\n\n      <!-- 3 \u00b7 VARIANTS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-variants\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Variants</div>\n        <p class=\"btn-family-desc\">Five element variants mirror common content shapes. Combine <code>Skeleton</code> (paragraph), <code>Skeleton.Avatar</code>, <code>Skeleton.Button</code>, <code>Skeleton.Input</code>, and <code>Skeleton.Image</code> to replicate any layout.</p>\n\n        <!-- Paragraph (default) -->\n        <div class=\"btn-variant-row\">\n          <span class=\"btn-variant-label\">Paragraph</span>\n          <div class=\"btn-variant-sizes\" style=\"pointer-events:none;\">\n            <div class=\"skel-active\" style=\"max-width:360px;\">\n              <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:38%;\"></div></div>\n              <div class=\"skel-paragraph\">\n                <div class=\"skel-block\" style=\"width:100%;\"></div>\n                <div class=\"skel-block\" style=\"width:94%;\"></div>\n                <div class=\"skel-block\" style=\"width:61%;\"></div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Avatar + Paragraph -->\n        <div class=\"btn-variant-row\">\n          <span class=\"btn-variant-label\">With Avatar</span>\n          <div class=\"btn-variant-sizes\" style=\"pointer-events:none;\">\n            <div class=\"skel-active\" style=\"max-width:360px;\">\n              <div class=\"skel-avatar-wrap\">\n                <div class=\"skel-block skel-block--circle\" style=\"width:40px;height:40px;flex-shrink:0;\"></div>\n                <div style=\"flex:1;\">\n                  <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:38%;\"></div></div>\n                  <div class=\"skel-paragraph\">\n                    <div class=\"skel-block\" style=\"width:100%;\"></div>\n                    <div class=\"skel-block\" style=\"width:61%;\"></div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Button variants -->\n        <div class=\"btn-variant-row\">\n          <span class=\"btn-variant-label\">Button</span>\n          <div class=\"btn-variant-sizes\" style=\"pointer-events:none;display:flex;gap:10px;flex-wrap:wrap;align-items:center;\">\n            <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:88px;height:32px;border-radius:8px;\"></div></div>\n            <div class=\"skel-active\"><div class=\"skel-block skel-block--round\" style=\"width:88px;height:32px;\"></div></div>\n            <div class=\"skel-active\"><div class=\"skel-block skel-block--circle\" style=\"width:32px;height:32px;\"></div></div>\n            <span style=\"font-size:11px;color:#9CA3AF;\">Default \u00b7 Round \u00b7 Circle</span>\n          </div>\n        </div>\n\n        <!-- Input -->\n        <div class=\"btn-variant-row\">\n          <span class=\"btn-variant-label\">Input</span>\n          <div class=\"btn-variant-sizes\" style=\"pointer-events:none;display:flex;gap:10px;flex-wrap:wrap;align-items:center;\">\n            <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:64px;height:24px;border-radius:4px;\"></div></div>\n            <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:120px;height:32px;border-radius:4px;\"></div></div>\n            <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:160px;height:40px;border-radius:4px;\"></div></div>\n            <span style=\"font-size:11px;color:#9CA3AF;\">Small \u00b7 Medium \u00b7 Large</span>\n          </div>\n        </div>\n\n        <!-- Image -->\n        <div class=\"btn-variant-row\">\n          <span class=\"btn-variant-label\">Image</span>\n          <div class=\"btn-variant-sizes\" style=\"pointer-events:none;\">\n            <div class=\"skel-active\">\n              <div class=\"skel-block\" style=\"width:96px;height:96px;border-radius:8px;display:flex;align-items:center;justify-content:center;\">\n                <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#CBD5E1\" stroke-width=\"1.5\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"/><polyline points=\"21 15 16 10 5 21\"/></svg>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 4 \u00b7 STATES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-states\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">States</div>\n        <p class=\"btn-family-desc\">Skeleton has two visual states \u2014 <strong>static</strong> (default, no animation) and <strong>active</strong> (shimmer wave). A third state is the post-load reveal, when real content fades in to replace the skeleton.</p>\n\n        <div class=\"btn-sub-label\" style=\"margin-bottom:12px;\">State matrix</div>\n        <div class=\"btn-states-grid\" style=\"grid-template-columns:repeat(3,1fr);\">\n          <!-- Static -->\n          <div class=\"btn-state-cell\">\n            <div style=\"pointer-events:none;padding:16px;border:1px solid #E2E8F0;border-radius:8px;background:#fff;\">\n              <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:40%;\"></div></div>\n              <div class=\"skel-paragraph\">\n                <div class=\"skel-block\" style=\"width:100%;\"></div>\n                <div class=\"skel-block\" style=\"width:80%;\"></div>\n                <div class=\"skel-block\" style=\"width:61%;\"></div>\n              </div>\n            </div>\n            <span class=\"btn-state-label\">Static (default)</span>\n          </div>\n          <!-- Active -->\n          <div class=\"btn-state-cell\">\n            <div style=\"pointer-events:none;padding:16px;border:1px solid #E2E8F0;border-radius:8px;background:#fff;\">\n              <div class=\"skel-active\">\n                <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:40%;\"></div></div>\n                <div class=\"skel-paragraph\">\n                  <div class=\"skel-block\" style=\"width:100%;\"></div>\n                  <div class=\"skel-block\" style=\"width:80%;\"></div>\n                  <div class=\"skel-block\" style=\"width:61%;\"></div>\n                </div>\n              </div>\n            </div>\n            <span class=\"btn-state-label\">Active (animated)</span>\n          </div>\n          <!-- Loaded -->\n          <div class=\"btn-state-cell\">\n            <div style=\"pointer-events:none;padding:16px;border:1px solid #E2E8F0;border-radius:8px;background:#fff;\">\n              <div style=\"font-size:14px;font-weight:600;color:#0F1B35;margin-bottom:8px;\">STI Garnet</div>\n              <div style=\"font-size:12px;color:#64748B;line-height:1.6;\">Singapore, SGP \u00b7 VLSFO 0.5% \u00b7 Booked</div>\n            </div>\n            <span class=\"btn-state-label\">Loaded (content revealed)</span>\n          </div>\n        </div>\n\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:8px;\">Token reference</div>\n        <table>\n          <thead><tr><th>Token</th><th>Ant Design name</th><th>GeoServe value</th><th>Purpose</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">--skel-from</td><td>gradientFromColor</td><td><code>#F1F5F9</code> (grey/50)</td><td>Shimmer background base</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">--skel-to</td><td>gradientToColor</td><td><code>#E2E8F0</code> (grey/100)</td><td>Shimmer highlight peak</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">--skel-radius</td><td>blockRadius</td><td><code>4px</code></td><td>Corner radius for all blocks</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">--skel-title-h</td><td>titleHeight</td><td><code>16px</code></td><td>Title bar height</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">--skel-para-lh</td><td>paragraphLiHeight</td><td><code>16px</code></td><td>Each paragraph row height</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">--skel-para-mt</td><td>paragraphMarginTop</td><td><code>28px</code></td><td>Gap between title and paragraph</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <!-- 5 \u00b7 INTERACTIONS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-interaction\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Interactions</div>\n        <table>\n          <thead><tr><th>Trigger</th><th>Behaviour</th><th>Timing</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td>Data resolves (<code>loading: false</code>)</td><td>Skeleton unmounts; real content renders in-place with no layout shift</td><td>Immediate</td></tr>\n            <tr class=\"ds-tr-border\"><td>300ms threshold</td><td>If data resolves in &lt;300ms, skeleton is never shown (prevents flicker)</td><td>300ms delay gate</td></tr>\n            <tr class=\"ds-tr-border\"><td>Active prop applied</td><td>Shimmer gradient sweeps right-to-left at 1.5s ease-in-out, looping infinitely</td><td>1.5s ease-in-out \u221e</td></tr>\n            <tr class=\"ds-tr-border\"><td><code>prefers-reduced-motion</code></td><td>Animation paused; skeleton remains visible as static placeholder</td><td>Instant</td></tr>\n            <tr class=\"ds-tr-border\"><td>10s timeout (fallback)</td><td>Replace skeleton with an error empty state and retry action</td><td>10 000ms</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <!-- 6 \u00b7 ACCESSIBILITY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-a11y\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Accessibility</div>\n\n        <div class=\"btn-sub-label\">Semantic element</div>\n        <p class=\"btn-family-desc\">The skeleton container is a standard <code>&lt;div&gt;</code>. It is not interactive and receives no focus. Screen readers must be informed of the loading state via the parent region.</p>\n\n        <div class=\"btn-sub-label\" style=\"margin-top:16px;\">ARIA attributes</div>\n        <table>\n          <thead><tr><th>Attribute</th><th>Value</th><th>Where to apply</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td><code>aria-busy</code></td><td><code>\"true\"</code> while loading, <code>\"false\"</code> after</td><td>Outermost content region, not the skeleton block itself</td></tr>\n            <tr class=\"ds-tr-border\"><td><code>aria-label</code></td><td>e.g. <code>\"Loading vessel list\"</code></td><td>The region element, describing what is loading</td></tr>\n            <tr class=\"ds-tr-border\"><td><code>aria-hidden</code></td><td><code>\"true\"</code></td><td>On the skeleton blocks \u2014 purely decorative, screen readers should skip them</td></tr>\n            <tr class=\"ds-tr-border\"><td><code>role=\"status\"</code></td><td>\u2014</td><td>On a visually-hidden live region that announces \"Loading\" and then \"Loaded\"</td></tr>\n          </tbody>\n        </table>\n\n        <div class=\"btn-sub-label\" style=\"margin-top:16px;\">Keyboard navigation</div>\n        <table>\n          <thead><tr><th>Key</th><th>Action</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td><kbd>Tab</kbd></td><td>Focus skips the skeleton entirely \u2014 no interactive elements inside</td></tr>\n          </tbody>\n        </table>\n\n        <div class=\"btn-sub-label\" style=\"margin-top:16px;\">Contrast ratios</div>\n        <table>\n          <thead><tr><th>Element</th><th>From</th><th>To</th><th>Against page bg</th><th>WCAG</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td>Skeleton block</td><td><code>#F1F5F9</code></td><td><code>#E2E8F0</code></td><td>White <code>#FFFFFF</code></td><td>Decorative \u2014 exempt (1.4.11)</td></tr>\n          </tbody>\n        </table>\n        <p class=\"btn-family-desc\" style=\"margin-top:8px;\">Skeleton blocks are purely decorative and are therefore exempt from WCAG 1.4.3 contrast requirements. Ensure the actual revealed content meets contrast requirements.</p>\n      </div>\n\n      <!-- 7 \u00b7 RESPONSIVE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-responsive\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Responsive Behaviour</div>\n        <table>\n          <thead><tr><th>Breakpoint</th><th>Behaviour</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td>&gt; 1024px</td><td>Full width within its container. Avatar + paragraph side-by-side at full row width.</td></tr>\n            <tr class=\"ds-tr-border\"><td>768px \u2013 1024px</td><td>Skeleton scales with its parent grid columns. No structural changes.</td></tr>\n            <tr class=\"ds-tr-border\"><td>&lt; 768px</td><td>Avatar stacks above the paragraph group (flex-direction: column). Paragraph rows reduce to container width.</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <!-- 8 \u00b7 DO / DON'T (optional) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-dosdonts\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Do / Don't</div>\n        <div class=\"btn-dos-donts\">\n          <div class=\"btn-do-card\">\n            <div class=\"btn-do-header\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n              Do\n            </div>\n            <ul>\n              <li>\n                <div class=\"btn-do-example\" style=\"pointer-events:none;\">\n                  <div class=\"skel-active\" style=\"max-width:260px;\">\n                    <div class=\"skel-avatar-wrap\">\n                      <div class=\"skel-block skel-block--circle\" style=\"width:36px;height:36px;flex-shrink:0;\"></div>\n                      <div style=\"flex:1;\">\n                        <div class=\"skel-title\"><div class=\"skel-block\" style=\"width:50%;\"></div></div>\n                        <div class=\"skel-paragraph\">\n                          <div class=\"skel-block\" style=\"width:100%;\"></div>\n                          <div class=\"skel-block\" style=\"width:61%;\"></div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n                <p>Mirror the real content layout exactly \u2014 skeleton shape, size, and count should match the content it replaces.</p>\n              </li>\n              <li>\n                <div class=\"btn-do-example\" style=\"pointer-events:none;font-size:12px;color:#64748b;\">\n                  <code style=\"font-size:11px;\">aria-busy=\"true\"</code> on the parent region while loading\n                </div>\n                <p>Always set <code>aria-busy</code> on the surrounding content region so screen readers announce the loading state.</p>\n              </li>\n            </ul>\n          </div>\n          <div class=\"btn-dont-card\">\n            <div class=\"btn-dont-header\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n              Don't\n            </div>\n            <ul>\n              <li>\n                <div class=\"btn-dont-example\" style=\"pointer-events:none;\">\n                  <div style=\"display:flex;flex-direction:column;gap:4px;max-width:260px;\">\n                    <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:100%;height:12px;\"></div></div>\n                    <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:100%;height:12px;\"></div></div>\n                    <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:100%;height:12px;\"></div></div>\n                    <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:100%;height:12px;\"></div></div>\n                    <div class=\"skel-active\"><div class=\"skel-block\" style=\"width:100%;height:12px;\"></div></div>\n                    <span style=\"font-size:10px;color:#9CA3AF;\">All rows equal width \u2717</span>\n                  </div>\n                </div>\n                <p>Don't use equal widths on all paragraph rows \u2014 it looks mechanical. Vary widths (100%, 94%, 61%) for a natural feel.</p>\n              </li>\n              <li>\n                <div class=\"btn-dont-example\" style=\"pointer-events:none;font-size:12px;color:#64748b;\">\n                  Show skeleton + spinner simultaneously in the same region\n                </div>\n                <p>Don't mix Skeleton and Spinner in the same content area \u2014 choose one loading pattern per region.</p>\n              </li>\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <!-- 9 \u00b7 RELATED \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-s-related\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Related Components</div>\n        <ul class=\"btn-related-list\">\n          <li>\n            <button class=\"btn-inline-link\" onclick=\"navigate('loading-spinner')\">Spinner</button>\n            \u2014 Use instead of Skeleton when the content layout is unknown or when a background mutation (save, approve) is in progress.\n          </li>\n          <li>\n            <button class=\"btn-inline-link\" onclick=\"navigate('view-table')\">Table</button>\n            \u2014 The Table component ships with a built-in <code>.tbl-skeleton-row</code> pattern that uses these same tokens.\n          </li>\n          <li>\n            <button class=\"btn-inline-link\" onclick=\"navigate('nav-progress')\">Progress Bar</button>\n            \u2014 Use when percentage completion is known (file upload, multi-step wizard).\n          </li>\n        </ul>\n      </div>\n\n    </div><!-- /code-tab-main -->\n\n    <div class=\"code-tab-qnav\">\n      <div class=\"code-qnav-inner\">\n        <p class=\"code-qnav-title\">On This Page</p>\n        <ul class=\"code-qnav-list\">\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-overview')\">Overview</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-anatomy')\">Anatomy</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-variants')\">Variants</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-states')\">States</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-interaction')\">Interactions</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-a11y')\">Accessibility</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-responsive')\">Responsive</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-dosdonts')\">Do / Don't</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-s-related')\">Related</button></li>\n        </ul>\n      </div>\n    </div>\n  </div><!-- /code-tab-layout -->\n</div><!-- /skel-tab-design -->\n\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n     CODE TAB\n     \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div id=\"skel-tab-code\" class=\"btn-tab-pane skel-tab-pane\">\n\n  <div class=\"fw-toggle-bar\">\n    <button class=\"fw-toggle-bar-btn active\" data-fw=\"react\"\n            onclick=\"switchFw('skel-tab-code','react')\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n        <circle cx=\"12\" cy=\"12\" r=\"2.5\" fill=\"#61dafb\"/>\n        <ellipse cx=\"12\" cy=\"12\" rx=\"10\" ry=\"4.5\" stroke=\"#61dafb\" stroke-width=\"1.5\" fill=\"none\"/>\n        <ellipse cx=\"12\" cy=\"12\" rx=\"10\" ry=\"4.5\" stroke=\"#61dafb\" stroke-width=\"1.5\" fill=\"none\" transform=\"rotate(60 12 12)\"/>\n        <ellipse cx=\"12\" cy=\"12\" rx=\"10\" ry=\"4.5\" stroke=\"#61dafb\" stroke-width=\"1.5\" fill=\"none\" transform=\"rotate(120 12 12)\"/>\n      </svg>\n      React\n    </button>\n    <button class=\"fw-toggle-bar-btn\" data-fw=\"angular\"\n            onclick=\"switchFw('skel-tab-code','angular')\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n        <path d=\"M12 2L2 6.5l1.5 12.5L12 22l8.5-3L22 6.5 12 2z\" fill=\"#dd0031\"/>\n        <path d=\"M12 2v20M12 2L6 17h12L12 2z\" fill=\"none\" stroke=\"#fff\" stroke-width=\"1.2\"/>\n      </svg>\n      Angular\n    </button>\n  </div>\n\n  <div class=\"code-tab-layout\">\n    <div class=\"code-tab-main\">\n\n      <!-- 1 \u00b7 Overview \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-overview\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">1</span><div class=\"btn-family-title\" style=\"margin:0;\">Overview</div></div>\n        <div class=\"fw-react\">\n          <p class=\"btn-family-desc\">The <code>Skeleton</code> component wraps Ant Design's <code>Skeleton</code> with GeoServe CSS tokens applied to colours, border radius, and animation timing. Sub-components \u2014 <code>Skeleton.Avatar</code>, <code>Skeleton.Button</code>, <code>Skeleton.Input</code>, and <code>Skeleton.Image</code> \u2014 are re-exported unchanged.</p>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <p class=\"btn-family-desc\">Apply the <code>.skel-block</code> utility class to any element, then wrap in <code>.skel-active</code> to enable animation. The CSS is available globally in <code>styles.css</code> \u2014 no module imports needed.</p>\n        </div>\n      </div>\n\n      <!-- 2 \u00b7 Install \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-install\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">2</span><div class=\"btn-family-title\" style=\"margin:0;\">Install / Setup</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">bash</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-install-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-install-r\"><code><span class=\"c-cmt\"># antd is already a peer dependency of @pelagos/components</span>\nnpm install antd @pelagos/components</code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <p class=\"btn-family-desc\">Include <code>styles.css</code> in your project \u2014 the <code>.skel-block</code> and <code>.skel-active</code> classes are globally available. No additional packages required.</p>\n        </div>\n      </div>\n\n      <!-- 3 \u00b7 Import \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-imports\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">3</span><div class=\"btn-family-title\" style=\"margin:0;\">Import</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-import-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-import-r\"><code><span class=\"c-kw\">import</span> { <span class=\"c-type\">Skeleton</span> } <span class=\"c-kw\">from</span> <span class=\"c-val\">'@pelagos/components/loading/skeleton'</span>;\n<span class=\"c-cmt\">// Sub-components are attached: Skeleton.Avatar, Skeleton.Button, etc.</span></code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <p class=\"btn-family-desc\">No import needed. Add <code>class=\"skel-block\"</code> to any HTML element and wrap in <code>class=\"skel-active\"</code> to animate. Both classes are in the global <code>styles.css</code>.</p>\n        </div>\n      </div>\n\n      <!-- 4 \u00b7 API / Props \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-api\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">4</span><div class=\"btn-family-title\" style=\"margin:0;\">API / Props</div></div>\n\n        <!-- Skeleton (main) -->\n        <div class=\"btn-sub-label\" style=\"margin-bottom:8px;\">Skeleton</div>\n        <div class=\"fw-react\">\n          <table>\n            <thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">active</td><td class=\"ds-td-code-muted\">boolean</td><td class=\"ds-td-code-muted\">false</td><td>No</td><td class=\"ds-td-value\">Show shimmer animation</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">loading</td><td class=\"ds-td-code-muted\">boolean</td><td class=\"ds-td-code-muted\">\u2014</td><td>No</td><td class=\"ds-td-value\">Display skeleton when <code>true</code>; render <code>children</code> when <code>false</code></td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">avatar</td><td class=\"ds-td-code-muted\">boolean | SkeletonAvatarProps</td><td class=\"ds-td-code-muted\">false</td><td>No</td><td class=\"ds-td-value\">Show avatar placeholder. Pass object for size/shape control.</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">title</td><td class=\"ds-td-code-muted\">boolean | SkeletonTitleProps</td><td class=\"ds-td-code-muted\">true</td><td>No</td><td class=\"ds-td-value\">Show title bar. Pass <code>&#123; width: '50%' &#125;</code> to override width.</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">paragraph</td><td class=\"ds-td-code-muted\">boolean | SkeletonParagraphProps</td><td class=\"ds-td-code-muted\">true</td><td>No</td><td class=\"ds-td-value\">Show paragraph rows. Pass <code>&#123; rows: 4 &#125;</code> or <code>&#123; width: ['100%','80%','61%'] &#125;</code>.</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">round</td><td class=\"ds-td-code-muted\">boolean</td><td class=\"ds-td-code-muted\">false</td><td>No</td><td class=\"ds-td-value\">Apply <code>border-radius: 100px</code> to title and paragraph rows</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <table>\n            <thead><tr><th>CSS Class</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">skel-block</td><td>Base shimmer block \u2014 apply to any element</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">skel-active</td><td>Wrapper that enables shimmer animation on all <code>.skel-block</code> children</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">skel-block--circle</td><td>50% border-radius \u2014 use for avatar placeholders</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">skel-block--round</td><td>100px border-radius \u2014 pill / button shapes</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">skel-block--square</td><td>No border-radius \u2014 sharp corners</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">skel-block--sm / --md / --lg</td><td>Height presets: 24px / 32px / 40px</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <!-- Skeleton.Avatar -->\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:8px;\">Skeleton.Avatar</div>\n        <div class=\"fw-react\">\n          <table>\n            <thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">shape</td><td class=\"ds-td-code-muted\">'circle' | 'square'</td><td class=\"ds-td-code-muted\">'circle'</td><td class=\"ds-td-value\">Avatar shape</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">size</td><td class=\"ds-td-code-muted\">number | 'large' | 'medium' | 'small'</td><td class=\"ds-td-code-muted\">'medium'</td><td class=\"ds-td-value\">Avatar diameter. <code>small</code>=24, <code>medium</code>=32, <code>large</code>=40</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\"><p class=\"btn-family-desc\">Use <code>.skel-block.skel-block--circle</code> with explicit <code>width</code> and <code>height</code> inline styles.</p></div>\n\n        <!-- Skeleton.Button -->\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:8px;\">Skeleton.Button</div>\n        <div class=\"fw-react\">\n          <table>\n            <thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">shape</td><td class=\"ds-td-code-muted\">'default' | 'round' | 'circle' | 'square'</td><td class=\"ds-td-code-muted\">'default'</td><td class=\"ds-td-value\">Button shape</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">size</td><td class=\"ds-td-code-muted\">'large' | 'medium' | 'small'</td><td class=\"ds-td-code-muted\">'medium'</td><td class=\"ds-td-value\">Button height preset</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">block</td><td class=\"ds-td-code-muted\">boolean</td><td class=\"ds-td-code-muted\">false</td><td class=\"ds-td-value\">Stretch to full parent width</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\"><p class=\"btn-family-desc\">Use <code>.skel-block.skel-block--md</code> with the appropriate <code>border-radius</code> override for the desired button shape.</p></div>\n\n        <!-- Skeleton.Input -->\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:8px;\">Skeleton.Input</div>\n        <div class=\"fw-react\">\n          <table>\n            <thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">size</td><td class=\"ds-td-code-muted\">'large' | 'medium' | 'small'</td><td class=\"ds-td-code-muted\">'medium'</td><td class=\"ds-td-value\">Input height: small=24px, medium=32px, large=40px</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\"><p class=\"btn-family-desc\">Use <code>.skel-block.skel-block--sm / --md / --lg</code> at full width for input placeholders.</p></div>\n      </div>\n\n      <!-- 5 \u00b7 Variants \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-variants\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">5</span><div class=\"btn-family-title\" style=\"margin:0;\">Variants</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-variants-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-variants-r\"><code><span class=\"c-cmt\">// 1. Paragraph only (default)</span>\n<span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">active</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// 2. Avatar + paragraph</span>\n<span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">avatar</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// 3. Custom paragraph rows and widths</span>\n<span class=\"c-tag\">&lt;Skeleton</span>\n  <span class=\"c-attr\">active</span>\n  <span class=\"c-attr\">paragraph</span>={{ rows: 4, width: [<span class=\"c-val\">'100%'</span>, <span class=\"c-val\">'92%'</span>, <span class=\"c-val\">'85%'</span>, <span class=\"c-val\">'61%'</span>] }}\n<span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// 4. Button skeleton (round shape)</span>\n<span class=\"c-tag\">&lt;Skeleton.Button</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">shape</span>=<span class=\"c-val\">\"round\"</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// 5. Input skeleton (large)</span>\n<span class=\"c-tag\">&lt;Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"large\"</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// 6. Image skeleton</span>\n<span class=\"c-tag\">&lt;Skeleton.Image</span> <span class=\"c-attr\">active</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// 7. Avatar shape variants</span>\n<span class=\"c-tag\">&lt;Skeleton.Avatar</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">shape</span>=<span class=\"c-val\">\"circle\"</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"large\"</span> <span class=\"c-tag\">/&gt;</span>\n<span class=\"c-tag\">&lt;Skeleton.Avatar</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">shape</span>=<span class=\"c-val\">\"square\"</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"large\"</span> <span class=\"c-tag\">/&gt;</span></code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">HTML</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-variants-ng',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-variants-ng\"><code><span class=\"c-cmt\">&lt;!-- Paragraph (active) --&gt;</span>\n<span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-active\"</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:38%;margin-bottom:28px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:100%;margin-bottom:8px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:94%;margin-bottom:8px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:61%;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n<span class=\"c-tag\">&lt;/div&gt;</span>\n\n<span class=\"c-cmt\">&lt;!-- Avatar + paragraph --&gt;</span>\n<span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-active\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"display:flex;gap:16px;\"</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block skel-block--circle\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"width:40px;height:40px;flex-shrink:0;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"flex:1;\"</span><span class=\"c-tag\">&gt;</span>\n    <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:38%;margin-bottom:28px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n    <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:100%;margin-bottom:8px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n    <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:61%;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;/div&gt;</span>\n<span class=\"c-tag\">&lt;/div&gt;</span>\n\n<span class=\"c-cmt\">&lt;!-- Button skeleton --&gt;</span>\n<span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-active\"</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block skel-block--round\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"width:88px;height:32px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n<span class=\"c-tag\">&lt;/div&gt;</span></code></pre></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 6 \u00b7 States \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-states\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">6</span><div class=\"btn-family-title\" style=\"margin:0;\">States</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-states-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-states-r\"><code><span class=\"c-cmt\">// Static (default) \u2014 no animation</span>\n<span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// Active \u2014 shimmer wave</span>\n<span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">active</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// Conditional \u2014 loading prop gates between skeleton and children</span>\n<span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">loading</span>={isLoading}<span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;ArticleCard</span> <span class=\"c-attr\">data</span>={article} <span class=\"c-tag\">/&gt;</span>\n<span class=\"c-tag\">&lt;/Skeleton&gt;</span>\n\n<span class=\"c-cmt\">// 300ms show-delay (prevents flicker for fast connections)</span>\n<span class=\"c-kw\">const</span> [showSkel, setShowSkel] = <span class=\"c-type\">useState</span>(<span class=\"c-kw\">false</span>);\n<span class=\"c-type\">useEffect</span>(() =&gt; {\n  <span class=\"c-kw\">const</span> t = setTimeout(() =&gt; setShowSkel(isLoading), 300);\n  <span class=\"c-kw\">return</span> () =&gt; clearTimeout(t);\n}, [isLoading]);\n\n<span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">loading</span>={showSkel}<span class=\"c-tag\">&gt;</span>\n  {children}\n<span class=\"c-tag\">&lt;/Skeleton&gt;</span></code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">HTML</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-states-ng',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-states-ng\"><code><span class=\"c-cmt\">&lt;!-- Toggle active class via JS --&gt;</span>\n<span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">id</span>=<span class=\"c-val\">\"vessel-skeleton\"</span>\n     <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-active\"</span>\n     <span class=\"c-attr\">aria-busy</span>=<span class=\"c-val\">\"true\"</span>\n     <span class=\"c-attr\">aria-label</span>=<span class=\"c-val\">\"Loading vessel data\"</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-cmt\">&lt;!-- skeleton blocks --&gt;</span>\n<span class=\"c-tag\">&lt;/div&gt;</span>\n\n<span class=\"c-cmt\">&lt;!-- After data resolves: remove skeleton, add content --&gt;</span>\n<span class=\"c-cmt\">// In your component:</span>\n<span class=\"c-kw\">const</span> skel = document.getElementById(<span class=\"c-val\">'vessel-skeleton'</span>);\nskel.remove();\n<span class=\"c-kw\">const</span> region = document.getElementById(<span class=\"c-val\">'vessel-region'</span>);\nregion.setAttribute(<span class=\"c-val\">'aria-busy'</span>, <span class=\"c-val\">'false'</span>);\nregion.innerHTML = renderedContent;</code></pre></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 7 \u00b7 Accessibility \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-a11y\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">7</span><div class=\"btn-family-title\" style=\"margin:0;\">Accessibility</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-a11y-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-a11y-r\"><code><span class=\"c-cmt\">// Wrap the loading region in an aria-busy container</span>\n<span class=\"c-tag\">&lt;section</span>\n  <span class=\"c-attr\">aria-busy</span>={isLoading}\n  <span class=\"c-attr\">aria-label</span>=<span class=\"c-val\">\"Vessel inquiry list\"</span>\n<span class=\"c-tag\">&gt;</span>\n  <span class=\"c-cmt\">// Visually-hidden live region announces state changes</span>\n  <span class=\"c-tag\">&lt;span</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"sr-only\"</span> <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-live</span>=<span class=\"c-val\">\"polite\"</span><span class=\"c-tag\">&gt;</span>\n    {isLoading ? <span class=\"c-val\">'Loading vessel list'</span> : <span class=\"c-val\">'Vessel list loaded'</span>}\n  <span class=\"c-tag\">&lt;/span&gt;</span>\n\n  <span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">loading</span>={isLoading} <span class=\"c-attr\">avatar</span><span class=\"c-tag\">&gt;</span>\n    <span class=\"c-tag\">&lt;VesselList</span> <span class=\"c-attr\">data</span>={vessels} <span class=\"c-tag\">/&gt;</span>\n  <span class=\"c-tag\">&lt;/Skeleton&gt;</span>\n<span class=\"c-tag\">&lt;/section&gt;</span></code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">HTML</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-a11y-ng',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-a11y-ng\"><code><span class=\"c-tag\">&lt;section</span> <span class=\"c-attr\">aria-busy</span>=<span class=\"c-val\">\"true\"</span> <span class=\"c-attr\">aria-label</span>=<span class=\"c-val\">\"Vessel list\"</span><span class=\"c-tag\">&gt;</span>\n\n  <span class=\"c-cmt\">&lt;!-- Screen-reader live region --&gt;</span>\n  <span class=\"c-tag\">&lt;span</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"sr-only\"</span> <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-live</span>=<span class=\"c-val\">\"polite\"</span><span class=\"c-tag\">&gt;</span>Loading vessel list<span class=\"c-tag\">&lt;/span&gt;</span>\n\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-active\"</span> <span class=\"c-attr\">aria-hidden</span>=<span class=\"c-val\">\"true\"</span><span class=\"c-tag\">&gt;</span>\n    <span class=\"c-cmt\">&lt;!-- skeleton blocks --&gt;</span>\n  <span class=\"c-tag\">&lt;/div&gt;</span>\n\n<span class=\"c-tag\">&lt;/section&gt;</span></code></pre></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 8 \u00b7 File Structure \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-files\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">8</span><div class=\"btn-family-title\" style=\"margin:0;\">File Structure</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">tree</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-files-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-files-r\"><code>@pelagos/components/\n\u2514\u2500\u2500 loading/\n    \u2514\u2500\u2500 skeleton/\n        \u251c\u2500\u2500 index.tsx         <span class=\"c-cmt\">// re-exports Skeleton + sub-components</span>\n        \u251c\u2500\u2500 skeleton.css      <span class=\"c-cmt\">// token overrides (--skel-* vars)</span>\n        \u2514\u2500\u2500 skeleton.test.tsx <span class=\"c-cmt\">// unit + a11y tests</span></code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">tree</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-files-ng',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-files-ng\"><code>styles/\n\u2514\u2500\u2500 components/\n    \u2514\u2500\u2500 _skeleton.scss   <span class=\"c-cmt\">// .skel-block, .skel-active, shape + size modifiers</span>\n\n<span class=\"c-cmt\">// Import in styles.css:</span>\n@use <span class=\"c-val\">'styles/components/skeleton'</span>;</code></pre></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 9 \u00b7 Usage Patterns \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-patterns\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">9</span><div class=\"btn-family-title\" style=\"margin:0;\">Usage Patterns</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-patterns-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-patterns-r\"><code><span class=\"c-cmt\">// Pattern A \u2014 table row skeleton (always 3 rows)</span>\n{isLoading ? (\n  [1,2,3].map(i =&gt; (\n    <span class=\"c-tag\">&lt;tr</span> <span class=\"c-attr\">key</span>={i} <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"tbl-skeleton-row\"</span><span class=\"c-tag\">&gt;</span>\n      <span class=\"c-tag\">&lt;td&gt;&lt;div</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"tbl-skeleton-cell\"</span> <span class=\"c-attr\">style</span>={{width:<span class=\"c-val\">'46px'</span>}} <span class=\"c-tag\">/&gt;&lt;/td&gt;</span>\n      <span class=\"c-tag\">&lt;td&gt;&lt;div</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"tbl-skeleton-cell\"</span> <span class=\"c-attr\">style</span>={{width:<span class=\"c-val\">'110px'</span>}} <span class=\"c-tag\">/&gt;&lt;/td&gt;</span>\n      <span class=\"c-tag\">&lt;td&gt;&lt;div</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"tbl-skeleton-cell\"</span>\n              <span class=\"c-attr\">style</span>={{width:<span class=\"c-val\">'80px'</span>, borderRadius:<span class=\"c-val\">'20px'</span>}} <span class=\"c-tag\">/&gt;&lt;/td&gt;</span>\n    <span class=\"c-tag\">&lt;/tr&gt;</span>\n  ))\n) : rows.map(row =&gt; <span class=\"c-tag\">&lt;TableRow</span> <span class=\"c-attr\">key</span>={row.id} <span class=\"c-attr\">row</span>={row} <span class=\"c-tag\">/&gt;</span>)}\n\n<span class=\"c-cmt\">// Pattern B \u2014 card grid skeleton</span>\n{isLoading ? (\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"card-grid\"</span><span class=\"c-tag\">&gt;</span>\n    {[1,2,3].map(i =&gt; (\n      <span class=\"c-tag\">&lt;Skeleton</span> <span class=\"c-attr\">key</span>={i} <span class=\"c-attr\">active</span> <span class=\"c-attr\">avatar</span>={{ shape:<span class=\"c-val\">'square'</span>, size:<span class=\"c-val\">'large'</span> }}\n               <span class=\"c-attr\">paragraph</span>={{ rows: 2 }} <span class=\"c-tag\">/&gt;</span>\n    ))}\n  <span class=\"c-tag\">&lt;/div&gt;</span>\n) : <span class=\"c-tag\">&lt;CardGrid</span> <span class=\"c-attr\">items</span>={items} <span class=\"c-tag\">/&gt;</span>}\n\n<span class=\"c-cmt\">// Pattern C \u2014 form pre-fill skeleton</span>\n{isLoading ? (\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"form-grid\"</span><span class=\"c-tag\">&gt;</span>\n    {[1,2,3,4].map(i =&gt; (\n      <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">key</span>={i}<span class=\"c-tag\">&gt;</span>\n        <span class=\"c-tag\">&lt;Skeleton.Input</span> <span class=\"c-attr\">active</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"large\"</span> <span class=\"c-attr\">block</span> <span class=\"c-tag\">/&gt;</span>\n      <span class=\"c-tag\">&lt;/div&gt;</span>\n    ))}\n  <span class=\"c-tag\">&lt;/div&gt;</span>\n) : <span class=\"c-tag\">&lt;InquiryForm</span> <span class=\"c-attr\">data</span>={formData} <span class=\"c-tag\">/&gt;</span>}</code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <p class=\"btn-family-desc\">Follow the same three patterns in Angular \u2014 replace JSX with Angular structural directives (<code>*ngIf</code>) and map component references to <code>.skel-block</code> HTML equivalents. See the Variants section for the HTML patterns.</p>\n        </div>\n      </div>\n\n      <!-- 10 \u00b7 Theming \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-tokens\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">10</span><div class=\"btn-family-title\" style=\"margin:0;\">Theming / Tokens</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JS</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-tokens-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-tokens-r\"><code><span class=\"c-cmt\">// In ConfigProvider \u2014 override Ant Design Skeleton design tokens</span>\n<span class=\"c-tag\">&lt;ConfigProvider</span>\n  <span class=\"c-attr\">theme</span>={{\n    components: {\n      Skeleton: {\n        blockRadius:        4,            <span class=\"c-cmt\">// --skel-radius</span>\n        gradientFromColor:  <span class=\"c-val\">'#F1F5F9'</span>,   <span class=\"c-cmt\">// --prim-grey-50</span>\n        gradientToColor:    <span class=\"c-val\">'#E2E8F0'</span>,   <span class=\"c-cmt\">// --prim-grey-100</span>\n        paragraphLiHeight:  16,           <span class=\"c-cmt\">// --skel-para-lh</span>\n        paragraphMarginTop: 28,           <span class=\"c-cmt\">// --skel-para-mt</span>\n        titleHeight:        16,           <span class=\"c-cmt\">// --skel-title-h</span>\n      }\n    }\n  }}\n<span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;App</span> <span class=\"c-tag\">/&gt;</span>\n<span class=\"c-tag\">&lt;/ConfigProvider&gt;</span></code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">SCSS</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-tokens-ng',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-tokens-ng\"><code><span class=\"c-cmt\">// Override in :root or a component scope</span>\n:root {\n  --skel-from:    #F1F5F9;   <span class=\"c-cmt\">/* grey/50  \u2014 base */</span>\n  --skel-to:      #E2E8F0;   <span class=\"c-cmt\">/* grey/100 \u2014 highlight */</span>\n  --skel-radius:  4px;\n  --skel-title-h: 16px;\n  --skel-para-lh: 16px;\n  --skel-para-mt: 28px;\n}</code></pre></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- 11 \u00b7 Full Example \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 -->\n      <div id=\"skel-c-example\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">11</span><div class=\"btn-family-title\" style=\"margin:0;\">Full Example</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-example-r',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-example-r\"><code><span class=\"c-kw\">import</span> { useState, useEffect } <span class=\"c-kw\">from</span> <span class=\"c-val\">'react'</span>;\n<span class=\"c-kw\">import</span> { <span class=\"c-type\">Skeleton</span> } <span class=\"c-kw\">from</span> <span class=\"c-val\">'@pelagos/components/loading/skeleton'</span>;\n\n<span class=\"c-kw\">export function</span> <span class=\"c-type\">VesselCard</span>({ vesselId }) {\n  <span class=\"c-kw\">const</span> [vessel, setVessel] = useState(<span class=\"c-kw\">null</span>);\n  <span class=\"c-kw\">const</span> [loading, setLoading] = useState(<span class=\"c-kw\">true</span>);\n  <span class=\"c-kw\">const</span> [showSkel, setShowSkel] = useState(<span class=\"c-kw\">false</span>);\n\n  <span class=\"c-cmt\">// 300ms delay prevents flicker for fast connections</span>\n  <span class=\"c-type\">useEffect</span>(() =&gt; {\n    <span class=\"c-kw\">const</span> t = setTimeout(() =&gt; setShowSkel(loading), 300);\n    <span class=\"c-kw\">return</span> () =&gt; clearTimeout(t);\n  }, [loading]);\n\n  <span class=\"c-type\">useEffect</span>(() =&gt; {\n    fetchVessel(vesselId).then(data =&gt; {\n      setVessel(data);\n      setLoading(<span class=\"c-kw\">false</span>);\n      setShowSkel(<span class=\"c-kw\">false</span>);\n    });\n  }, [vesselId]);\n\n  <span class=\"c-kw\">return</span> (\n    <span class=\"c-tag\">&lt;section</span>\n      <span class=\"c-attr\">aria-busy</span>={showSkel}\n      <span class=\"c-attr\">aria-label</span>=<span class=\"c-val\">\"Vessel details\"</span>\n    <span class=\"c-tag\">&gt;</span>\n      <span class=\"c-tag\">&lt;span</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"sr-only\"</span> <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-live</span>=<span class=\"c-val\">\"polite\"</span><span class=\"c-tag\">&gt;</span>\n        {showSkel ? <span class=\"c-val\">'Loading vessel details'</span> : <span class=\"c-val\">'Vessel details loaded'</span>}\n      <span class=\"c-tag\">&lt;/span&gt;</span>\n\n      <span class=\"c-tag\">&lt;Skeleton</span>\n        <span class=\"c-attr\">active</span>\n        <span class=\"c-attr\">loading</span>={showSkel}\n        <span class=\"c-attr\">avatar</span>={{ shape: <span class=\"c-val\">'circle'</span>, size: <span class=\"c-val\">'large'</span> }}\n        <span class=\"c-attr\">paragraph</span>={{ rows: 3, width: [<span class=\"c-val\">'100%'</span>, <span class=\"c-val\">'85%'</span>, <span class=\"c-val\">'61%'</span>] }}\n      <span class=\"c-tag\">&gt;</span>\n        <span class=\"c-cmt\">/* real content \u2014 shown when loading=false */</span>\n        <span class=\"c-tag\">&lt;VesselDetail</span> <span class=\"c-attr\">vessel</span>={vessel} <span class=\"c-tag\">/&gt;</span>\n      <span class=\"c-tag\">&lt;/Skeleton&gt;</span>\n    <span class=\"c-tag\">&lt;/section&gt;</span>\n  );\n}</code></pre></div>\n          </div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\">\n            <div class=\"btn-code-head\"><span class=\"btn-code-lang\">HTML</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('skel-c-example-ng',this)\">Copy</button></div>\n            <div class=\"btn-code-body\"><pre id=\"skel-c-example-ng\"><code><span class=\"c-tag\">&lt;section</span> [<span class=\"c-attr\">attr.aria-busy</span>]=<span class=\"c-val\">\"isLoading\"</span> <span class=\"c-attr\">aria-label</span>=<span class=\"c-val\">\"Vessel details\"</span><span class=\"c-tag\">&gt;</span>\n\n  <span class=\"c-tag\">&lt;span</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"sr-only\"</span> <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-live</span>=<span class=\"c-val\">\"polite\"</span><span class=\"c-tag\">&gt;</span>\n    {{ isLoading ? 'Loading vessel details' : 'Vessel details loaded' }}\n  <span class=\"c-tag\">&lt;/span&gt;</span>\n\n  <span class=\"c-tag\">&lt;div</span> *<span class=\"c-attr\">ngIf</span>=<span class=\"c-val\">\"showSkeleton\"</span>\n       <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-active\"</span>\n       <span class=\"c-attr\">aria-hidden</span>=<span class=\"c-val\">\"true\"</span><span class=\"c-tag\">&gt;</span>\n    <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"display:flex;gap:16px;\"</span><span class=\"c-tag\">&gt;</span>\n      <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block skel-block--circle\"</span>\n           <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"width:40px;height:40px;flex-shrink:0;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n      <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"flex:1;display:flex;flex-direction:column;gap:8px;\"</span><span class=\"c-tag\">&gt;</span>\n        <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:38%;margin-bottom:28px;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n        <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:100%;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n        <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:85%;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n        <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"skel-block\"</span> <span class=\"c-attr\">style</span>=<span class=\"c-val\">\"height:16px;width:61%;\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n      <span class=\"c-tag\">&lt;/div&gt;</span>\n    <span class=\"c-tag\">&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;/div&gt;</span>\n\n  <span class=\"c-tag\">&lt;app-vessel-detail</span> *<span class=\"c-attr\">ngIf</span>=<span class=\"c-val\">\"!isLoading\"</span> [<span class=\"c-attr\">vessel</span>]=<span class=\"c-val\">\"vessel\"</span><span class=\"c-tag\">&gt;&lt;/app-vessel-detail&gt;</span>\n\n<span class=\"c-tag\">&lt;/section&gt;</span></code></pre></div>\n          </div>\n        </div>\n      </div>\n\n    </div><!-- /code-tab-main -->\n\n    <div class=\"code-tab-qnav\">\n      <div class=\"code-qnav-inner\">\n        <p class=\"code-qnav-title\">On This Page</p>\n        <ul class=\"code-qnav-list\">\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-overview')\">1 \u00b7 Overview</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-install')\">2 \u00b7 Install</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-imports')\">3 \u00b7 Import</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-api')\">4 \u00b7 API / Props</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-variants')\">5 \u00b7 Variants</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-states')\">6 \u00b7 States</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-a11y')\">7 \u00b7 Accessibility</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-files')\">8 \u00b7 File Structure</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-patterns')\">9 \u00b7 Usage Patterns</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-tokens')\">10 \u00b7 Theming</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-c-example')\">11 \u00b7 Full Example</button></li>\n        </ul>\n      </div>\n    </div>\n  </div><!-- /code-tab-layout -->\n</div><!-- /skel-tab-code -->\n\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n     USAGE TAB\n     \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div id=\"skel-tab-usage\" class=\"btn-tab-pane skel-tab-pane\">\n  <div class=\"code-tab-layout\">\n    <div class=\"code-tab-main\">\n\n      <!-- When to Use -->\n      <div id=\"skel-u-when\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">When to Use</div>\n        <ul class=\"btn-usage-list\">\n          <li><strong>First data load with a known layout</strong> \u2014 whenever the page structure is predictable (list of cards, table rows, form fields) and data is loading for the first time. The skeleton prevents layout shift by holding the exact space the content will occupy.</li>\n          <li><strong>Parallel data fetching</strong> \u2014 when multiple sections fetch independently, show a skeleton per section. Each resolves into content at its own pace without blocking other parts of the UI.</li>\n          <li><strong>Rich content areas</strong> \u2014 components that contain lots of information (Table, List, Card grid) benefit most from skeletons since they have a high surface area to fill.</li>\n          <li><strong>Content that doesn't exist yet</strong> \u2014 use Skeleton to visualise placeholder layouts in empty states or \"coming soon\" panels.</li>\n        </ul>\n      </div>\n\n      <!-- When Not to Use -->\n      <div id=\"skel-u-when-not\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">When Not to Use</div>\n        <ul class=\"btn-usage-list\">\n          <li>\n            <strong>Background mutations</strong> \u2014 use\n            <button onclick=\"navigate('loading-spinner')\" class=\"btn-inline-link\">Spinner</button>\n            inside buttons for save/approve/submit actions. A skeleton would imply full-section re-load which is misleading.\n          </li>\n          <li>\n            <strong>Unknown layout</strong> \u2014 if you can't predict the content shape (e.g. a rich-text article of variable length), use\n            <button onclick=\"navigate('loading-spinner')\" class=\"btn-inline-link\">Spinner</button>\n            instead. A badly-proportioned skeleton is worse than no skeleton.\n          </li>\n          <li>\n            <strong>Very fast loads (&lt;300ms)</strong> \u2014 showing a skeleton for 200ms then immediately replacing it with real content causes jarring visual flicker. Apply a 300ms delay before rendering the skeleton; if data arrives within that window, skip it entirely.\n          </li>\n          <li>\n            <strong>Deterministic progress</strong> \u2014 use\n            <button onclick=\"navigate('nav-progress')\" class=\"btn-inline-link\">Progress Bar</button>\n            when you can report a percentage (file upload, multi-step wizard).\n          </li>\n        </ul>\n      </div>\n\n      <!-- Best Practices -->\n      <div id=\"skel-u-best\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Best Practices</div>\n        <ul class=\"btn-usage-list\">\n          <li><strong>Mirror real content dimensions exactly</strong> \u2014 the skeleton and the actual content must occupy the same space to prevent layout jump on reveal. Check that avatar size, row heights, and column widths match 1:1.</li>\n          <li><strong>Vary paragraph row widths</strong> \u2014 use decreasing widths (100%, 94%, 61%) per Ant Design's default. Equal-width rows look mechanical; varying widths mimic natural prose.</li>\n          <li><strong>Always 3 rows for Table skeletons</strong> \u2014 consistent with the Table component specification. Never vary the count based on expected result set size.</li>\n          <li><strong>Apply a 300ms show-delay</strong> \u2014 render real content immediately; only show the skeleton if data hasn't resolved after 300ms. This eliminates flicker for fast connections without removing the feedback for slow ones.</li>\n          <li><strong>Provide a 10s timeout fallback</strong> \u2014 if data hasn't arrived after 10 seconds, replace the skeleton with an error empty state that includes a retry action.</li>\n          <li><strong>Set <code>aria-busy</code> on the region</strong> \u2014 not on the skeleton blocks themselves. The skeleton blocks should be <code>aria-hidden=\"true\"</code>.</li>\n        </ul>\n      </div>\n\n      <!-- Patterns -->\n      <div id=\"skel-u-patterns\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Patterns</div>\n        <ul class=\"btn-usage-list\">\n          <li><strong>Table row pattern</strong> \u2014 use <code>.tbl-skeleton-row</code> and <code>.tbl-skeleton-cell</code> (pre-configured in the Table component). Always show 3 rows. Badge cells get <code>border-radius: 20px</code>, chip cells get <code>border-radius: 6px</code>.</li>\n          <li><strong>Card grid pattern</strong> \u2014 render N skeleton cards (matching your actual grid column count) each with an avatar-shaped image placeholder and 2\u20133 paragraph lines. Use <code>Skeleton.Avatar</code> with <code>shape=\"square\"</code> for rectangular image thumbnails.</li>\n          <li><strong>Form pre-fill pattern</strong> \u2014 show label-height (10px) skeleton lines above full-width input-height (40px) blocks for each field. Match the exact grid layout of the form so no reflow occurs on load.</li>\n          <li><strong>Detail page pattern</strong> \u2014 for a detail/header section: large avatar circle + title skeleton at 38% width + 3-line paragraph. Below the fold, use smaller skeletons for KPI tiles and secondary sections.</li>\n        </ul>\n      </div>\n\n      <!-- Anti-patterns -->\n      <div id=\"skel-u-mistakes\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Anti-patterns</div>\n        <ul class=\"btn-usage-list\">\n          <li>\n            <strong>\u274c Equal-width paragraph rows</strong> \u2014 all rows at 100% looks like a bar chart, not text.<br>\n            <strong>\u2705 Fix:</strong> use <code>['100%', '92%', '61%']</code> (or the Ant Design default <code>paragraph.width</code>).\n          </li>\n          <li>\n            <strong>\u274c Skeleton + Spinner in the same region simultaneously</strong> \u2014 creates competing loading signals.<br>\n            <strong>\u2705 Fix:</strong> choose one per region. Skeleton for layout-preserving loads; Spinner for overlay/button states.\n          </li>\n          <li>\n            <strong>\u274c Skeleton that never resolves</strong> \u2014 if data fails silently, users stare at a permanently loading UI.<br>\n            <strong>\u2705 Fix:</strong> implement a 10s timeout that replaces the skeleton with an error empty state and retry button.\n          </li>\n          <li>\n            <strong>\u274c Too many skeleton rows</strong> \u2014 showing 20 skeleton rows for a table implies a huge result set even when it may be empty.<br>\n            <strong>\u2705 Fix:</strong> always show exactly 3 rows \u2014 this is a convention, not a preview of expected row count.\n          </li>\n          <li>\n            <strong>\u274c Skeleton without <code>aria-busy</code></strong> \u2014 screen reader users get no feedback that the page is loading.<br>\n            <strong>\u2705 Fix:</strong> always set <code>aria-busy=\"true\"</code> on the content region and use a live region to announce completion.\n          </li>\n        </ul>\n      </div>\n\n      <!-- References -->\n      <div id=\"skel-u-refs\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">References</div>\n        <ul class=\"btn-related-list\">\n          <li><a href=\"https://ant.design/components/skeleton\" target=\"_blank\" rel=\"noopener\">Ant Design \u2014 Skeleton component specification</a></li>\n          <li><a href=\"https://www.figma.com/design/TOLfBpRePgynqwvDVp6fg3/Design-System\" target=\"_blank\" rel=\"noopener\">Figma \u2014 Pelagos Design System</a></li>\n          <li><a href=\"https://www.nngroup.com/articles/skeleton-screens/\" target=\"_blank\" rel=\"noopener\">Nielsen Norman Group \u2014 Skeleton Screens</a></li>\n          <li><a href=\"https://www.w3.org/WAI/ARIA/apg/patterns/\" target=\"_blank\" rel=\"noopener\">ARIA Authoring Practices \u2014 Loading patterns</a></li>\n          <li><a href=\"https://www.w3.org/WAI/WCAG21/Understanding/pause-stop-hide.html\" target=\"_blank\" rel=\"noopener\">WCAG 2.1 \u2014 2.2.2 Pause, Stop, Hide (animations)</a></li>\n        </ul>\n      </div>\n\n    </div><!-- /code-tab-main -->\n\n    <div class=\"code-tab-qnav\">\n      <div class=\"code-qnav-inner\">\n        <p class=\"code-qnav-title\">Quick Access</p>\n        <ul class=\"code-qnav-list\">\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-u-when')\">When to Use</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-u-when-not')\">When Not to Use</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-u-best')\">Best Practices</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-u-patterns')\">Patterns</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-u-mistakes')\">Anti-patterns</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('skel-u-refs')\">References</button></li>\n        </ul>\n      </div>\n    </div>\n  </div><!-- /code-tab-layout -->\n</div><!-- /skel-tab-usage -->\n";

  window.PAGES_BUNDLE["loading-spinner"] = "<style>\n/* ── Spinner component tokens ─────────────────────────────────────────── */\n:root {\n  --sp-brand:  #1852FE;\n  --sp-white:  #FFFFFF;\n  --sp-muted:  #94A3B8;\n  --sp-navy:   #001E4C;\n}\n\n/*\n * ── Spinner architecture ────────────────────────────────────────────────\n *  Two CSS layers via pseudo-elements — zero extra DOM required:\n *\n *  ::before  →  TRACK  — static full-circle ring at low opacity (does NOT rotate)\n *  ::after   →  ARC    — ~270° handle that spins (only this element rotates)\n *\n *  By keeping the track on a separate, non-animated layer, the background\n *  ring remains perfectly still while only the bright arc sweeps around it.\n * ─────────────────────────────────────────────────────────────────────── */\n\n/* ── Base container ────────────────────────────────────────────────────── */\n.gs-spinner {\n  display: inline-block;\n  position: relative;        /* stacking context for ::before / ::after     */\n  border-radius: 50%;\n  flex-shrink: 0;\n  /* No border or animation on the container itself                         */\n}\n\n/* ── Track (::before) — STATIC ─────────────────────────────────────────── */\n.gs-spinner::before {\n  content: '';\n  position: absolute;\n  inset: 0;\n  border-radius: 50%;\n  border-style: solid;\n  pointer-events: none;\n  /* border-width set per size; border-color set per variant                */\n}\n\n/* ── Arc (::after) — ROTATES ──────────────────────────────────────────── */\n/* ~270° arc: top + right at full opacity, bottom faded, left transparent  */\n.gs-spinner::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  border-radius: 50%;\n  border-style: solid;\n  border-color: transparent;          /* overridden per colour variant       */\n  pointer-events: none;\n  animation: gs-spin 0.72s linear infinite;\n}\n\n@keyframes gs-spin { to { transform: rotate(360deg); } }\n\n/* ── Size variants ─────────────────────────────────────────────────────── */\n.gs-spinner--sm  { width: 16px; height: 16px; }\n.gs-spinner--sm::before,\n.gs-spinner--sm::after  { border-width: 2px; }\n\n.gs-spinner--md  { width: 24px; height: 24px; }\n.gs-spinner--md::before,\n.gs-spinner--md::after  { border-width: 2.5px; }\n\n.gs-spinner--lg  { width: 40px; height: 40px; }\n.gs-spinner--lg::before,\n.gs-spinner--lg::after  { border-width: 3px; }\n\n.gs-spinner--xl  { width: 56px; height: 56px; }\n.gs-spinner--xl::before,\n.gs-spinner--xl::after  { border-width: 4px; }\n\n/* ── Colour variants ───────────────────────────────────────────────────── */\n/*  ::before → full-circle GREY track (Figma spec — #E2E8F0, never blue)   */\n/*  ::after  → solid arc ~270°: top+right+bottom=brand, left=transparent   */\n\n/* Brand — grey track, solid blue arc */\n.gs-spinner--brand::before {\n  border-color: #E2E8F0;    /* --prim-grey-100: the standard border grey     */\n}\n.gs-spinner--brand::after {\n  border-top-color:    var(--sp-brand);   /* solid blue — no fade            */\n  border-right-color:  var(--sp-brand);\n  border-bottom-color: var(--sp-brand);\n  /* border-left-color: transparent — 90° gap creates rotation cue          */\n}\n\n/* Muted — lighter grey track, solid muted arc */\n.gs-spinner--muted::before {\n  border-color: #F1F5F9;    /* --prim-grey-50: subtle track                  */\n}\n.gs-spinner--muted::after {\n  border-top-color:    var(--sp-muted);\n  border-right-color:  var(--sp-muted);\n  border-bottom-color: var(--sp-muted);\n}\n\n/* White — semi-white track for dark surfaces */\n.gs-spinner--white::before {\n  border-color: rgba(255, 255, 255, 0.25);\n}\n.gs-spinner--white::after {\n  border-top-color:    var(--sp-white);\n  border-right-color:  var(--sp-white);\n  border-bottom-color: var(--sp-white);\n}\n\n/* ── Reduced motion ─────────────────────────────────────────────────────── */\n@media (prefers-reduced-motion: reduce) {\n  .gs-spinner::after {\n    animation-duration: 2s;\n    animation-timing-function: steps(8, end);\n  }\n}\n\n/* ── Inline wrapper (spinner + label) ──────────────────────────────────── */\n.gs-spinner-row {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--color-text-secondary, #64748B);\n}\n\n/* ── Full-page overlay ─────────────────────────────────────────────────── */\n.gs-spinner-overlay {\n  position: absolute; inset: 0;\n  display: flex; align-items: center; justify-content: center;\n  background: rgba(255,255,255,.72);\n  backdrop-filter: blur(2px);\n  border-radius: inherit;\n  z-index: 10;\n}\n\n/* ── Demo helpers ──────────────────────────────────────────────────────── */\n.sp-demo-cell {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n}\n.sp-demo-label {\n  font-size: 11px;\n  color: #9CA3AF;\n  font-weight: 500;\n  text-align: center;\n}\n.sp-dark-bg {\n  background: var(--sp-navy);\n  border-radius: 10px;\n  padding: 20px 28px;\n  display: flex; align-items: center; justify-content: center; gap: 10px;\n}\n</style>\n\n<!-- BANNER -->\n<div class=\"page-header\">\n  <h1 class=\"ds-hero-title\">Spinner</h1>\n</div>\n\n<!-- TAB BAR -->\n<div class=\"btn-tab-bar\">\n  <button class=\"btn-tab-btn spinner-tab-btn active\" data-tab=\"design\" onclick=\"switchSpinnerTab('design')\">Design</button>\n  <button class=\"btn-tab-btn spinner-tab-btn\" data-tab=\"code\"   onclick=\"switchSpinnerTab('code')\">Code</button>\n  <button class=\"btn-tab-btn spinner-tab-btn\" data-tab=\"usage\"  onclick=\"switchSpinnerTab('usage')\">Usage</button>\n</div>\n\n<!-- ═══ DESIGN TAB ═══════════════════════════════════════════════ -->\n<div id=\"spinner-tab-design\" class=\"btn-tab-pane spinner-tab-pane active\">\n  <div class=\"code-tab-layout\">\n    <div class=\"code-tab-main\">\n\n      <!-- OVERVIEW -->\n      <div id=\"sp-s-overview\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Overview</div>\n        <p class=\"btn-family-desc\">The Spinner is a circular indeterminate progress indicator. Use it whenever a system action is in progress and the duration is unknown — data loading, form submission, route transitions. It is always animated and never used as a static icon.</p>\n\n        <div style=\"margin-top:20px;display:flex;flex-wrap:wrap;align-items:center;gap:32px;\">\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner gs-spinner--md gs-spinner--brand\"></div>\n            <span class=\"sp-demo-label\">Brand (default)</span>\n          </div>\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner gs-spinner--md gs-spinner--muted\"></div>\n            <span class=\"sp-demo-label\">Muted</span>\n          </div>\n          <div class=\"sp-demo-cell\">\n            <div class=\"sp-dark-bg\">\n              <div class=\"gs-spinner gs-spinner--md gs-spinner--white\"></div>\n            </div>\n            <span class=\"sp-demo-label\">White (dark bg)</span>\n          </div>\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner-row\">\n              <div class=\"gs-spinner gs-spinner--sm gs-spinner--brand\"></div>\n              Loading records…\n            </div>\n            <span class=\"sp-demo-label\">Inline + label</span>\n          </div>\n        </div>\n\n        <div class=\"btn-when-examples\" style=\"margin-top:16px;\">\n          <span class=\"btn-when-example-tag\">Indeterminate</span>\n          <span class=\"btn-when-example-tag\">4 sizes</span>\n          <span class=\"btn-when-example-tag\">3 colour variants</span>\n          <span class=\"btn-when-example-tag\">Inline or overlay</span>\n          <span class=\"btn-when-example-tag\">0.72s linear</span>\n        </div>\n      </div>\n\n      <!-- SIZE VARIANTS -->\n      <div id=\"sp-s-sizes\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Size Variants</div>\n        <p class=\"btn-family-desc\">Four sizes keyed to context — <strong>sm</strong> for inline hints and button states, <strong>md</strong> for cards and panels, <strong>lg</strong> for section-level loading, <strong>xl</strong> for full-page overlays.</p>\n\n        <div style=\"margin-top:20px;display:flex;flex-wrap:wrap;align-items:flex-end;gap:32px;\">\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner gs-spinner--sm gs-spinner--brand\"></div>\n            <span class=\"sp-demo-label\"><strong>sm</strong><br>16 × 16px<br>border 2px</span>\n          </div>\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner gs-spinner--md gs-spinner--brand\"></div>\n            <span class=\"sp-demo-label\"><strong>md</strong> (default)<br>24 × 24px<br>border 2.5px</span>\n          </div>\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner gs-spinner--lg gs-spinner--brand\"></div>\n            <span class=\"sp-demo-label\"><strong>lg</strong><br>40 × 40px<br>border 3px</span>\n          </div>\n          <div class=\"sp-demo-cell\">\n            <div class=\"gs-spinner gs-spinner--xl gs-spinner--brand\"></div>\n            <span class=\"sp-demo-label\"><strong>xl</strong><br>56 × 56px<br>border 4px</span>\n          </div>\n        </div>\n\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:8px;\">Size token reference</div>\n        <table>\n          <thead><tr><th>Modifier</th><th>Size</th><th>Border</th><th>Typical use</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner--sm</td><td>16 × 16px</td><td>2px</td><td>Button loading state, inline form hint</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner--md</td><td>24 × 24px</td><td>2.5px</td><td>Card, panel, table fetch (default)</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner--lg</td><td>40 × 40px</td><td>3px</td><td>Section or drawer loading</td></tr>\n            <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner--xl</td><td>56 × 56px</td><td>4px</td><td>Full-page / modal overlay</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <!-- COLOUR VARIANTS -->\n      <div id=\"sp-s-colours\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Colour Variants</div>\n        <p class=\"btn-family-desc\">Three colour options. The <strong>track</strong> (<code>::before</code>, static) is always <strong>grey</strong> — <code>#E2E8F0</code> for brand/muted, semi-white for dark surfaces. The <strong>arc</strong> (<code>::after</code>) is a solid 270° sweep at full opacity — no fade, matching the Figma spec.</p>\n\n        <div style=\"margin-top:16px;display:flex;flex-wrap:wrap;gap:24px;align-items:stretch;\">\n          <!-- Brand -->\n          <div style=\"flex:1;min-width:180px;border:1px solid #E2E8F0;border-radius:10px;overflow:hidden;\">\n            <div style=\"padding:28px;display:flex;align-items:center;justify-content:center;background:#F7FAFC;\">\n              <div class=\"gs-spinner gs-spinner--lg gs-spinner--brand\"></div>\n            </div>\n            <div style=\"padding:12px 14px;border-top:1px solid #E2E8F0;\">\n              <div style=\"font-size:12.5px;font-weight:600;color:#0F1B35;\">Brand</div>\n              <div style=\"font-size:11.5px;color:#9CA3AF;margin-top:2px;\"><code>.gs-spinner--brand</code></div>\n              <div style=\"font-size:11.5px;color:#64748B;margin-top:4px;\">Default. Use on white or light-grey surfaces.</div>\n            </div>\n          </div>\n          <!-- Muted -->\n          <div style=\"flex:1;min-width:180px;border:1px solid #E2E8F0;border-radius:10px;overflow:hidden;\">\n            <div style=\"padding:28px;display:flex;align-items:center;justify-content:center;background:#F7FAFC;\">\n              <div class=\"gs-spinner gs-spinner--lg gs-spinner--muted\"></div>\n            </div>\n            <div style=\"padding:12px 14px;border-top:1px solid #E2E8F0;\">\n              <div style=\"font-size:12.5px;font-weight:600;color:#0F1B35;\">Muted</div>\n              <div style=\"font-size:11.5px;color:#9CA3AF;margin-top:2px;\"><code>.gs-spinner--muted</code></div>\n              <div style=\"font-size:11.5px;color:#64748B;margin-top:4px;\">Deemphasised loading; secondary panels.</div>\n            </div>\n          </div>\n          <!-- White -->\n          <div style=\"flex:1;min-width:180px;border:1px solid #E2E8F0;border-radius:10px;overflow:hidden;\">\n            <div style=\"padding:28px;display:flex;align-items:center;justify-content:center;background:#001E4C;\">\n              <div class=\"gs-spinner gs-spinner--lg gs-spinner--white\"></div>\n            </div>\n            <div style=\"padding:12px 14px;border-top:1px solid #E2E8F0;\">\n              <div style=\"font-size:12.5px;font-weight:600;color:#0F1B35;\">White</div>\n              <div style=\"font-size:11.5px;color:#9CA3AF;margin-top:2px;\"><code>.gs-spinner--white</code></div>\n              <div style=\"font-size:11.5px;color:#64748B;margin-top:4px;\">Use on navy, blue, or any dark surface.</div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- USAGE CONTEXTS -->\n      <div id=\"sp-s-contexts\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Usage Contexts</div>\n        <p class=\"btn-family-desc\">The spinner adapts to three common loading patterns in GeoServe UI — inline (with text), overlaid over a card, and inside a button during async actions.</p>\n\n        <!-- Inline -->\n        <div class=\"btn-sub-label\" style=\"margin-top:16px;margin-bottom:10px;\">Inline + label</div>\n        <div style=\"background:#F7FAFC;border:1px solid #E2E8F0;border-radius:10px;padding:20px 24px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;\">\n          <div class=\"gs-spinner-row\">\n            <div class=\"gs-spinner gs-spinner--sm gs-spinner--brand\"></div>\n            Loading records…\n          </div>\n          <div class=\"gs-spinner-row\">\n            <div class=\"gs-spinner gs-spinner--sm gs-spinner--muted\"></div>\n            Syncing with IMOS…\n          </div>\n          <div style=\"background:#001E4C;border-radius:8px;padding:10px 16px;\">\n            <div class=\"gs-spinner-row\" style=\"color:#fff;\">\n              <div class=\"gs-spinner gs-spinner--sm gs-spinner--white\"></div>\n              Saving changes…\n            </div>\n          </div>\n        </div>\n\n        <!-- Card overlay -->\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:10px;\">Card / panel overlay</div>\n        <div style=\"position:relative;background:#fff;border:1px solid #E2E8F0;border-radius:12px;padding:24px;min-height:120px;overflow:hidden;\">\n          <div style=\"opacity:.3;\">\n            <div style=\"height:14px;background:#E2E8F0;border-radius:4px;width:40%;margin-bottom:10px;\"></div>\n            <div style=\"height:10px;background:#E2E8F0;border-radius:4px;width:70%;margin-bottom:8px;\"></div>\n            <div style=\"height:10px;background:#E2E8F0;border-radius:4px;width:55%;\"></div>\n          </div>\n          <div class=\"gs-spinner-overlay\">\n            <div style=\"display:flex;flex-direction:column;align-items:center;gap:10px;\">\n              <div class=\"gs-spinner gs-spinner--lg gs-spinner--brand\"></div>\n              <span style=\"font-size:12.5px;font-weight:500;color:#64748B;\">Loading data…</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Button loading state -->\n        <div class=\"btn-sub-label\" style=\"margin-top:20px;margin-bottom:10px;\">Button loading state</div>\n        <p class=\"btn-family-desc\" style=\"margin-bottom:14px;\">Add <code>.gs-btn--loading</code> to any button. The spinner colour is automatically matched to the button family — no extra modifier needed. See <button class=\"btn-inline-link\" onclick=\"navigate('prim-buttons')\">Button → Loading State</button> for the full spec.</p>\n\n        <div style=\"background:#F7FAFC;border:1px solid #E2E8F0;border-radius:10px;padding:20px 24px;\">\n          <!-- Primary -->\n          <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:14px;\">\n            <span style=\"width:110px;font-size:11px;color:#9CA3AF;font-weight:600;flex-shrink:0;\">Primary</span>\n            <div style=\"pointer-events:none;display:flex;gap:10px;flex-wrap:wrap;align-items:center;\">\n              <button class=\"gs-btn gs-btn-primary gs-btn-sm gs-btn--loading\" disabled>Saving…</button>\n              <button class=\"gs-btn gs-btn-primary gs-btn-md gs-btn--loading\" disabled>Saving…</button>\n              <button class=\"gs-btn gs-btn-primary gs-btn-lg gs-btn--loading\" disabled>Saving…</button>\n            </div>\n          </div>\n          <!-- Secondary -->\n          <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:14px;\">\n            <span style=\"width:110px;font-size:11px;color:#9CA3AF;font-weight:600;flex-shrink:0;\">Secondary</span>\n            <div style=\"pointer-events:none;display:flex;gap:10px;flex-wrap:wrap;align-items:center;\">\n              <button class=\"gs-btn gs-btn-secondary gs-btn-sm gs-btn--loading\" disabled>Loading…</button>\n              <button class=\"gs-btn gs-btn-secondary gs-btn-md gs-btn--loading\" disabled>Loading…</button>\n              <button class=\"gs-btn gs-btn-secondary gs-btn-lg gs-btn--loading\" disabled>Loading…</button>\n            </div>\n          </div>\n          <!-- Danger -->\n          <div style=\"display:flex;align-items:center;gap:8px;\">\n            <span style=\"width:110px;font-size:11px;color:#9CA3AF;font-weight:600;flex-shrink:0;\">Danger</span>\n            <div style=\"pointer-events:none;display:flex;gap:10px;flex-wrap:wrap;align-items:center;\">\n              <button class=\"gs-btn gs-btn-danger-primary gs-btn-sm gs-btn--loading\" disabled>Deleting…</button>\n              <button class=\"gs-btn gs-btn-danger-primary gs-btn-md gs-btn--loading\" disabled>Deleting…</button>\n              <button class=\"gs-btn gs-btn-danger-primary gs-btn-lg gs-btn--loading\" disabled>Deleting…</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- MOTION SPEC -->\n      <div id=\"sp-s-motion\" class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Motion Spec</div>\n        <p class=\"btn-family-desc\">Two-layer CSS animation: the <strong>track</strong> (<code>::before</code>) is always static. Only the <strong>arc</strong> (<code>::after</code>) rotates at constant speed — no easing — signalling ongoing work with no definite end point.</p>\n        <table style=\"margin-top:14px;\">\n          <thead><tr><th>Property</th><th>Value</th><th>Rationale</th></tr></thead>\n          <tbody>\n            <tr class=\"ds-tr-border\"><td>Track layer</td><td><code>::before</code> — no animation</td><td>Full-circle static ring; serves as the path indicator</td></tr>\n            <tr class=\"ds-tr-border\"><td>Arc layer</td><td><code>::after</code> — rotates</td><td>Only the handle moves; track stays fixed</td></tr>\n            <tr class=\"ds-tr-border\"><td>Duration</td><td><code>0.72s</code></td><td>Fast enough to feel responsive; slow enough to read the arc</td></tr>\n            <tr class=\"ds-tr-border\"><td>Easing</td><td><code>linear</code></td><td>Uniform rotation — no perceived start/stop</td></tr>\n            <tr class=\"ds-tr-border\"><td>Iteration</td><td><code>infinite</code></td><td>Runs until the loading state is cleared</td></tr>\n            <tr class=\"ds-tr-border\"><td>Arc coverage</td><td>~270° solid (top + right + bottom borders)</td><td>90° gap gives clear rotation cue; arc is solid per Figma spec — no fade</td></tr>\n            <tr class=\"ds-tr-border\"><td>Reduced motion</td><td>Slow to 2s, stepped (8 frames)</td><td>Respects <code>prefers-reduced-motion</code> without removing feedback</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n    </div><!-- /code-tab-main -->\n    <div class=\"code-tab-qnav\">\n      <div class=\"code-qnav-inner\">\n        <p class=\"code-qnav-title\">On This Page</p>\n        <ul class=\"code-qnav-list\">\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-s-overview')\">Overview</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-s-sizes')\">Size Variants</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-s-colours')\">Colour Variants</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-s-contexts')\">Usage Contexts</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-s-motion')\">Motion Spec</button></li>\n        </ul>\n      </div>\n    </div>\n  </div><!-- /code-tab-layout -->\n</div><!-- /spinner-tab-design -->\n\n<!-- ═══ CODE TAB ═══════════════════════════════════════════════ -->\n<div id=\"spinner-tab-code\" class=\"btn-tab-pane spinner-tab-pane\">\n\n  <!-- Framework toggle -->\n  <div class=\"fw-toggle-bar\">\n    <button class=\"fw-toggle-bar-btn active\" data-fw=\"react\" onclick=\"switchFw('spinner-tab-code','react')\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"12\" r=\"2.05\" fill=\"#61DAFB\"/><ellipse cx=\"12\" cy=\"12\" rx=\"10\" ry=\"3.8\" stroke=\"#61DAFB\" stroke-width=\"1.3\" fill=\"none\"/><ellipse cx=\"12\" cy=\"12\" rx=\"10\" ry=\"3.8\" stroke=\"#61DAFB\" stroke-width=\"1.3\" fill=\"none\" transform=\"rotate(60 12 12)\"/><ellipse cx=\"12\" cy=\"12\" rx=\"10\" ry=\"3.8\" stroke=\"#61DAFB\" stroke-width=\"1.3\" fill=\"none\" transform=\"rotate(120 12 12)\"/></svg>\n      React\n    </button>\n    <button class=\"fw-toggle-bar-btn\" data-fw=\"angular\" onclick=\"switchFw('spinner-tab-code','angular')\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\"><polygon points=\"12,2 22,5.5 20,18 12,22 4,18 2,5.5\" fill=\"#DD0031\"/><polygon points=\"12,2 12,22 4,18 2,5.5\" fill=\"#C3002F\"/><polygon points=\"12,5.5 8,15.5 9.5,15.5 10.5,13 13.5,13 14.5,15.5 16,15.5 12,5.5\" fill=\"white\"/></svg>\n      Angular\n    </button>\n  </div>\n\n  <div class=\"code-tab-layout\">\n    <div class=\"code-tab-main\">\n\n      <!-- 1 Overview -->\n      <div id=\"sp-c-overview\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">1</span><div class=\"btn-family-title\" style=\"margin:0;\">Overview</div></div>\n        <div class=\"fw-react\"><p class=\"btn-family-desc\">Import <code>Spinner</code> from the GeoServe component library. Combine <code>size</code> and <code>variant</code> props to cover all use cases. No extra dependencies needed — the animation is pure CSS.</p></div>\n        <div class=\"fw-angular\" style=\"display:none;\"><p class=\"btn-family-desc\">Add the <code>gs-spinner</code> CSS classes directly to any element or use the <code>SpinnerComponent</code> for Angular template integration. The CSS lives in <code>styles.css</code>.</p></div>\n      </div>\n\n      <!-- 2 Import -->\n      <div id=\"sp-c-import\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">2</span><div class=\"btn-family-title\" style=\"margin:0;\">Import</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\"><div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sp-imp-r',this)\">Copy</button></div>\n          <div class=\"btn-code-body\"><pre id=\"sp-imp-r\"><code><span class=\"c-kw\">import</span> { <span class=\"c-type\">Spinner</span> } <span class=\"c-kw\">from</span> <span class=\"c-val\">'@pelagos/components/loading/spinner'</span>;</code></pre></div></div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <p class=\"btn-family-desc\">Include <code>styles.css</code> — <code>.gs-spinner</code>, <code>.gs-spinner--{size}</code>, and <code>.gs-spinner--{variant}</code> are globally available.</p>\n        </div>\n      </div>\n\n      <!-- 3 API -->\n      <div id=\"sp-c-api\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">3</span><div class=\"btn-family-title\" style=\"margin:0;\">API / Props</div></div>\n        <div class=\"fw-react\">\n          <table>\n            <thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">size</td><td class=\"ds-td-code-muted\">'sm' | 'md' | 'lg' | 'xl'</td><td class=\"ds-td-code-muted\">'md'</td><td>Spinner diameter</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">variant</td><td class=\"ds-td-code-muted\">'brand' | 'white' | 'muted'</td><td class=\"ds-td-code-muted\">'brand'</td><td>Colour theme</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">label</td><td class=\"ds-td-code-muted\">string</td><td class=\"ds-td-code-muted\">—</td><td>Accessible text (used as aria-label and optional visible label)</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">showLabel</td><td class=\"ds-td-code-muted\">boolean</td><td class=\"ds-td-code-muted\">false</td><td>Render label text next to spinner</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">className</td><td class=\"ds-td-code-muted\">string</td><td class=\"ds-td-code-muted\">—</td><td>Extra class names on the root element</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <table>\n            <thead><tr><th>CSS Class</th><th>Description</th></tr></thead>\n            <tbody>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner</td><td>Base class — always required</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner--sm / --md / --lg / --xl</td><td>Size modifier</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner--brand / --white / --muted</td><td>Colour modifier</td></tr>\n              <tr class=\"ds-tr-border\"><td class=\"ds-td-code-primary\">gs-spinner-row</td><td>Flex wrapper for spinner + inline label text</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- 4 Basic usage -->\n      <div id=\"sp-c-basic\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">4</span><div class=\"btn-family-title\" style=\"margin:0;\">Basic Usage</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\"><div class=\"btn-code-head\"><span class=\"btn-code-lang\">JSX</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sp-basic-r',this)\">Copy</button></div>\n          <div class=\"btn-code-body\"><pre id=\"sp-basic-r\"><code><span class=\"c-cmt\">// Default (md, brand)</span>\n<span class=\"c-tag\">&lt;Spinner</span> <span class=\"c-attr\">label</span>=<span class=\"c-val\">\"Loading\"</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// Large + white (for dark backgrounds)</span>\n<span class=\"c-tag\">&lt;Spinner</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"lg\"</span> <span class=\"c-attr\">variant</span>=<span class=\"c-val\">\"white\"</span> <span class=\"c-attr\">label</span>=<span class=\"c-val\">\"Loading\"</span> <span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// Inline with visible label</span>\n<span class=\"c-tag\">&lt;Spinner</span>\n  <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"sm\"</span>\n  <span class=\"c-attr\">label</span>=<span class=\"c-val\">\"Saving changes…\"</span>\n  <span class=\"c-attr\">showLabel</span>\n<span class=\"c-tag\">/&gt;</span>\n\n<span class=\"c-cmt\">// Button loading state — preferred: use .gs-btn--loading class (no extra DOM)</span>\n<span class=\"c-tag\">&lt;button</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"gs-btn gs-btn-primary gs-btn-md gs-btn--loading\"</span> <span class=\"c-attr\">disabled</span><span class=\"c-tag\">&gt;</span>\n  Saving…\n<span class=\"c-tag\">&lt;/button&gt;</span>\n\n<span class=\"c-cmt\">// Alternative: explicit Spinner component inside button</span>\n<span class=\"c-tag\">&lt;button</span> <span class=\"c-attr\">className</span>=<span class=\"c-val\">\"gs-btn gs-btn-primary gs-btn-md\"</span> <span class=\"c-attr\">disabled</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;Spinner</span> <span class=\"c-attr\">size</span>=<span class=\"c-val\">\"sm\"</span> <span class=\"c-attr\">variant</span>=<span class=\"c-val\">\"white\"</span> <span class=\"c-attr\">label</span>=<span class=\"c-val\">\"Saving\"</span> <span class=\"c-tag\">/&gt;</span>\n  Saving…\n<span class=\"c-tag\">&lt;/button&gt;</span></code></pre></div></div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\"><div class=\"btn-code-head\"><span class=\"btn-code-lang\">HTML</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sp-basic-ng',this)\">Copy</button></div>\n          <div class=\"btn-code-body\"><pre id=\"sp-basic-ng\"><code><span class=\"c-cmt\">&lt;!-- Default (md, brand) --&gt;</span>\n<span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"gs-spinner gs-spinner--md gs-spinner--brand\"</span>\n     <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span>\n     <span class=\"c-attr\">aria-label</span>=<span class=\"c-val\">\"Loading\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n\n<span class=\"c-cmt\">&lt;!-- Inline with label text --&gt;</span>\n<span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"gs-spinner-row\"</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"gs-spinner gs-spinner--sm gs-spinner--brand\"</span>\n       <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-hidden</span>=<span class=\"c-val\">\"true\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  <span class=\"c-tag\">&lt;span&gt;</span>Loading records…<span class=\"c-tag\">&lt;/span&gt;</span>\n<span class=\"c-tag\">&lt;/div&gt;</span>\n\n<span class=\"c-cmt\">&lt;!-- Button loading state --&gt;</span>\n<span class=\"c-tag\">&lt;button</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"gs-btn gs-btn-primary\"</span> <span class=\"c-attr\">disabled</span><span class=\"c-tag\">&gt;</span>\n  <span class=\"c-tag\">&lt;div</span> <span class=\"c-attr\">class</span>=<span class=\"c-val\">\"gs-spinner gs-spinner--sm gs-spinner--white\"</span>\n       <span class=\"c-attr\">role</span>=<span class=\"c-val\">\"status\"</span> <span class=\"c-attr\">aria-hidden</span>=<span class=\"c-val\">\"true\"</span><span class=\"c-tag\">&gt;&lt;/div&gt;</span>\n  Saving…\n<span class=\"c-tag\">&lt;/button&gt;</span></code></pre></div></div>\n        </div>\n      </div>\n\n      <!-- 5 Reduced motion -->\n      <div id=\"sp-c-motion\" class=\"btn-family-card\">\n        <div class=\"ds-step-row\"><span class=\"ds-step-num\">5</span><div class=\"btn-family-title\" style=\"margin:0;\">Reduced Motion</div></div>\n        <div class=\"fw-react\">\n          <div class=\"btn-code-block\"><div class=\"btn-code-head\"><span class=\"btn-code-lang\">CSS</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sp-motion-r',this)\">Copy</button></div>\n          <div class=\"btn-code-body\"><pre id=\"sp-motion-r\"><code><span class=\"c-cmt\">/*\n * Architecture: ::before = static track, ::after = rotating arc.\n * Only ::after has animation-play-state — track never moves.\n */</span>\n<span class=\"c-attr\">@media</span> (prefers-reduced-motion: reduce) {\n  .gs-spinner::after {\n    animation-duration: 2s;              <span class=\"c-cmt\">/* slow rotation only    */</span>\n    animation-timing-function: steps(8, end); <span class=\"c-cmt\">/* stepped, less dizzying */</span>\n  }\n}</code></pre></div></div>\n        </div>\n        <div class=\"fw-angular\" style=\"display:none;\">\n          <div class=\"btn-code-block\"><div class=\"btn-code-head\"><span class=\"btn-code-lang\">CSS</span><button class=\"btn-copy-btn\" onclick=\"copyBtnCode('sp-motion-ng',this)\">Copy</button></div>\n          <div class=\"btn-code-body\"><pre id=\"sp-motion-ng\"><code><span class=\"c-cmt\">/* styles.css — architecture: ::before = static track, ::after = rotating arc */</span>\n<span class=\"c-attr\">@media</span> (prefers-reduced-motion: reduce) {\n  .gs-spinner::after {\n    animation-duration: 2s;\n    animation-timing-function: steps(8, end);\n  }\n}</code></pre></div></div>\n        </div>\n      </div>\n\n    </div><!-- /code-tab-main -->\n    <div class=\"code-tab-qnav\">\n      <div class=\"code-qnav-inner\">\n        <p class=\"code-qnav-title\">On This Page</p>\n        <ul class=\"code-qnav-list\">\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-c-overview')\">1 · Overview</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-c-import')\">2 · Import</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-c-api')\">3 · API / Props</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-c-basic')\">4 · Basic Usage</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-c-motion')\">5 · Reduced Motion</button></li>\n        </ul>\n      </div>\n    </div>\n  </div><!-- /code-tab-layout -->\n</div><!-- /spinner-tab-code -->\n\n<!-- ═══ USAGE TAB ════════════════════════════════════════════════ -->\n<div id=\"spinner-tab-usage\" class=\"btn-tab-pane spinner-tab-pane\">\n  <div class=\"code-tab-layout\">\n    <div class=\"code-tab-main\">\n\n      <div class=\"btn-family-card\">\n        <div class=\"btn-family-title\">When to Use</div>\n        <ul class=\"btn-usage-list\">\n          <li><strong>Unknown duration</strong> — whenever a process has no predictable end time (API call, file upload, route transition), use a Spinner. Use a Progress Bar when percentage completion is available.</li>\n          <li><strong>Background actions</strong> — form auto-save, live search, row-level operations like approvals or status changes that don't block the full page.</li>\n          <li><strong>Initial data load</strong> — place a centred md or lg spinner in a card or panel while the first data fetch resolves. Replace with a Skeleton for heavier layout previews.</li>\n        </ul>\n      </div>\n\n      <div class=\"btn-family-card\">\n        <div class=\"btn-family-title\">When Not to Use</div>\n        <ul class=\"btn-usage-list\">\n          <li><strong>Deterministic progress</strong> — if you can report percentage (file upload, multi-step wizard) use a Progress Bar instead.</li>\n          <li><strong>Initial page paint</strong> — for first meaningful paint, prefer a Skeleton Loader so users see layout structure before data arrives.</li>\n          <li><strong>Long-running operations (&gt;10s)</strong> — combine a spinner with status text; users need feedback that the system hasn't frozen.</li>\n        </ul>\n      </div>\n\n      <div class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Accessibility</div>\n        <ul class=\"btn-usage-list\">\n          <li>Always add <code>role=\"status\"</code> on the spinner element so screen readers announce state changes.</li>\n          <li>Include a visible or visually-hidden <code>aria-label</code> (e.g. <code>aria-label=\"Loading vessel data\"</code>) describing <em>what</em> is loading.</li>\n          <li>When the spinner is inside a button, set <code>aria-hidden=\"true\"</code> on the spinner itself — the button's accessible label (e.g. \"Saving…\") already conveys the state.</li>\n          <li>Honour <code>prefers-reduced-motion</code> — slow the animation to avoid triggering vestibular disorders.</li>\n        </ul>\n      </div>\n\n      <div class=\"btn-family-card\">\n        <div class=\"btn-family-title\">Anti-patterns</div>\n        <ul class=\"btn-usage-list\">\n          <li><strong>❌ Multiple spinners on the same screen</strong> — confusing and looks broken. Show one spinner per loading region. Use Skeletons for page-level parallel fetches.<br><strong>✅ Fix:</strong> one spinner per card or one full-page overlay — never both simultaneously.</li>\n          <li><strong>❌ Spinner without feedback for &gt;3s</strong> — users lose confidence.<br><strong>✅ Fix:</strong> after 3 seconds add a status message (\"Still loading…\"); after 10s offer a retry action.</li>\n          <li><strong>❌ Using xl spinner inline</strong> — xl is for full-page overlays only.<br><strong>✅ Fix:</strong> use sm inside buttons and table rows; md/lg for panels and cards.</li>\n        </ul>\n      </div>\n\n    </div><!-- /code-tab-main -->\n    <div class=\"code-tab-qnav\">\n      <div class=\"code-qnav-inner\">\n        <p class=\"code-qnav-title\">Quick Access</p>\n        <ul class=\"code-qnav-list\">\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-u-when')\">When to Use</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-u-not')\">When Not to Use</button></li>\n          <li class=\"code-qnav-item\"><button class=\"code-qnav-link\" onclick=\"scrollToSection('sp-u-a11y')\">Accessibility</button></li>\n        </ul>\n      </div>\n    </div>\n  </div><!-- /code-tab-layout -->\n</div><!-- /spinner-tab-usage -->\n";
})();